# ============================================================
# CHECK USERNAME
# ============================================================
@bp.route('/check-username', methods=['POST'])
def check_username():

    # --------------------------------------------------------
    # Get JSON safely
    # --------------------------------------------------------
    data = request.get_json(silent=True) or {}

    username = (data.get('username') or '').strip()

    # --------------------------------------------------------
    # Empty username
    # --------------------------------------------------------
    if not username:
        return jsonify({
            "taken": False,
            "valid": False,
            "message": "Username is required.",
            "suggestions": []
        })

    # --------------------------------------------------------
    # ALWAYS convert to lowercase
    #
    # ASAD -> asad
    # Asad -> asad
    # aSaD -> asad
    # --------------------------------------------------------
    username = username.lower()

    # --------------------------------------------------------
    # Length: 3 - 30
    # --------------------------------------------------------
    if len(username) < 3 or len(username) > 30:
        return jsonify({
            "taken": False,
            "valid": False,
            "message": (
                "Username-ku waa inuu u dhexeeyaa "
                "3 ilaa 30 characters."
            ),
            "suggestions": []
        })

    # --------------------------------------------------------
    # MUST start with a letter
    #
    # Allowed after first character:
    # letters
    # numbers
    # underscore
    # dot
    #
    # 134asad -> INVALID
    # _asad   -> INVALID
    # .asad   -> INVALID
    # asad    -> VALID
    # asad123 -> VALID
    # --------------------------------------------------------
    if not re.fullmatch(r'[a-z][a-z0-9._]{2,29}', username):
        return jsonify({
            "taken": False,
            "valid": False,
            "message": (
                "Username-ku waa inuu ku bilaabmaa letter, "
                "wuxuuna oggol yahay letters, numbers, "
                "underscore (_) iyo dot (.)."
            ),
            "suggestions": []
        })

    # --------------------------------------------------------
    # CASE-INSENSITIVE DATABASE CHECK
    #
    # ASAD = Asad = asad = aSaD
    # --------------------------------------------------------
    user = mongo.db.users.find_one({
        "username": {
            "$regex": f"^{re.escape(username)}$",
            "$options": "i"
        }
    })

    # --------------------------------------------------------
    # Username already taken
    # --------------------------------------------------------
    if user:

        suggestions = []
        attempts = 0

        while len(suggestions) < 3 and attempts < 100:
            attempts += 1

            suggestion = f"{username}{random.randint(10, 99)}"

            # Prevent duplicate suggestions
            if suggestion in suggestions:
                continue

            # Case-insensitive check
            existing = mongo.db.users.find_one({
                "username": {
                    "$regex": f"^{re.escape(suggestion)}$",
                    "$options": "i"
                }
            })

            if not existing:
                suggestions.append(suggestion)

        return jsonify({
            "taken": True,
            "valid": True,
            "username": username,
            "message": "Username is already taken.",
            "suggestions": suggestions
        })

    # --------------------------------------------------------
    # Username available
    # --------------------------------------------------------
    return jsonify({
        "taken": False,
        "valid": True,
        "username": username,
        "message": "Username is available.",
        "suggestions": []
    })
    
# ============================================================
# EMAIL DOMAIN / MX VALIDATION
# ============================================================

def is_valid_email_domain(email):

    try:

        if not email:
            return False

        # ----------------------------------------------------
        # Extract domain safely
        # ----------------------------------------------------
        parts = email.strip().lower().split('@')

        if len(parts) != 2:
            return False

        domain = parts[1].strip()

        if not domain:
            return False

        # ----------------------------------------------------
        # MX RECORD CHECK
        # ----------------------------------------------------
        records = dns.resolver.resolve(
            domain,
            'MX',
            lifetime=5
        )

        return bool(records)

    except (
        dns.resolver.NoAnswer,
        dns.resolver.NXDOMAIN,
        dns.resolver.NoNameservers,
        dns.resolver.Timeout
    ):

        return False

    except Exception as e:

        print(
            "EMAIL DOMAIN CHECK ERROR:",
            repr(e)
        )

        return False


