@bp.route('/register', methods=['GET', 'POST'])
def register():

    # --------------------------------------------------------
    # Already logged in
    # --------------------------------------------------------
    if current_user.is_authenticated:
        return redirect(
            url_for('main.dashboard')
        )

    # ========================================================
    # POST
    # ========================================================

    if request.method == 'POST':

        # ----------------------------------------------------
        # GET FORM VALUES SAFELY
        # ----------------------------------------------------

        username = (
            request.form.get('username') or ''
        ).strip()

        fullname = (
            request.form.get('fullname') or ''
        ).strip()

        email = (
            request.form.get('email') or ''
        ).strip().lower()

        password = (
            request.form.get('password') or ''
        )

        confirm_password = (
            request.form.get('password_confirmation') or ''
        )

        terms = request.form.get('terms')

        # ====================================================
        # 1. USERNAME REQUIRED
        # ====================================================

        if not username:

            flash(
                "Fadlan geli username-ka!",
                "danger"
            )

            return redirect(
                url_for('main.register')
            )

        # ====================================================
        # 2. USERNAME LENGTH
        # ====================================================

        if len(username) < 3 or len(username) > 30:

            flash(
                "Username-ku waa inuu u dhexeeyaa 3 ilaa 30 characters!",
                "danger"
            )

            return redirect(
                url_for('main.register')
            )

        # ====================================================
        # 3. USERNAME CHARACTERS
        # ====================================================

        if not re.fullmatch(
            r'[A-Za-z0-9._]+',
            username
        ):

            flash(
                "Username-ku wuxuu oggol yahay letters, numbers, underscore (_) iyo dot (.) oo keliya!",
                "danger"
            )

            return redirect(
                url_for('main.register')
            )

        # ====================================================
        # 4. FULL NAME REQUIRED
        # ====================================================

        if not fullname:

            flash(
                "Fadlan geli Full Name-ka!",
                "danger"
            )

            return redirect(
                url_for('main.register')
            )

        # ====================================================
        # 5. FULL NAME LENGTH
        # ====================================================

        if len(fullname) < 2 or len(fullname) > 100:

            flash(
                "Full Name-ku waa inuu u dhexeeyaa 2 ilaa 100 characters!",
                "danger"
            )

            return redirect(
                url_for('main.register')
            )

        # ====================================================
        # 6. FULL NAME VALIDATION
        #
        # Allowed:
        # Letters
        # Spaces
        # Apostrophe
        # Hyphen
        #
        # Numbers lama oggola.
        # ====================================================

        fullname_pattern = (
            r"^[^\W\d_]+"
            r"(?:[ '\u2019-][^\W\d_]+)*$"
        )

        if not re.fullmatch(
            fullname_pattern,
            fullname,
            flags=re.UNICODE
        ):

            flash(
                "Full Name-ku wuxuu oggol yahay letters, spaces, apostrophe iyo hyphen oo keliya. Numbers lama oggola!",
                "danger"
            )

            return redirect(
                url_for('main.register')
            )

        # ====================================================
        # 7. EMAIL REQUIRED
        # ====================================================

        if not email:

            flash(
                "Fadlan geli email-kaaga!",
                "danger"
            )

            return redirect(
                url_for('main.register')
            )

        # ====================================================
        # 8. EMAIL LENGTH
        # ====================================================

        if len(email) > 254:

            flash(
                "Email-ku aad ayuu u dheer yahay!",
                "danger"
            )

            return redirect(
                url_for('main.register')
            )

        # ====================================================
        # 9. EMAIL FORMAT
        # ====================================================

        email_pattern = (
            r"^[A-Za-z0-9.!#$%&'*+/=?^_`{|}~-]+"
            r"@"
            r"[A-Za-z0-9]"
            r"(?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?"
            r"(?:\.[A-Za-z0-9]"
            r"(?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?)+$"
        )

        if not re.fullmatch(
            email_pattern,
            email
        ):

            flash(
                "Fadlan geli email sax ah!",
                "danger"
            )

            return redirect(
                url_for('main.register')
            )

        # ====================================================
        # 10. EMAIL MX CHECK
        # ====================================================

        if not is_valid_email_domain(email):

            flash(
                "Email-kan domain-kiisu ma jiro ama ma aqbalo email!",
                "danger"
            )

            return redirect(
                url_for('main.register')
            )

        # ====================================================
        # 11. TERMS REQUIRED
        # ====================================================

        if terms not in [
            '1',
            'true',
            'on',
            'yes'
        ]:

            flash(
                "Fadlan aqbal Terms & Conditions-ka!",
                "danger"
            )

            return redirect(
                url_for('main.register')
            )

        # ====================================================
        # 12. PASSWORD REQUIRED
        # ====================================================

        if not password:

            flash(
                "Fadlan geli password-ka!",
                "danger"
            )

            return redirect(
                url_for('main.register')
            )

        # ====================================================
        # 13. PASSWORD LENGTH
        # ====================================================

        if len(password) < 8:

            flash(
                "Password-ku waa inuu leeyahay ugu yaraan 8 characters!",
                "danger"
            )

            return redirect(
                url_for('main.register')
            )

        if len(password) > 128:

            flash(
                "Password-ku kama badnaan karo 128 characters!",
                "danger"
            )

            return redirect(
                url_for('main.register')
            )

        # ====================================================
        # 14. PASSWORD UPPERCASE
        # ====================================================

        if not re.search(
            r'[A-Z]',
            password
        ):

            flash(
                "Password-ku waa inuu leeyahay ugu yaraan hal uppercase letter!",
                "danger"
            )

            return redirect(
                url_for('main.register')
            )

        # ====================================================
        # 15. PASSWORD LOWERCASE
        # ====================================================

        if not re.search(
            r'[a-z]',
            password
        ):

            flash(
                "Password-ku waa inuu leeyahay ugu yaraan hal lowercase letter!",
                "danger"
            )

            return redirect(
                url_for('main.register')
            )

        # ====================================================
        # 16. PASSWORD NUMBER
        # ====================================================

        if not re.search(
            r'\d',
            password
        ):

            flash(
                "Password-ku waa inuu leeyahay ugu yaraan hal number!",
                "danger"
            )

            return redirect(
                url_for('main.register')
            )

        # ====================================================
        # 17. PASSWORD SPECIAL CHARACTER
        # ====================================================

        if not re.search(
            r'[^A-Za-z0-9]',
            password
        ):

            flash(
                "Password-ku waa inuu leeyahay ugu yaraan hal special character!",
                "danger"
            )

            return redirect(
                url_for('main.register')
            )

        # ====================================================
        # 18. CONFIRM PASSWORD REQUIRED
        # ====================================================

        if not confirm_password:

            flash(
                "Fadlan xaqiiji password-ka!",
                "danger"
            )

            return redirect(
                url_for('main.register')
            )

        # ====================================================
        # 19. PASSWORD MATCH
        # ====================================================

        if password != confirm_password:

            flash(
                "Passwords-ka isma laha!",
                "danger"
            )

            return redirect(
                url_for('main.register')
            )

        # ====================================================
        # 20. CHECK DUPLICATE EMAIL
        # ====================================================

        existing_email = mongo.db.users.find_one({
            "email": email
        })

        if existing_email:

            flash(
                "Email-kan horey ayaa loo isticmaalay!",
                "danger"
            )

            return redirect(
                url_for('main.register')
            )

        # ====================================================
        # 21. CHECK DUPLICATE USERNAME
        # ====================================================

        existing_username = mongo.db.users.find_one({
            "username": username
        })

        if existing_username:

            flash(
                "Username-kan horey ayaa loo qaatay, fadlan mid kale dooro!",
                "danger"
            )

            return redirect(
                url_for('main.register')
            )

        # ====================================================
        # 22. ROLE LOGIC
        # ====================================================

        user_count = mongo.db.users.count_documents({})

        if user_count == 0:

            role = UserRole.superadmin.value

        else:

            role = UserRole.admin.value

        # ====================================================
        # 23. CREATE USER
        # ====================================================

        new_user = {
            "fullname": fullname,
            "username": username,
            "email": email,
            "password": generate_password_hash(password),
            "role": role,
            "status": True,
            "created_at": datetime.utcnow()
        }

        # ====================================================
        # 24. SAVE USER
        # ====================================================

        try:

            mongo.db.users.insert_one(
                new_user
            )

        except Exception as e:

            print(
                "REGISTER INSERT ERROR:",
                repr(e)
            )

            flash(
                "Account-ka lama abuuri karin. Fadlan isku day mar kale!",
                "danger"
            )

            return redirect(
                url_for('main.register')
            )

        # ====================================================
        # 25. SUCCESS
        # ====================================================

        flash(
            "Diiwaangelinta way guulaysatay! Hadda waad login-gareyn kartaa.",
            "success"
        )

        return redirect(
            url_for('main.login')
        )

    # ========================================================
    # GET REGISTER PAGE
    # ========================================================

    return render_template(
        "backend/auth/auth-register.html"
    )


# ============================================================
# LOGIN
# ============================================================


@bp.route("/login", methods=["GET", "POST"])
def login():

    # --------------------------------------------------------
    # ALREADY LOGGED IN
    # --------------------------------------------------------

    if current_user.is_authenticated:
        return redirect(
            url_for("main.dashboard")
        )


    # --------------------------------------------------------
    # GET
    # --------------------------------------------------------

    if request.method == "GET":

        return render_template(
            "backend/auth/auth-login.html",
            error_message=None,
            success_message=None
        )


    # ========================================================
    # POST
    # ========================================================

    login_value = request.form.get(
        "login",
        ""
    ).strip()

    password = request.form.get(
        "password",
        ""
    )

    remember = (
        request.form.get("remember")
        in ["1", "true", "on", "yes"]
    )


    # ========================================================
    # EMPTY LOGIN
    # ========================================================

    if not login_value:

        return render_template(
            "backend/auth/auth-login.html",
            error_message="Fadlan geli Username, Email ama Phone.",
            success_message=None
        )


    # ========================================================
    # EMPTY PASSWORD
    # ========================================================

    if not password:

        return render_template(
            "backend/auth/auth-login.html",
            error_message="Fadlan geli Password-ka.",
            success_message=None
        )


    # ========================================================
    # NORMALIZE
    # ========================================================

    login_value = login_value.strip()

    login_lower = login_value.lower()


    # ========================================================
    # FIND USER
    # ========================================================

    user_data = None


    # --------------------------------------------------------
    # USERNAME
    # --------------------------------------------------------

    try:

        user_data = mongo.db.users.find_one({
            "username": login_value
        })

    except Exception as e:

        print(
            "LOGIN USERNAME SEARCH ERROR:",
            repr(e)
        )

        return render_template(
            "backend/auth/auth-login.html",
            error_message="Database error ayaa dhacay.",
            success_message=None
        )


    # --------------------------------------------------------
    # EMAIL
    # --------------------------------------------------------

    if user_data is None:

        try:

            user_data = mongo.db.users.find_one({
                "email": login_lower
            })

        except Exception as e:

            print(
                "LOGIN EMAIL SEARCH ERROR:",
                repr(e)
            )

            return render_template(
                "backend/auth/auth-login.html",
                error_message="Database error ayaa dhacay.",
                success_message=None
            )


    # --------------------------------------------------------
    # PHONE
    # --------------------------------------------------------

    if user_data is None:

        try:

            user_data = mongo.db.users.find_one({
                "phone": login_value
            })

        except Exception as e:

            print(
                "LOGIN PHONE SEARCH ERROR:",
                repr(e)
            )

            return render_template(
                "backend/auth/auth-login.html",
                error_message="Database error ayaa dhacay.",
                success_message=None
            )


    # ========================================================
    # USER NOT FOUND
    # ========================================================

    if user_data is None:

        return render_template(
            "backend/auth/auth-login.html",
            error_message=(
                "Username, Email ama Phone "
                "waa khaldan yahay."
            ),
            success_message=None
        )


    # ========================================================
    # USER ID
    # ========================================================

    user_id = user_data.get("_id")


    # ========================================================
    # ACCOUNT STATUS
    # ========================================================

    status = user_data.get(
        "status",
        True
    )


    if status in [
        False,
        0,
        "false",
        "False",
        "inactive",
        "disabled",
        "blocked"
    ]:

        return render_template(
            "backend/auth/auth-login.html",
            error_message=(
                "Account-kaaga waa disabled "
                "ama blocked."
            ),
            success_message=None
        )


    # ========================================================
    # PASSWORD FROM DATABASE
    # ========================================================

    stored_password = user_data.get(
        "password"
    )


    if not stored_password:

        return render_template(
            "backend/auth/auth-login.html",
            error_message=(
                "Account-kan password kuma jiro "
                "database-ka."
            ),
            success_message=None
        )


    # ========================================================
    # CHECK PASSWORD
    # ========================================================

    try:

        password_valid = check_password_hash(
            stored_password,
            password
        )

    except Exception as e:

        print(
            "PASSWORD HASH ERROR:",
            repr(e)
        )

        return render_template(
            "backend/auth/auth-login.html",
            error_message=(
                "Password-ka database-ka "
                "si sax ah looma kaydin."
            ),
            success_message=None
        )


    # ========================================================
    # WRONG PASSWORD
    # ========================================================

    if not password_valid:

        try:

            mongo.db.users.update_one(
                {
                    "_id": user_id
                },
                {
                    "$inc": {
                        "failed_login_attempts": 1
                    }
                }
            )

        except Exception as e:

            print(
                "FAILED LOGIN UPDATE ERROR:",
                repr(e)
            )


        return render_template(
            "backend/auth/auth-login.html",
            error_message="Password-ka waa khaldan yahay.",
            success_message=None
        )


    # ========================================================
    # RESET FAILED ATTEMPTS
    # ========================================================

    try:

        mongo.db.users.update_one(
            {
                "_id": user_id
            },
            {
                "$set": {
                    "failed_login_attempts": 0
                }
            }
        )

    except Exception as e:

        print(
            "RESET FAILED LOGIN ERROR:",
            repr(e)
        )


    # ========================================================
    # CREATE USER OBJECT
    # ========================================================

    try:

        user = User(
            user_data
        )

    except Exception as e:

        print(
            "USER OBJECT ERROR:",
            repr(e)
        )

        return render_template(
            "backend/auth/auth-login.html",
            error_message=(
                "User account-ka lama diyaarin karin."
            ),
            success_message=None
        )


    # ========================================================
    # LOGIN USER
    # ========================================================

    try:

        login_user(
            user,
            remember=remember
        )

    except Exception as e:

        print(
            "FLASK LOGIN ERROR:",
            repr(e)
        )

        return render_template(
            "backend/auth/auth-login.html",
            error_message=(
                "Login session lama abuuri karin."
            ),
            success_message=None
        )


    # ========================================================
    # UPDATE LOGIN DATA
    # ========================================================

    try:

        from datetime import datetime
        from uuid import uuid4

        login_time = datetime.utcnow()

        session_token = str(
            uuid4()
        )

        ip_address = (
            request.headers.get(
                "X-Forwarded-For"
            )
            or request.remote_addr
            or "Unknown"
        )

        if "," in ip_address:

            ip_address = (
                ip_address
                .split(",")[0]
                .strip()
            )


        user_agent = (
            request.headers.get(
                "User-Agent"
            )
            or "Unknown"
        )


        mongo.db.users.update_one(

            {
                "_id": user_id
            },

            {
                "$set": {

                    "auth_status": "login",

                    "session_token": session_token,

                    "login_time": login_time,

                    "last_seen": login_time,

                    "last_active": login_time,

                    "last_login_ip": ip_address,

                    "device": user_agent

                }
            }

        )

    except Exception as e:

        print(
            "LOGIN DATA UPDATE ERROR:",
            repr(e)
        )


    # ========================================================
    # SUCCESS
    # ========================================================

    return redirect(
        url_for(
            "main.dashboard"
        )
    )


