# ============================================================
# DEVICE / BROWSER / PLATFORM DETECTOR
# ============================================================

def get_device_info(user_agent):

    ua = (user_agent or "").lower()

    # ========================================================
    # PLATFORM
    # ========================================================

    if "windows" in ua:
        platform = "Windows"

    elif "android" in ua:
        platform = "Android"

    elif "iphone" in ua:
        platform = "iOS"

    elif "ipad" in ua:
        platform = "iPadOS"

    elif "mac os x" in ua or "macintosh" in ua:
        platform = "macOS"

    elif "linux" in ua:
        platform = "Linux"

    else:
        platform = "Unknown"


    # ========================================================
    # DEVICE
    # ========================================================

    if "ipad" in ua or "tablet" in ua:

        device = "Tablet"

    elif (
        "mobile" in ua
        or "android" in ua
        or "iphone" in ua
    ):

        device = "Mobile"

    else:

        device = "Desktop"


    # ========================================================
    # BROWSER
    # ========================================================

    # Microsoft Edge must be checked before Chrome

    if "edg/" in ua or "edge/" in ua:

        browser = "Microsoft Edge"

    elif "opr/" in ua or "opera" in ua:

        browser = "Opera"

    elif "firefox/" in ua:

        browser = "Mozilla Firefox"

    elif "chrome/" in ua:

        browser = "Google Chrome"

    elif "safari/" in ua:

        browser = "Safari"

    else:

        browser = "Unknown"


    # ========================================================
    # DEVICE NAME
    # ========================================================

    if platform == "Windows":

        device_name = "Windows PC"

    elif platform == "macOS":

        device_name = "Mac"

    elif platform == "Android":

        device_name = "Android Device"

    elif platform == "iOS":

        device_name = "iPhone"

    elif platform == "iPadOS":

        device_name = "iPad"

    elif platform == "Linux":

        device_name = "Linux PC"

    else:

        device_name = "Unknown Device"


    # ========================================================
    # INTERFACE
    # ========================================================

    interface_name = "Web Browser"


    # ========================================================
    # RETURN
    # ========================================================

    return {
        "device": device,
        "device_name": device_name,
        "browser": browser,
        "platform": platform,
        "interface_name": interface_name
    }


