@bp.route("/profile", methods=["GET"])
@login_required
def profile():

    from bson import ObjectId
    from datetime import datetime

    # ========================================================
    # CURRENT USER ID
    # ========================================================

    try:

        user_id = ObjectId(
            str(current_user.id)
        )

    except Exception:

        flash(
            "Invalid user account.",
            "danger"
        )

        return redirect(
            url_for("main.dashboard")
        )


    # ========================================================
    # GET LATEST USER FROM MONGODB
    # ========================================================

    user_data = mongo.db.users.find_one(
        {
            "_id": user_id
        }
    )


    # ========================================================
    # USER NOT FOUND
    # ========================================================

    if not user_data:

        flash(
            "User account not found.",
            "danger"
        )

        return redirect(
            url_for("main.dashboard")
        )


    # ========================================================
    # CURRENT USER AGENT
    # ========================================================

    current_user_agent = request.headers.get(
        "User-Agent",
        ""
    )


    # ========================================================
    # GET DEVICE INFORMATION
    # ========================================================

    device_info = get_device_info(
        current_user_agent
    )


    # ========================================================
    # FIX MISSING DEVICE INFORMATION
    #
    # Haddii MongoDB horey u lahaa:
    #
    # device = None
    # browser = None
    # platform = None
    #
    # profile-ka hadda wuxuu isticmaali karaa
    # current browser information.
    # ========================================================

    device = (
        user_data.get("device")
        or device_info["device"]
    )

    device_name = (
        user_data.get("device_name")
        or device_info["device_name"]
    )

    browser = (
        user_data.get("browser")
        or device_info["browser"]
    )

    platform = (
        user_data.get("platform")
        or device_info["platform"]
    )

    interface_name = (
        user_data.get("interface_name")
        or device_info["interface_name"]
    )


    # ========================================================
    # BUILD PROFILE DATA
    #
    # Waxaan sameyneynaa copy si aan database object-ka
    # original-ka u beddelin.
    # ========================================================

    profile_data = dict(user_data)


    profile_data["device"] = device
    profile_data["device_name"] = device_name
    profile_data["browser"] = browser
    profile_data["platform"] = platform
    profile_data["interface_name"] = interface_name


    # ========================================================
    # AUTH STATUS
    # ========================================================

    profile_data["auth_status"] = (
        user_data.get("auth_status")
        or "login"
    )


    # ========================================================
    # AUTH PROVIDER
    # ========================================================

    profile_data["auth_provider"] = (
        user_data.get("auth_provider")
        or "local"
    )


    # ========================================================
    # PASSWORD SECURITY
    # ========================================================

    profile_data["last_password_change"] = (
        user_data.get(
            "last_password_change"
        )
    )

    profile_data["password_changed_ip"] = (
        user_data.get(
            "password_changed_ip"
        )
    )

    profile_data["password_changed_user_agent"] = (
        user_data.get(
            "password_changed_user_agent"
        )
    )


    # ========================================================
    # LOGIN INFORMATION
    # ========================================================

    profile_data["last_login_ip"] = (
        user_data.get(
            "last_login_ip"
        )
    )

    profile_data["last_active"] = (
        user_data.get(
            "last_active"
        )
    )

    profile_data["login_time"] = (
        user_data.get(
            "login_time"
        )
    )

    profile_data["failed_login_attempts"] = (
        user_data.get(
            "failed_login_attempts",
            0
        )
    )


    # ========================================================
    # VERIFICATION
    # ========================================================

    profile_data["is_verified"] = (
        user_data.get(
            "is_verified",
            False
        )
    )

    profile_data["phone_verified"] = (
        user_data.get(
            "phone_verified",
            False
        )
    )

    profile_data["two_factor_enabled"] = (
        user_data.get(
            "two_factor_enabled",
            False
        )
    )


    # ========================================================
    # PHOTO VISIBILITY
    # ========================================================

    profile_data["photo_visibility"] = (
        user_data.get(
            "photo_visibility",
            "everyone"
        )
    )


    # ========================================================
    # STATUS
    # ========================================================

    profile_data["status"] = (
        user_data.get(
            "status",
            True
        )
    )


    # ========================================================
    # REFRESH CURRENT USER
    # ========================================================

    current_user.data = profile_data


    # ========================================================
    # BUILD USER OBJECT
    # ========================================================

    user = User(
        profile_data
    )


    # ========================================================
    # EXTRA ATTRIBUTES
    #
    # User class-ka haddii fields-kan uusan constructor-ka
    # ku jirin, si toos ah ayaan ugu dari karnaa object-ka.
    # ========================================================

    user.last_password_change = (
        profile_data.get(
            "last_password_change"
        )
    )

    user.password_changed_ip = (
        profile_data.get(
            "password_changed_ip"
        )
    )

    user.password_changed_user_agent = (
        profile_data.get(
            "password_changed_user_agent"
        )
    )


    # ========================================================
    # PROFILE PAGE
    # ========================================================

    return render_template(
        "backend/pages/components/users/profile.html",
        user=user
    )



@bp.route("/change-password/check-current", methods=["POST"])
@login_required
def check_current_password():

    from bson import ObjectId
    from werkzeug.security import check_password_hash

    try:
        user_id = ObjectId(str(current_user.id))
    except Exception:
        return jsonify({
            "success": False,
            "valid": False,
            "message": "Invalid user account."
        }), 400

    data = request.get_json(silent=True) or {}

    current_password = data.get("current_password") or ""

    if not current_password:
        return jsonify({
            "success": True,
            "valid": False,
            "message": ""
        })

    user_data = mongo.db.users.find_one({
        "_id": user_id
    })

    if not user_data:
        return jsonify({
            "success": False,
            "valid": False,
            "message": "User account not found."
        }), 404

    stored_password = user_data.get("password")

    if not stored_password:
        return jsonify({
            "success": False,
            "valid": False,
            "message": "No valid password found."
        }), 400

    try:
        password_valid = check_password_hash(
            stored_password,
            current_password
        )
    except Exception:
        password_valid = False

    if password_valid:

        return jsonify({
            "success": True,
            "valid": True,
            "message": "Current password is correct."
        })

    return jsonify({
        "success": True,
        "valid": False,
        "message": "Current password is incorrect."
    })



# ============================================================
# CHANGE PASSWORD
# ============================================================

@bp.route("/change-password", methods=["GET", "POST"])
@login_required
def change_password():

    from bson import ObjectId
    from datetime import datetime
    from werkzeug.security import (
        check_password_hash,
        generate_password_hash
    )

    # ========================================================
    # CURRENT USER ID
    # ========================================================

    try:
        user_id = ObjectId(str(current_user.id))

    except Exception:

        flash(
            "Invalid user account.",
            "danger"
        )

        return redirect(
            url_for("main.dashboard")
        )

    # ========================================================
    # GET CURRENT USER
    # ========================================================

    user_data = mongo.db.users.find_one(
        {
            "_id": user_id
        }
    )

    if not user_data:

        flash(
            "User account not found.",
            "danger"
        )

        return redirect(
            url_for("main.dashboard")
        )

    # ========================================================
    # GET
    # ========================================================

    if request.method == "GET":

        user = User(user_data)

        # Password history
        password_history = list(
            mongo.db.password_change_logs.find(
                {
                    "user_id": user_id
                }
            ).sort(
                "changed_at",
                -1
            ).limit(10)
        )

        return render_template(
            "backend/pages/components/users/change_password.html",
            user=user,
            password_history=password_history
        )

    # ========================================================
    # POST DATA
    # ========================================================

    old_password = request.form.get(
        "old_password",
        ""
    ).strip()

    new_password = request.form.get(
        "new_password",
        ""
    )

    confirm_password = request.form.get(
        "confirm_password",
        ""
    )

    # ========================================================
    # REQUIRED FIELDS
    # ========================================================

    if not old_password:

        flash(
            "Please enter your current password.",
            "danger"
        )

        return redirect(
            url_for("main.change_password")
        )

    if not new_password:

        flash(
            "Please enter your new password.",
            "danger"
        )

        return redirect(
            url_for("main.change_password")
        )

    if not confirm_password:

        flash(
            "Please confirm your new password.",
            "danger"
        )

        return redirect(
            url_for("main.change_password")
        )

    # ========================================================
    # CONFIRM PASSWORD
    # ========================================================

    if new_password != confirm_password:

        flash(
            "New passwords do not match.",
            "danger"
        )

        return redirect(
            url_for("main.change_password")
        )

    # ========================================================
    # STORED PASSWORD
    # ========================================================

    stored_password = user_data.get("password")

    if not stored_password:

        flash(
            "Your account does not have a valid password. Please contact the administrator.",
            "danger"
        )

        return redirect(
            url_for("main.change_password")
        )

    # ========================================================
    # VERIFY CURRENT PASSWORD
    # IMPORTANT
    # ========================================================

    try:

        password_valid = check_password_hash(
            str(stored_password),
            old_password
        )

    except Exception as e:

        print(
            "CURRENT PASSWORD VERIFY ERROR:",
            repr(e)
        )

        password_valid = False

    if not password_valid:

        flash(
            "Current password is incorrect.",
            "danger"
        )

        return redirect(
            url_for("main.change_password")
        )

    # ========================================================
    # NEW PASSWORD MUST BE DIFFERENT
    # ========================================================

    try:

        same_password = check_password_hash(
            str(stored_password),
            new_password
        )

    except Exception:

        same_password = False

    if same_password:

        flash(
            "New password must be different from your current password.",
            "danger"
        )

        return redirect(
            url_for("main.change_password")
        )

    # ========================================================
    # PASSWORD LENGTH
    # ========================================================

    if len(new_password) < 8:

        flash(
            "Password must be at least 8 characters long.",
            "danger"
        )

        return redirect(
            url_for("main.change_password")
        )

    # ========================================================
    # UPPERCASE
    # ========================================================

    if not any(
        char.isupper()
        for char in new_password
    ):

        flash(
            "Password must contain at least one uppercase letter.",
            "danger"
        )

        return redirect(
            url_for("main.change_password")
        )

    # ========================================================
    # LOWERCASE
    # ========================================================

    if not any(
        char.islower()
        for char in new_password
    ):

        flash(
            "Password must contain at least one lowercase letter.",
            "danger"
        )

        return redirect(
            url_for("main.change_password")
        )

    # ========================================================
    # NUMBER
    # ========================================================

    if not any(
        char.isdigit()
        for char in new_password
    ):

        flash(
            "Password must contain at least one number.",
            "danger"
        )

        return redirect(
            url_for("main.change_password")
        )

    # ========================================================
    # HASH NEW PASSWORD
    # ========================================================

    try:

        hashed_password = generate_password_hash(
            new_password
        )

    except Exception as e:

        print(
            "PASSWORD HASH ERROR:",
            repr(e)
        )

        flash(
            "Unable to secure your new password.",
            "danger"
        )

        return redirect(
            url_for("main.change_password")
        )

    # ========================================================
    # CURRENT TIME
    # ========================================================

    now = datetime.utcnow()

    # ========================================================
    # IP ADDRESS
    # ========================================================

    ip_address = request.headers.get(
        "X-Forwarded-For"
    )

    if ip_address:

        ip_address = ip_address.split(",")[0].strip()

    else:

        ip_address = request.remote_addr or "Unknown"

    # ========================================================
    # USER AGENT
    # ========================================================

    user_agent = request.headers.get(
        "User-Agent",
        ""
    )

    # ========================================================
    # DEVICE INFORMATION
    # ========================================================

    device_info = get_device_info(
        user_agent
    )

    device = device_info.get(
        "device"
    )

    browser = device_info.get(
        "browser"
    )

    platform = device_info.get(
        "platform"
    )

    device_name = device_info.get(
        "device_name"
    )

    interface_name = device_info.get(
        "interface_name"
    )

    # ========================================================
    # UPDATE USER
    # ========================================================

    try:

        result = mongo.db.users.update_one(
            {
                "_id": user_id
            },
            {
                "$set": {

                    "password": hashed_password,

                    "last_password_change": now,

                    "password_changed_ip": ip_address,

                    "password_changed_user_agent": user_agent,

                    "device": device,

                    "device_name": device_name,

                    "browser": browser,

                    "platform": platform,

                    "interface_name": interface_name,

                    "updated_at": now
                }
            }
        )

    except Exception as e:

        print(
            "PASSWORD UPDATE ERROR:",
            repr(e)
        )

        flash(
            "Unable to change password. Please try again.",
            "danger"
        )

        return redirect(
            url_for("main.change_password")
        )

    # ========================================================
    # CHECK UPDATE
    # ========================================================

    if result.matched_count == 0:

        flash(
            "Password could not be changed.",
            "danger"
        )

        return redirect(
            url_for("main.change_password")
        )

    # ========================================================
    # PASSWORD CHANGE LOG
    # ========================================================

    try:

        mongo.db.password_change_logs.insert_one(
            {
                "user_id": user_id,

                "username": user_data.get(
                    "username"
                ),

                "fullname": user_data.get(
                    "fullname"
                ),

                "email": user_data.get(
                    "email"
                ),

                "auth_provider": user_data.get(
                    "auth_provider",
                    "local"
                ),

                "action": "password_changed",

                "changed_at": now,

                "created_at": now,

                "ip_address": ip_address,

                "user_agent": user_agent,

                "device": device,

                "device_name": device_name,

                "browser": browser,

                "platform": platform,

                "interface_name": interface_name
            }
        )

    except Exception as e:

        print(
            "PASSWORD LOG ERROR:",
            repr(e)
        )

    # ========================================================
    # REFRESH CURRENT USER
    # ========================================================

    updated_user_data = mongo.db.users.find_one(
        {
            "_id": user_id
        }
    )

    if updated_user_data:

        current_user.data = updated_user_data

        current_user.password = updated_user_data.get(
            "password"
        )

        current_user.updated_at = updated_user_data.get(
            "updated_at"
        )

        current_user.last_password_change = (
            updated_user_data.get(
                "last_password_change"
            )
        )

        current_user.password_changed_ip = (
            updated_user_data.get(
                "password_changed_ip"
            )
        )

        current_user.password_changed_user_agent = (
            updated_user_data.get(
                "password_changed_user_agent"
            )
        )

        current_user.device = updated_user_data.get(
            "device"
        )

        current_user.device_name = updated_user_data.get(
            "device_name"
        )

        current_user.browser = updated_user_data.get(
            "browser"
        )

        current_user.platform = updated_user_data.get(
            "platform"
        )

        current_user.interface_name = (
            updated_user_data.get(
                "interface_name"
            )
        )

    # ========================================================
    # SUCCESS
    # ========================================================

    flash(
        "Password changed successfully.",
        "success"
    )

    return redirect(
        url_for("main.change_password")
    )


