@bp.route("/account-settings", methods=["GET", "POST"])
@login_required
def account_settings():

    from bson import ObjectId
    from datetime import datetime

    # ========================================================
    # CURRENT USER ID
    # ========================================================

    try:
        current_user_id = ObjectId(str(current_user.id))
    except Exception:
        flash("Invalid user account.", "error")
        return redirect(url_for("main.dashboard"))

    # ========================================================
    # GET USER FROM MONGODB
    # ========================================================

    user = mongo.db.users.find_one({
        "_id": current_user_id
    })

    if not user:
        flash("User account not found.", "error")
        return redirect(url_for("main.dashboard"))

    # ========================================================
    # POST - UPDATE ACCOUNT
    # ========================================================

    if request.method == "POST":

        try:

            # ====================================================
            # BASIC INFORMATION
            # ====================================================

            fullname = request.form.get("fullname", "").strip()
            username = request.form.get("username", "").strip()

            phone = request.form.get("phone", "").strip()
            country = request.form.get("country", "").strip()
            state = request.form.get("state", "").strip()
            city = request.form.get("city", "").strip()
            address = request.form.get("address", "").strip()
            bio = request.form.get("bio", "").strip()

            gender = request.form.get("gender", "").strip()
            photo_visibility = request.form.get(
                "photo_visibility",
                "everyone"
            ).strip()

            # ====================================================
            # SOCIAL ACCOUNTS
            # ====================================================

            facebook = request.form.get("facebook", "").strip()
            twitter = request.form.get("twitter", "").strip()
            google = request.form.get("google", "").strip()
            whatsapp = request.form.get("whatsapp", "").strip()
            instagram = request.form.get("instagram", "").strip()
            github = request.form.get("github", "").strip()

            # ====================================================
            # VALIDATION
            # ====================================================

            if not fullname:
                flash("Full name is required.", "error")
                return render_template(
                    "backend/pages/components/users/account_settings.html",
                    user=User(user)
                )

            if not username:
                flash("Username is required.", "error")
                return render_template(
                    "backend/pages/components/users/account_settings.html",
                    user=User(user)
                )

            # ====================================================
            # USERNAME DUPLICATE CHECK
            # ====================================================

            existing_username = mongo.db.users.find_one({
                "username": username,
                "_id": {
                    "$ne": current_user_id
                }
            })

            if existing_username:

                flash(
                    "This username is already taken.",
                    "error"
                )

                return render_template(
                    "backend/pages/components/users/account_settings.html",
                    user=User(user)
                )

            # ====================================================
            # PHOTO VISIBILITY VALIDATION
            # ====================================================

            allowed_visibility = [
                "everyone",
                "friends",
                "only_me"
            ]

            if photo_visibility not in allowed_visibility:
                photo_visibility = "everyone"

            # ====================================================
            # UPDATE DATA
            # ====================================================

            data = {
                "fullname": fullname,
                "username": username,

                "phone": phone,
                "country": country,
                "state": state,
                "city": city,
                "address": address,
                "bio": bio,

                "gender": gender,
                "photo_visibility": photo_visibility,

                # Social accounts
                "facebook": facebook,
                "twitter": twitter,
                "google": google,
                "whatsapp": whatsapp,
                "instagram": instagram,
                "github": github,

                # Timestamp
                "updated_at": datetime.utcnow()
            }

            # ====================================================
            # PROFILE PHOTO
            # ====================================================

            file = request.files.get("photo")

            if file and file.filename:

                upload_result = cloudinary.uploader.upload(
                    file,
                    folder="users",
                    resource_type="image"
                )

                photo_url = upload_result.get("secure_url")

                if photo_url:
                    data["photo"] = photo_url

            # ====================================================
            # UPDATE MONGODB
            # ====================================================

            result = mongo.db.users.update_one(
                {
                    "_id": current_user_id
                },
                {
                    "$set": data
                }
            )

            # ====================================================
            # CHECK UPDATE
            # ====================================================

            if result.matched_count == 0:

                flash(
                    "User account could not be found.",
                    "error"
                )

                return redirect(
                    url_for("main.account_settings")
                )

            # ====================================================
            # REFRESH CURRENT USER
            # ====================================================

            updated_user = mongo.db.users.find_one({
                "_id": current_user_id
            })

            if updated_user:

                # Update Flask-Login current user object
                current_user.data = updated_user

                current_user.username = updated_user.get(
                    "username"
                )

                current_user.fullname = updated_user.get(
                    "fullname"
                )

                current_user.email = updated_user.get(
                    "email"
                )

                current_user.phone = updated_user.get(
                    "phone"
                )

                current_user.country = updated_user.get(
                    "country"
                )

                current_user.state = updated_user.get(
                    "state"
                )

                current_user.city = updated_user.get(
                    "city"
                )

                current_user.address = updated_user.get(
                    "address"
                )

                current_user.bio = updated_user.get(
                    "bio"
                )

                current_user.gender = updated_user.get(
                    "gender"
                )

                current_user.photo = updated_user.get(
                    "photo"
                )

                current_user.photo_visibility = updated_user.get(
                    "photo_visibility",
                    "everyone"
                )

                current_user.facebook = updated_user.get(
                    "facebook"
                )

                current_user.twitter = updated_user.get(
                    "twitter"
                )

                current_user.google = updated_user.get(
                    "google"
                )

                current_user.whatsapp = updated_user.get(
                    "whatsapp"
                )

                current_user.instagram = updated_user.get(
                    "instagram"
                )

                current_user.github = updated_user.get(
                    "github"
                )

                current_user.updated_at = updated_user.get(
                    "updated_at"
                )

            # ====================================================
            # SUCCESS
            # ====================================================

            flash(
                "Account updated successfully.",
                "success"
            )

            return redirect(
                url_for("main.account_settings")
            )

        # ========================================================
        # MONGODB ERROR
        # ========================================================

        except Exception as e:

            print(
                "ACCOUNT SETTINGS ERROR:",
                repr(e)
            )

            flash(
                "Something went wrong while updating your account.",
                "error"
            )

            return redirect(
                url_for("main.account_settings")
            )

    # ============================================================
    # GET
    # ============================================================

    return render_template(
        "backend/pages/components/users/account_settings.html",
        user=User(user)
    )


@bp.route('/add-user', methods=['GET', 'POST'])
@login_required
def add_user():

    if current_user.role not in ['superadmin', 'admin']:
        return abort(403)

    countries = [
        {"code": "SO", "name": "Somalia", "flag_url": "https://flagcdn.com/so.svg"},
        {"code": "KE", "name": "Kenya", "flag_url": "https://flagcdn.com/ke.svg"},
    ]

    if request.method == 'POST':

        fullname = request.form.get('fullname')
        username = request.form.get('username')
        email = request.form.get('email')
        password = request.form.get('password')
        confirm_password = request.form.get('confirm_password')
        role = request.form.get('role') or "user"
        country = request.form.get('country')
        phone = request.form.get('phone')
        state = request.form.get('state')
        city = request.form.get('city')
        address = request.form.get('address')
        status = True if request.form.get('status') == '1' else False

        # ================= VALIDATION =================
        if not email or not username or not fullname:
            flash("Fadlan buuxi fields-ka muhiimka ah!", "danger")
            return redirect(url_for('main.add_user'))

        if password != confirm_password:
            flash("Passwords-ka isma laha!", "danger")
            return redirect(url_for('main.add_user'))

        if mongo.db.users.find_one({"email": email}):
            flash("Email-kan horey ayaa loo isticmaalay!", "danger")
            return redirect(url_for('main.add_user'))

        if mongo.db.users.find_one({"username": username}):
            flash("Username-kan horey ayaa loo isticmaalay!", "danger")
            return redirect(url_for('main.add_user'))

        # ================= PHOTO UPLOAD =================
        photo_path = None

        file = request.files.get('photo')

        if file and file.filename:

            project_root = os.path.abspath(os.getcwd())

            upload_dir = os.path.join(
                project_root,
                'static',
                'backend',
                'uploads',
                'users'
            )

            os.makedirs(upload_dir, exist_ok=True)

            filename = f"{uuid.uuid4().hex}_{secure_filename(file.filename)}"
            file_path = os.path.join(upload_dir, filename)

            file.save(file_path)

            photo_path = f"backend/uploads/users/{filename}"

        # ================= CREATE USER =================
        new_user = {
            "fullname": fullname,
            "username": username,
            "email": email,
            "password": generate_password_hash(password),
            "role": role,
            "country": country,
            "phone": phone,
            "state": state,
            "city": city,
            "address": address,
            "status": status,
            "photo": photo_path,
            "created_at": datetime.utcnow(),
            "updated_at": datetime.utcnow()
        }

        mongo.db.users.insert_one(new_user)

        flash(f"User {username} si guul leh ayaa loo diiwaangeliyey!", "success")
        return redirect(url_for('main.add_user'))

    return render_template(
        "backend/pages/components/users/add_user.html",
        countries=countries
    )


@bp.route('/edit-user/<user_id>', methods=['GET', 'POST'])
@login_required
def edit_user(user_id):

    if current_user.role not in ['superadmin', 'admin']:
        return abort(403)

    try:
        raw_user = mongo.db.users.find_one({"_id": ObjectId(user_id)})
    except Exception:
        flash("Invalid user ID!", "danger")
        return redirect(url_for('main.index'))

    if not raw_user:
        flash("User-ka lama helin!", "danger")
        return redirect(url_for('main.index'))

    user = User(raw_user)

    if request.method == 'POST':

        fullname = request.form.get('fullname')
        username = request.form.get('username')
        email = request.form.get('email')
        role = request.form.get('role')
        country = request.form.get('country')
        phone = request.form.get('phone')
        address = request.form.get('address')
        bio = request.form.get('bio')
        status = True if request.form.get('status') == '1' else False

        password = request.form.get('password')
        confirm_password = request.form.get('confirm_password')

        # ================= VALIDATION =================
        if mongo.db.users.find_one({
            "username": username,
            "_id": {"$ne": ObjectId(user_id)}
        }):
            flash("Username-kan horey ayaa loo isticmaalay!", "danger")
            return redirect(url_for('main.edit_user', user_id=user_id))

        if mongo.db.users.find_one({
            "email": email,
            "_id": {"$ne": ObjectId(user_id)}
        }):
            flash("Email-kan horey ayaa loo isticmaalay!", "danger")
            return redirect(url_for('main.edit_user', user_id=user_id))

        updated_data = {
            "fullname": fullname,
            "username": username,
            "email": email,
            "role": role,
            "country": country,
            "phone": phone,
            "address": address,
            "bio": bio,
            "status": status,
            "updated_at": datetime.utcnow()
        }

        # ================= PASSWORD =================
        if password:
            if password != confirm_password:
                flash("Passwords-ka isma laha!", "danger")
                return redirect(url_for('main.edit_user', user_id=user_id))

            updated_data["password"] = generate_password_hash(password)

        # ================= CLOUDINARY PHOTO =================
        file = request.files.get('photo')

        if file and file.filename:

            old_public_id = raw_user.get("photo_public_id")

            # delete old image
            if old_public_id:
                try:
                    cloudinary.uploader.destroy(old_public_id)
                except Exception:
                    pass

            # upload new image
            result = cloudinary.uploader.upload(
                file,
                folder="users"
            )

            updated_data["photo"] = result["secure_url"]
            updated_data["photo_public_id"] = result["public_id"]

        # ================= UPDATE DB =================
        mongo.db.users.update_one(
            {"_id": ObjectId(user_id)},
            {"$set": updated_data}
        )

        flash("User si guul leh ayaa loo cusbooneysiiyey!", "success")
        return redirect(url_for('main.edit_user', user_id=user_id))

    return render_template(
        "backend/pages/components/users/edit_user.html",
        user=user
    )


@bp.route('/delete-user/<user_id>', methods=['POST'])
@login_required
def delete_user(user_id):

    if current_user.role not in ['superadmin', 'admin']:
        return abort(403)

    try:
        user = mongo.db.users.find_one({
            "_id": ObjectId(user_id)
        })
    except Exception:
        flash("Invalid user ID!", "danger")
        return redirect(url_for('main.all_users'))

    if not user:
        flash("User-ka lama helin!", "danger")
        return redirect(url_for('main.all_users'))

    # ==========================================
    # DELETE USER PHOTO FROM CLOUDINARY
    # ==========================================

    photo_public_id = user.get("photo_public_id")

    if photo_public_id:
        try:
            cloudinary.uploader.destroy(photo_public_id)
        except Exception:
            pass

    # ==========================================
    # FIND ALL USER ORDERS
    # ==========================================

    orders = list(
        mongo.db.orders.find({
            "user_id": ObjectId(user_id)
        })
    )

    # ==========================================
    # RESTORE PRODUCT STOCK
    # ==========================================

    for order in orders:

        for item in order.get("items", []):

            try:
                mongo.db.products.update_one(
                    {
                        "_id": ObjectId(item["product_id"])
                    },
                    {
                        "$inc": {
                            "stock": int(item["qty"])
                        }
                    }
                )
            except Exception:
                pass

    # ==========================================
    # DELETE ALL CUSTOMER ORDERS
    # ==========================================

    mongo.db.orders.delete_many({
        "user_id": ObjectId(user_id)
    })

    # ==========================================
    # DELETE USER
    # ==========================================

    mongo.db.users.delete_one({
        "_id": ObjectId(user_id)
    })

    flash(
        "Customer, orders-kiisii iyo payments-kiisii si guul leh ayaa loo tirtiray!",
        "success"
    )

    return redirect(url_for('main.all_users'))



@bp.route('/all-users', methods=['GET'])
@login_required
def all_users():

    if current_user.role not in ['superadmin', 'admin']:
        return abort(403)

    if current_user.role == 'superadmin':
        # Superadmin sees everyone
        users_cursor = mongo.db.users.find().sort('created_at', -1)

    else:  # admin
        # Admin cannot see superadmins
        users_cursor = mongo.db.users.find(
            {"role": {"$ne": "superadmin"}}
        ).sort('created_at', -1)

    users = [User(user_data) for user_data in users_cursor]

    return render_template(
        'backend/pages/components/users/all_users.html',
        users=users
    )





# ==========================================
# CALCULATE HEALTHY WEIGHT
# ==========================================

def calculate_goal_weight(height_cm):

    height_m = height_cm / 100

    healthy_min = 18.5 * (height_m ** 2)

    healthy_max = 24.9 * (height_m ** 2)

    goal = (healthy_min + healthy_max) / 2


    return (
        round(goal, 1),
        round(healthy_min, 1),
        round(healthy_max, 1)
    )





# ==========================================
# BMI CALCULATOR
# ==========================================

def calculate_bmi(weight, height_cm):

    try:

        weight = float(weight)
        height_cm = float(height_cm)


        if weight <= 0 or height_cm <= 0:
            return 0


        # CM TO METER
        height_m = height_cm / 100


        bmi = weight / (height_m * height_m)


        return round(bmi, 2)


    except:

        return 0



def bmi_status(bmi):

    if bmi < 18.5:

        return "Under Weight"


    elif bmi < 25:

        return "Normal Weight"


    elif bmi < 30:

        return "Over Weight"


    else:

        return "Obesity"





@bp.route("/gym/checkin", methods=["GET"])
@login_required
def gym_checkin():

    user_id = ObjectId(current_user.id)

    today = datetime.utcnow().date()


    # =====================================
    # PROFILE
    # =====================================

    profile = mongo.db.gym_profile.find_one({

        "user_id": user_id

    })


    if not profile:

        flash(
            "Please create Gym Profile first.",
            "warning"
        )

        return redirect(
            url_for("main.gym_profile")
        )



    # =====================================
    # WEIGHT DATA
    # =====================================

    latest_weight = mongo.db.weight_progress.find_one(

        {
            "user_id": user_id
        },

        sort=[
            ("date",-1)
        ]

    )


    if latest_weight:

        current_weight = float(
            latest_weight.get(
                "weight",
                0
            )
        )

    else:

        current_weight = float(
            profile.get(
                "start_weight",
                0
            )
        )



    start_weight = float(

        profile.get(
            "start_weight",
            current_weight
        )

    )



    # =====================================
    # WEIGHT RESULT
    # =====================================

    if current_weight > start_weight:


        net_gain = round(
            current_weight - start_weight,
            2
        )

        net_loss = 0


    elif current_weight < start_weight:


        net_loss = round(
            start_weight-current_weight,
            2
        )

        net_gain = 0


    else:

        net_gain = 0
        net_loss = 0





    # =====================================
    # STREAK DATA
    # =====================================

    streak = mongo.db.gym_streak.find_one({

        "user_id":user_id

    })


    if not streak:

        streak = {

            "current_streak":0,

            "best_streak":0,

            "total_checkins":0,

            "start_date":None

        }





    # =====================================
    # CHECKIN HISTORY
    # =====================================


    checkins = list(

        mongo.db.gym_checkins.find({

            "user_id":user_id

        })

    )



    checked_dates = {}



    for item in checkins:


        check_date = item.get(
            "date"
        )


        if check_date:


            checked_dates[check_date.date()] = {

                "time":check_date.strftime(
                    "%H:%M"
                )

            }






    # =====================================
    # JOURNEY START DATE
    # =====================================


    journey_start = profile.get(
        "created_at"
    )



    if not journey_start:

        journey_start = streak.get(
            "start_date"
        )



    if not journey_start:

        journey_start = datetime.utcnow()



    journey_start = journey_start.date()






    # =====================================
    # DAILY ATTENDANCE REPORT
    # =====================================


    calendar_days = []


    present_days = 0

    absent_days = 0



    total_days = (

        today -

        journey_start

    ).days + 1




    for i in range(total_days):


        day = journey_start + timedelta(
            days=i
        )



        if day in checked_dates:


            checked = True

            status = "Checked"

            icon = "☑️"

            checkin_time = checked_dates[day]["time"]

            present_days += 1



        else:


            checked = False

            status = "Absent"

            icon = "⬜"

            checkin_time = "-"

            absent_days += 1





        calendar_days.append({


            "date":day.strftime(
                "%Y-%m-%d"
            ),


            "day_name":calendar.day_name[
                day.weekday()
            ],


            "checked":checked,


            "icon":icon,


            "status":status,


            "checkin_time":checkin_time


        })







    # =====================================
    # DAYS SINCE START
    # =====================================


    days_since_start = (

        today -

        journey_start

    ).days + 1





    # =====================================
    # MOTIVATION
    # =====================================


    current = streak.get(

        "current_streak",

        0

    )


    if current >= 60:


        message = "🔥 Legendary! 60+ days consistency!"



    elif current >= 30:


        message = "👑 Amazing! 30 days completed!"



    elif current >=14:


        message = "🚀 Two weeks strong! Keep pushing."



    elif current >=7:


        message = "🏆 One week completed!"



    elif current >=3:


        message = "🔥 Great consistency. Keep going!"



    else:


        message = "💪 Every workout counts. Stay focused."






    # =====================================
    # TEMPLATE
    # =====================================


    return render_template(

        "backend/pages/components/gym/checkin_report.html",


        profile=profile,


        calendar_days=calendar_days,


        journey_start=journey_start,


        total_days=total_days,


        present_days=present_days,


        absent_days=absent_days,


        current_streak=streak.get(
            "current_streak",
            0
        ),


        best_streak=streak.get(
            "best_streak",
            0
        ),


        total_checkins=streak.get(
            "total_checkins",
            0
        ),


        start_date=streak.get(
            "start_date"
        ),


        days_since_start=days_since_start,


        start_weight=start_weight,


        current_weight=current_weight,


        net_gain=net_gain,


        net_loss=net_loss,


        message=message

    )


@bp.route("/gym/checkin/manual", methods=["POST"])
@login_required
def gym_checkin_manual():

    user_id = ObjectId(current_user.id)


    selected_dates = request.form.getlist(
        "checkin_dates"
    )


    if not selected_dates:

        flash(
            "Please select at least one day.",
            "warning"
        )

        return redirect(
            url_for("main.gym_checkin")
        )



    # =====================================
    # GET PROFILE START DATE
    # =====================================

    profile = mongo.db.gym_profile.find_one({

        "user_id": user_id

    })


    if not profile:

        flash(
            "Please create Gym Profile first.",
            "warning"
        )

        return redirect(
            url_for("main.gym_profile")
        )



    start_date = profile.get(
        "created_at"
    )


    if not start_date:

        start_date = datetime.utcnow()



    start_date = start_date.date()



    weight = float(

        profile.get(
            "start_weight",
            0
        )

    )



    saved = 0



    # =====================================
    # SAVE SELECTED DAYS
    # =====================================

    for date_string in selected_dates:


        check_date = datetime.strptime(

            date_string,

            "%Y-%m-%d"

        )



        check_day = check_date.date()



        # ================================
        # BLOCK BEFORE PROFILE DATE
        # ================================

        if check_day < start_date:


            continue




        # ================================
        # DUPLICATE CHECK
        # ================================

        exists = mongo.db.gym_checkins.find_one({

            "user_id": user_id,


            "date": check_date

        })



        if not exists:


            mongo.db.gym_checkins.insert_one({

                "user_id": user_id,

                "date": check_date,

                "weight": weight,

                "created_at": datetime.utcnow()

            })


            saved += 1




    if saved > 0:


        flash(

            f"✅ {saved} gym attendance days saved.",

            "success"

        )


    else:


        flash(

            "No new attendance saved.",

            "info"

        )



    return redirect(

        url_for(
            "main.gym_checkin"
        )

    )



@bp.route("/gym/calendar")
@login_required
def gym_calendar():

    user_id = ObjectId(current_user.id)

    now = datetime.utcnow()

    today = now.date()

    # =====================================
    # PROFILE
    # =====================================

    profile = mongo.db.gym_profile.find_one({
        "user_id": user_id
    })

    if not profile:

        flash(
            "Please create Gym Profile first.",
            "warning"
        )

        return redirect(
            url_for("main.gym_profile")
        )

    # =====================================
    # YEAR / MONTH
    # =====================================

    year = int(
        request.args.get(
            "year",
            now.year
        )
    )

    month = int(
        request.args.get(
            "month",
            now.month
        )
    )

    if month < 1:

        month = 12
        year -= 1

    elif month > 12:

        month = 1
        year += 1

    month_name = calendar.month_name[month]

    # =====================================
    # PROFILE START DATE
    # =====================================

    journey_start = profile.get("created_at")

    if not journey_start:

        streak = mongo.db.gym_streak.find_one({
            "user_id": user_id
        })

        if streak:

            journey_start = streak.get("start_date")

    if not journey_start:

        journey_start = now

    journey_start = journey_start.date()

    # =====================================
    # MONTH RANGE
    # =====================================

    first_day = datetime(
        year,
        month,
        1
    )

    if month == 12:

        next_month = datetime(
            year + 1,
            1,
            1
        )

    else:

        next_month = datetime(
            year,
            month + 1,
            1
        )

    # =====================================
    # CHECKINS
    # =====================================

    checkins = list(

        mongo.db.gym_checkins.find({

            "user_id": user_id,

            "date": {

                "$gte": first_day,

                "$lt": next_month

            }

        })

    )

    checked_days = {}

    for item in checkins:

        d = item.get("date")

        if d:

            checked_days[d.day] = d.strftime("%H:%M")

    # =====================================
    # BUILD CALENDAR
    # =====================================

    calendar_data = []

    for week in calendar.monthcalendar(year, month):

        row = []

        for day in week:

            if day == 0:

                row.append(None)

                continue

            current_date = datetime(
                year,
                month,
                day
            ).date()

            checked = day in checked_days

            if current_date < journey_start:

                status = "before"

            elif current_date > today:

                status = "future"

            elif checked:

                status = "checked"

            else:

                status = "absent"

            row.append({

                "day": day,

                "checked": checked,

                "status": status,

                "time": checked_days.get(day)

            })

        calendar_data.append(row)

    # =====================================
    # STREAK
    # =====================================

    streak = mongo.db.gym_streak.find_one({

        "user_id": user_id

    })

    if not streak:

        streak = {

            "current_streak": 0,

            "best_streak": 0,

            "total_checkins": 0

        }

    # =====================================
    # SUMMARY
    # =====================================

    total_gym_days = len(checked_days)

    total_month_days = 0
    absent_days = 0

    for week in calendar_data:

        for cell in week:

            if not cell:

                continue

            if cell["status"] in ["checked", "absent"]:

                total_month_days += 1

            if cell["status"] == "absent":

                absent_days += 1

    # =====================================
    # TEMPLATE
    # =====================================

    return render_template(

        "backend/pages/components/gym/gym_calendar.html",

        calendar_data=calendar_data,

        month_name=month_name,

        month=month,

        year=year,

        today=today,

        journey_start=journey_start,

        total_month_days=total_month_days,

        total_gym_days=total_gym_days,

        absent_days=absent_days,

        current_streak=streak.get(
            "current_streak",
            0
        ),

        best_streak=streak.get(
            "best_streak",
            0
        ),

        total_checkins=streak.get(
            "total_checkins",
            0
        )

    )


