@bp.route("/gym/profile", methods=["GET","POST"])
@login_required
def gym_profile():

    user_id = ObjectId(current_user.id)


    profile = mongo.db.gym_profile.find_one({

        "user_id": user_id

    })



    # DEFAULT VALUES

    bmi = 0

    bmi_status_text = ""

    goal_weight = 0

    healthy_min = 0

    healthy_max = 0

    age = 0

    height_m = 0



    # ==========================
    # POST SAVE
    # ==========================

    if request.method == "POST":


        height_cm = float(
            request.form.get("height")
        )


        start_weight = float(
            request.form.get("start_weight")
        )


        birth_year = int(
            request.form.get("birth_year")
        )



        # ==========================
        # HEIGHT CONVERSION
        # ==========================

        height_m = round(

            height_cm / 100,

            2

        )



        # AUTO AGE

        current_year = datetime.utcnow().year

        age = current_year - birth_year



        gender = request.form.get(
            "gender"
        )


        activity_level = request.form.get(
            "activity_level"
        )



        # ==========================
        # GOAL WEIGHT
        # ==========================

        goal_weight, healthy_min, healthy_max = calculate_goal_weight(

            height_cm

        )



        # ==========================
        # BMI
        # ==========================

        bmi = calculate_bmi(

            start_weight,

            height_cm

        )


        bmi_status_text = bmi_status(

            bmi

        )



        data = {


            "user_id": user_id,


            # CM VALUE

            "height_cm": height_cm,


            # METER VALUE

            "height_m": height_m,


            "start_weight": start_weight,


            "goal_weight": goal_weight,


            "healthy_min": healthy_min,


            "healthy_max": healthy_max,


            "birth_year": birth_year,


            "age": age,


            "gender": gender,


            "activity_level": activity_level,


            "updated_at": datetime.utcnow()

        }




        if profile:


            mongo.db.gym_profile.update_one(

                {
                    "_id": profile["_id"]
                },

                {
                    "$set": data
                }

            )


        else:


            data["created_at"] = datetime.utcnow()


            mongo.db.gym_profile.insert_one(

                data

            )




        flash(

            "Gym profile saved successfully.",

            "success"

        )


        return redirect(

            url_for(

                "main.gym_profile"

            )

        )





    # ==========================
    # GET DISPLAY
    # ==========================


    if profile:



        height_cm = float(

            profile.get(

                "height_cm",

                0

            )

        )



        height_m = round(

            height_cm / 100,

            2

        )




        weight = float(

            profile.get(

                "start_weight",

                0

            )

        )



        if height_cm and weight:



            bmi = calculate_bmi(

                weight,

                height_cm

            )


            bmi_status_text = bmi_status(

                bmi

            )




        goal_weight, healthy_min, healthy_max = calculate_goal_weight(

            height_cm

        )




        birth_year = profile.get(

            "birth_year"

        )



        if birth_year:


            age = datetime.utcnow().year - birth_year







    return render_template(


        "backend/pages/components/gym/profile.html",


        profile=profile,


        bmi=bmi,


        bmi_status=bmi_status_text,


        goal_weight=goal_weight,


        healthy_min=healthy_min,


        healthy_max=healthy_max,


        age=age,


        height_cm=height_cm if profile else 0,


        height_m=height_m


    )


@bp.route("/gym/weight/add", methods=["GET", "POST"])
@login_required
def add_gym_weight():

    user_id = ObjectId(current_user.id)


    # =====================================
    # GET PROFILE
    # =====================================

    profile = mongo.db.gym_profile.find_one({
        "user_id": user_id
    })


    if not profile:

        flash(
            "Please create your Gym Profile first.",
            "warning"
        )

        return redirect(
            url_for("main.gym_profile")
        )



    # =====================================
    # LAST WEIGHT
    # =====================================

    last_weight = mongo.db.weight_progress.find_one(
        {
            "user_id": user_id
        },
        sort=[
            ("date",-1)
        ]
    )


    if last_weight:

        previous_weight = float(
            last_weight.get(
                "weight",
                0
            )
        )

    else:

        previous_weight = float(
            profile.get(
                "start_weight",
                0
            )
        )




    # =====================================
    # HEIGHT CONVERSION
    # =====================================

    height_cm = float(
        profile.get(
            "height_cm",
            0
        )
    )


    height_m = round(
        height_cm / 100,
        2
    ) if height_cm else 0




    # =====================================
    # BMI FUNCTION
    # =====================================

    def calculate_bmi_value(weight):

        if height_m <= 0:

            return 0

        return round(
            weight /
            (height_m ** 2),
            2
        )



    def get_bmi_status(value):

        if value < 18.5:

            return "Underweight"


        elif value < 25:

            return "Normal Weight"


        elif value < 30:

            return "Overweight"


        else:

            return "Obese"




    # =====================================
    # CURRENT BMI
    # =====================================

    bmi = calculate_bmi_value(
        previous_weight
    )


    bmi_status = get_bmi_status(
        bmi
    )




    # =====================================
    # POST SAVE
    # =====================================

    if request.method == "POST":


        weight = request.form.get(
            "weight",
            ""
        ).strip()


        date = request.form.get(
            "date"
        )


        note = request.form.get(
            "note",
            ""
        ).strip()


        record_type = request.form.get(
            "type",
            "weight_record"
        )



        if not weight:


            flash(
                "Weight is required.",
                "danger"
            )

            return redirect(
                request.url
            )



        try:

            weight = float(weight)

        except:


            flash(
                "Invalid weight.",
                "danger"
            )

            return redirect(
                request.url
            )



        if weight <= 0:


            flash(
                "Weight must be greater than zero.",
                "danger"
            )

            return redirect(
                request.url
            )




        # DATE

        if date:

            date = datetime.strptime(
                date,
                "%Y-%m-%d"
            )

        else:

            date = datetime.utcnow()




        # DUPLICATE CHECK

        exists = mongo.db.weight_progress.find_one({

            "user_id": user_id,

            "date": date

        })


        if exists:


            flash(
                "Weight already exists for this date.",
                "warning"
            )

            return redirect(
                request.url
            )




        # WEIGHT CHANGE

        difference = round(
            weight - previous_weight,
            2
        )


        if difference > 0:

            change_type = "Weight Gain"


        elif difference < 0:

            change_type = "Weight Loss"


        else:

            change_type = "No Change"




        # NEW BMI

        new_bmi = calculate_bmi_value(
            weight
        )


        new_bmi_status = get_bmi_status(
            new_bmi
        )




        # SAVE


        mongo.db.weight_progress.insert_one({

            "user_id":user_id,

            "type":record_type,

            "weight":weight,

            "previous_weight":previous_weight,

            "difference":difference,

            "change_type":change_type,


            "height_cm":height_cm,

            "height_m":height_m,


            "bmi":new_bmi,

            "bmi_status":new_bmi_status,


            "date":date,

            "note":note,


            "created_at":datetime.utcnow(),

            "updated_at":datetime.utcnow()

        })




        flash(
            "Weight record saved successfully.",
            "success"
        )


        return redirect(
            url_for(
                "main.weight_history"
            )
        )




    return render_template(

        "backend/pages/components/gym/add_weight.html",

        profile=profile,

        previous_weight=previous_weight,


        height_cm=height_cm,

        height_m=height_m,


        bmi=bmi,

        bmi_status=bmi_status,


        datetime=datetime

    )




@bp.route("/gym/weight/edit/<id>", methods=["GET","POST"])
@login_required
def edit_gym_weight(id):

    try:

        weight_id = ObjectId(id)

    except:

        abort(404)



    user_id = ObjectId(current_user.id)



    # ==========================
    # GET OLD RECORD
    # ==========================

    weight = mongo.db.weight_progress.find_one({

        "_id": weight_id,

        "user_id": user_id

    })



    if not weight:

        abort(404)





    if request.method == "POST":


        new_weight = request.form.get(
            "weight"
        )


        date = request.form.get(
            "date"
        )


        note = request.form.get(
            "note",
            ""
        )



        # ==========================
        # VALIDATION
        # ==========================


        if not new_weight:


            flash(
                "Weight is required.",
                "danger"
            )

            return redirect(
                request.url
            )



        try:

            new_weight = float(
                new_weight
            )


        except:


            flash(
                "Invalid weight.",
                "danger"
            )

            return redirect(
                request.url
            )




        if new_weight <= 0:


            flash(
                "Weight must be greater than zero.",
                "danger"
            )

            return redirect(
                request.url
            )





        # ==========================
        # DATE
        # ==========================


        if date:


            date = datetime.strptime(
                date,
                "%Y-%m-%d"
            )


        else:

            date = weight.get(
                "date",
                datetime.utcnow()
            )







        # ==========================
        # CALCULATE CHANGE
        # ==========================


        old_weight = float(
            weight.get(
                "weight",
                0
            )
        )



        difference = round(

            new_weight - old_weight,

            2

        )



        if difference > 0:


            change_type = "Weight Gain"



        elif difference < 0:


            change_type = "Weight Loss"



        else:


            change_type = "No Change"







        # ==========================
        # UPDATE
        # ==========================


        mongo.db.weight_progress.update_one(

            {

                "_id":weight_id,

                "user_id":user_id

            },


            {

                "$set":{


                    "weight":
                    new_weight,


                    "difference":
                    difference,


                    "change_type":
                    change_type,


                    "date":
                    date,


                    "note":
                    note,


                    "updated_at":
                    datetime.utcnow()


                }

            }

        )






        flash(

            "Weight updated successfully.",

            "success"

        )



        return redirect(

            url_for(
                "main.weight_history"
            )

        )







    return render_template(

        "backend/pages/components/gym/edit_weight.html",

        weight=weight

    )

