# ============================================================
# ACCOUNTS - FULL ACCOUNT REPORT
# ============================================================

@bp.route("/accounts")
@login_required
def account_list():

    from bson import ObjectId
    from datetime import datetime

    # ========================================================
    # SAFE NUMBER
    # ========================================================

    def to_float(value):

        try:
            return float(value or 0)

        except (TypeError, ValueError):

            return 0.0


    # ========================================================
    # SAFE OBJECT ID
    # ========================================================

    def safe_object_id(value):

        try:

            return ObjectId(str(value))

        except Exception:

            return None


    # ========================================================
    # SERIALIZE MONGO VALUES
    # ========================================================

    def serialize_value(value):

        if isinstance(value, ObjectId):

            return str(value)

        if isinstance(value, datetime):

            return value.strftime(
                "%Y-%m-%d %H:%M:%S"
            )

        if isinstance(value, dict):

            return {
                str(k): serialize_value(v)
                for k, v in value.items()
            }

        if isinstance(value, list):

            return [
                serialize_value(v)
                for v in value
            ]

        return value


    # ========================================================
    # USER ID
    # ========================================================

    current_user_id = safe_object_id(
        current_user.id
    )


    # ========================================================
    # USER QUERY
    # ========================================================

    query = {}

    if current_user.role != UserRole.superadmin.value:

        if current_user_id is None:

            return render_template(
                "backend/pages/components/accounts/all_accounts.html",
                accounts=[],
                savings=[],
                account_reports=[],
                all_accounts_report={
                    "total_accounts": 0,
                    "opening_balance": 0,
                    "total_income": 0,
                    "total_expense": 0,
                    "transfer_in": 0,
                    "transfer_out": 0,
                    "net_movement": 0,
                    "current_balance": 0,
                    "transaction_count": 0,
                    "income_categories": {},
                    "expense_categories": {}
                },
                income_categories={},
                expense_categories={}
            )

        query["user_id"] = current_user_id


    # ========================================================
    # GET ACCOUNTS
    # ========================================================

    accounts = list(
        mongo.db.accounts.find(query)
        .sort("created_at", -1)
    )


    # ========================================================
    # GET TRANSACTIONS
    # ========================================================

    transactions = list(
        mongo.db.transactions.find(query)
        .sort("date", -1)
    )


    # ========================================================
    # GET SAVINGS
    # ========================================================

    saving_query = {}

    if current_user.role != UserRole.superadmin.value:

        saving_query["user_id"] = current_user_id


    savings = list(
        mongo.db.savings.find(
            saving_query
        )
    )


    # ========================================================
    # SAVING ID
    # ========================================================

    active_saving = (
        savings[0]
        if savings
        else None
    )


    saving_id = ""

    if active_saving:

        saving_id = str(
            active_saving.get("_id")
        )


    # ========================================================
    # GRAND TOTALS
    # ========================================================

    grand_opening = 0.0
    grand_income = 0.0
    grand_expense = 0.0
    grand_transfer_in = 0.0
    grand_transfer_out = 0.0
    grand_balance = 0.0
    grand_transactions = 0

    income_categories = {}
    expense_categories = {}


    # ========================================================
    # ACCOUNT REPORTS
    # ========================================================

    account_reports = []


    # ========================================================
    # ACCOUNT LOOP
    # ========================================================

    for account in accounts:

        account_id = str(
            account.get("_id")
        )


        account_name = (
            account.get("name")
            or "Unnamed Account"
        )


        account_type = (
            account.get("type")
            or "Other"
        )


        currency = (
            account.get("currency")
            or "USD"
        )


        # ====================================================
        # BALANCE
        # ====================================================

        current_balance = to_float(
            account.get("balance")
        )

        if (
            "balance" not in account
            and "current_balance" in account
        ):

            current_balance = to_float(
                account.get(
                    "current_balance"
                )
            )


        # ====================================================
        # OPENING BALANCE
        # ====================================================

        opening_balance = to_float(
            account.get(
                "opening_balance"
            )
        )


        if opening_balance == 0:

            opening_balance = to_float(
                account.get(
                    "initial_balance"
                )
            )


        # ====================================================
        # ACCOUNT TRANSACTIONS
        # ====================================================

        account_transactions = []

        total_income = 0.0
        total_expense = 0.0
        total_transfer_in = 0.0
        total_transfer_out = 0.0

        income_count = 0
        expense_count = 0
        transfer_count = 0

        account_income_categories = {}
        account_expense_categories = {}


        # ====================================================
        # TRANSACTION LOOP
        # ====================================================

        for trx in transactions:

            trx_account_id = trx.get(
                "account_id"
            )


            if trx_account_id is None:

                continue


            if str(
                trx_account_id
            ) != account_id:

                continue


            transaction_type = str(

                trx.get(
                    "transaction_type"
                )

                or

                trx.get(
                    "type"
                )

                or ""

            ).lower().strip()


            amount = to_float(
                trx.get("amount")
            )


            category = str(
                trx.get("category")
                or "Other"
            )


            # =================================================
            # INCOME
            # =================================================

            if transaction_type == "income":

                total_income += amount

                income_count += 1


                account_income_categories[
                    category
                ] = (

                    account_income_categories.get(
                        category,
                        0.0
                    )

                    + amount

                )


                income_categories[
                    category
                ] = (

                    income_categories.get(
                        category,
                        0.0
                    )

                    + amount

                )


            # =================================================
            # EXPENSE
            # =================================================

            elif transaction_type == "expense":

                total_expense += amount

                expense_count += 1


                account_expense_categories[
                    category
                ] = (

                    account_expense_categories.get(
                        category,
                        0.0
                    )

                    + amount

                )


                expense_categories[
                    category
                ] = (

                    expense_categories.get(
                        category,
                        0.0
                    )

                    + amount

                )


            # =================================================
            # TRANSFER IN
            # =================================================

            elif transaction_type in (

                "transfer_in",
                "transfer-in",
                "transfer in",
                "transferin"

            ):

                total_transfer_in += amount

                transfer_count += 1


            # =================================================
            # TRANSFER OUT
            # =================================================

            elif transaction_type in (

                "transfer_out",
                "transfer-out",
                "transfer out",
                "transferout"

            ):

                total_transfer_out += amount

                transfer_count += 1


            # =================================================
            # COPY TRANSACTION
            # =================================================

            transaction_copy = dict(
                trx
            )


            # Serialize ALL Mongo values
            transaction_copy = serialize_value(
                transaction_copy
            )


            # Account information
            transaction_copy[
                "account_name"
            ] = account_name


            transaction_copy[
                "account_type"
            ] = account_type


            account_transactions.append(
                transaction_copy
            )


        # ====================================================
        # NET MOVEMENT
        # ====================================================

        net_movement = (

            total_income

            + total_transfer_in

            - total_expense

            - total_transfer_out

        )


        # ====================================================
        # TOTAL TRANSACTIONS
        # ====================================================

        transaction_count = len(
            account_transactions
        )


        # ====================================================
        # GRAND TOTALS
        # ====================================================

        grand_opening += opening_balance

        grand_income += total_income

        grand_expense += total_expense

        grand_transfer_in += (
            total_transfer_in
        )

        grand_transfer_out += (
            total_transfer_out
        )

        grand_balance += current_balance

        grand_transactions += (
            transaction_count
        )


        # ====================================================
        # REPORT
        # ====================================================

        report = {

            "id":
                account_id,

            "name":
                account_name,

            "type":
                account_type,

            "currency":
                currency,

            "opening_balance":
                opening_balance,

            "balance":
                current_balance,

            # Compatibility
            "current_balance":
                current_balance,

            "total_income":
                total_income,

            "total_expense":
                total_expense,

            "transfer_in":
                total_transfer_in,

            "transfer_out":
                total_transfer_out,

            "net_movement":
                net_movement,

            "transaction_count":
                transaction_count,

            "income_count":
                income_count,

            "expense_count":
                expense_count,

            "transfer_count":
                transfer_count,

            "income_categories":
                account_income_categories,

            "expense_categories":
                account_expense_categories,

            "transactions":
                account_transactions
        }


        # ====================================================
        # ADD REPORT
        # ====================================================

        account_reports.append(
            report
        )


    # ========================================================
    # GRAND NET MOVEMENT
    # ========================================================

    grand_net = (

        grand_income

        + grand_transfer_in

        - grand_expense

        - grand_transfer_out

    )


    # ========================================================
    # ALL ACCOUNTS REPORT
    # ========================================================

    all_accounts_report = {

        "total_accounts":
            len(account_reports),

        "opening_balance":
            grand_opening,

        "total_income":
            grand_income,

        "total_expense":
            grand_expense,

        "transfer_in":
            grand_transfer_in,

        "transfer_out":
            grand_transfer_out,

        "net_movement":
            grand_net,

        "current_balance":
            grand_balance,

        "transaction_count":
            grand_transactions,

        "income_categories":
            income_categories,

        "expense_categories":
            expense_categories
    }


    # ========================================================
    # PREPARE NORMAL ACCOUNTS
    # ========================================================

    prepared_accounts = []


    for account in accounts:

        account_copy = dict(
            account
        )


        # ====================================================
        # ACCOUNT ID
        # ====================================================

        account_copy["_id"] = str(
            account_copy.get("_id")
        )


        # ====================================================
        # USER ID
        # ====================================================

        if account_copy.get(
            "user_id"
        ) is not None:

            account_copy["user_id"] = str(
                account_copy["user_id"]
            )


        # ====================================================
        # SAVING ID
        # ====================================================

        account_copy[
            "saving_id"
        ] = saving_id


        # ====================================================
        # FIND REPORT
        # ====================================================

        matching_report = next(

            (
                report

                for report in account_reports

                if report["id"]
                == account_copy["_id"]

            ),

            None

        )


        # ====================================================
        # ATTACH REPORT
        # ====================================================

        if matching_report:

            account_copy[
                "report"
            ] = matching_report


            # ------------------------------------------------
            # Compatibility fields
            # ------------------------------------------------

            account_copy[
                "current_balance"
            ] = matching_report[
                "balance"
            ]


            account_copy[
                "balance"
            ] = matching_report[
                "balance"
            ]


            account_copy[
                "opening_balance"
            ] = matching_report[
                "opening_balance"
            ]


            account_copy[
                "total_income"
            ] = matching_report[
                "total_income"
            ]


            account_copy[
                "total_expense"
            ] = matching_report[
                "total_expense"
            ]


            account_copy[
                "net_movement"
            ] = matching_report[
                "net_movement"
            ]


            account_copy[
                "transaction_count"
            ] = matching_report[
                "transaction_count"
            ]


            account_copy[
                "income_count"
            ] = matching_report[
                "income_count"
            ]


            account_copy[
                "expense_count"
            ] = matching_report[
                "expense_count"
            ]


            account_copy[
                "income_categories"
            ] = matching_report[
                "income_categories"
            ]


            account_copy[
                "expense_categories"
            ] = matching_report[
                "expense_categories"
            ]


            account_copy[
                "report_transactions"
            ] = matching_report[
                "transactions"
            ]


        else:

            # =================================================
            # EMPTY REPORT
            # =================================================

            empty_report = {

                "id":
                    account_copy["_id"],

                "name":
                    account_copy.get(
                        "name",
                        "Unnamed Account"
                    ),

                "type":
                    account_copy.get(
                        "type",
                        "Other"
                    ),

                "currency":
                    account_copy.get(
                        "currency",
                        "USD"
                    ),

                "opening_balance":
                    0.0,

                "balance":
                    0.0,

                "current_balance":
                    0.0,

                "total_income":
                    0.0,

                "total_expense":
                    0.0,

                "transfer_in":
                    0.0,

                "transfer_out":
                    0.0,

                "net_movement":
                    0.0,

                "transaction_count":
                    0,

                "income_count":
                    0,

                "expense_count":
                    0,

                "transfer_count":
                    0,

                "income_categories":
                    {},

                "expense_categories":
                    {},

                "transactions":
                    []
            }


            account_copy[
                "report"
            ] = empty_report


            account_copy[
                "current_balance"
            ] = 0.0


            account_copy[
                "total_income"
            ] = 0.0


            account_copy[
                "total_expense"
            ] = 0.0


            account_copy[
                "net_movement"
            ] = 0.0


            account_copy[
                "transaction_count"
            ] = 0


        prepared_accounts.append(
            account_copy
        )


    # ========================================================
    # SERIALIZE SAVINGS
    # ========================================================

    prepared_savings = []

    for saving in savings:

        saving_copy = serialize_value(
            dict(saving)
        )

        prepared_savings.append(
            saving_copy
        )


    # ========================================================
    # RENDER
    # ========================================================

    return render_template(

        "backend/pages/components/accounts/all_accounts.html",

        accounts=prepared_accounts,

        savings=prepared_savings,

        account_reports=account_reports,

        all_accounts_report=
            all_accounts_report,

        income_categories=
            income_categories,

        expense_categories=
            expense_categories,

        saving_id=
            saving_id

    )



@bp.route('/add-account', methods=['GET', 'POST'])
@login_required
def add_account():

    if request.method == "POST":

        # Form Data
        name = request.form.get("name", "").strip()
        account_type = request.form.get("type", "cash").strip()
        balance = request.form.get("balance", 0)
        currency = request.form.get("currency", "USD").strip()

        # Validation
        if not name:
            flash("Account name is required.", "danger")
            return redirect(url_for("main.add_account"))

        try:
            balance = float(balance)
        except ValueError:
            flash("Invalid balance amount.", "danger")
            return redirect(url_for("main.add_account"))

        # Duplicate Check
        existing = mongo.db.accounts.find_one({
            "user_id": ObjectId(current_user.id),
            "name": {
                "$regex": f"^{name}$",
                "$options": "i"
            }
        })

        if existing:
            flash("Account already exists.", "danger")
            return redirect(url_for("main.add_account"))

        # Save
        account = Account()

        data = account.add(
            user_id=current_user.id,
            name=name,
            account_type=account_type,
            balance=balance,
            currency=currency,
            status=True
        )

        data["user_id"] = ObjectId(current_user.id)

        mongo.db.accounts.insert_one(data)

        flash("Account created successfully.", "success")
        return redirect(url_for("main.account_list"))

    return render_template(
        "backend/pages/components/accounts/add_account.html"
    )


@bp.route("/edit-account/<id>", methods=["GET", "POST"])
@login_required
def edit_account(id):

    account = mongo.db.accounts.find_one({
        "_id": ObjectId(id),
        "user_id": ObjectId(current_user.id)
    })

    if not account:
        flash("Account not found.", "danger")
        return redirect(url_for("main.account_list"))

    if request.method == "POST":

        name = request.form.get("name", "").strip()
        account_type = request.form.get("type")
        currency = request.form.get("currency")
        balance = request.form.get("balance", 0)

        if not name:
            flash("Account name is required.", "danger")
            return redirect(url_for("main.edit_account", id=id))

        try:
            balance = float(balance)
        except ValueError:
            balance = 0

        mongo.db.accounts.update_one(
            {"_id": ObjectId(id)},
            {
                "$set": {
                    "name": name,
                    "type": account_type,
                    "currency": currency,
                    "balance": balance,
                    "updated_at": datetime.utcnow()
                }
            }
        )

        flash("Account updated successfully.", "success")
        return redirect(url_for("main.account_list"))

    return render_template(
        "backend/pages/components/accounts/edit_account.html",
        account=account
    )


@bp.route("/delete-account/<id>")
@login_required
def delete_account(id):

    account = mongo.db.accounts.find_one({
        "_id": ObjectId(id),
        "user_id": ObjectId(current_user.id)
    })

    if not account:
        flash("Account not found.", "danger")
        return redirect(url_for("main.account_list"))

    # 🔥 SAFETY CHECK (IMPORTANT)
    has_transactions = mongo.db.transactions.find_one({
        "account_id": id
    })

    has_savings = mongo.db.savings.find_one({
        "account_id": id
    })

    if has_transactions or has_savings:
        flash("This account cannot be deleted because it is in use.", "warning")
        return redirect(url_for("main.account_list"))

    mongo.db.accounts.delete_one({
        "_id": ObjectId(id)
    })

    flash("Account deleted successfully.", "success")
    return redirect(url_for("main.account_list"))




# ============================================================
# ACCOUNT TRANSFER
# ============================================================
@bp.route("/account/transfer", methods=["POST"])
@login_required
def account_transfer():

    from bson import ObjectId
    from datetime import datetime
    from flask import request, jsonify
    import uuid

    # ============================================================
    # HELPERS
    # ============================================================

    def oid(value):
        if not value:
            return None

        try:
            if isinstance(value, ObjectId):
                return value

            return ObjectId(str(value))

        except Exception:
            return None

    def safe_float(value, default=0.0):
        try:
            return float(value or 0)
        except (TypeError, ValueError):
            return default

    # ============================================================
    # REQUEST DATA
    # ============================================================

    data = request.get_json(silent=True)

    if not data:
        return jsonify({
            "success": False,
            "error": "No data provided."
        }), 400

    transfer_type = (
        data.get("transfer_type")
        or "account_to_account"
    )

    # ------------------------------------------------------------
    # Supported:
    #
    # account_to_account
    # account_to_saving
    # saving_to_account
    # ------------------------------------------------------------

    allowed_types = {
        "account_to_account",
        "account_to_saving",
        "saving_to_account"
    }

    if transfer_type not in allowed_types:
        return jsonify({
            "success": False,
            "error": "Invalid transfer type."
        }), 400

    amount = safe_float(
        data.get("amount")
    )

    if amount <= 0:
        return jsonify({
            "success": False,
            "error": "Transfer amount must be greater than zero."
        }), 400

    # ============================================================
    # CURRENT USER
    # ============================================================

    user_id = str(current_user.id)

    user_object_id = oid(user_id)

    # ============================================================
    # OWNER FILTER
    # ============================================================

    if current_user.role == UserRole.superadmin.value:

        owner_filter = {}

    else:

        owner_conditions = [
            {
                "user_id": user_id
            }
        ]

        if user_object_id:

            owner_conditions.append({
                "user_id": user_object_id
            })

        owner_filter = {
            "$or": owner_conditions
        }

    # ============================================================
    # IDS
    # ============================================================

    from_account_id = data.get(
        "from_account"
    )

    to_account_id = data.get(
        "to_account"
    )

    from_saving_id = data.get(
        "from_saving"
    )

    to_saving_id = data.get(
        "to_saving"
    )

    from_account_obj = oid(
        from_account_id
    )

    to_account_obj = oid(
        to_account_id
    )

    from_saving_obj = oid(
        from_saving_id
    )

    to_saving_obj = oid(
        to_saving_id
    )

    # ============================================================
    # DATE
    # ============================================================

    now = datetime.utcnow()

    # ============================================================
    # REFERENCE
    # ============================================================

    if transfer_type == "saving_to_account":

        reference_no = (
            "SAV-"
            + now.strftime("%Y%m%d%H%M%S")
            + "-"
            + uuid.uuid4().hex[:6].upper()
        )

    elif transfer_type == "account_to_saving":

        reference_no = (
            "SAV-"
            + now.strftime("%Y%m%d%H%M%S")
            + "-"
            + uuid.uuid4().hex[:6].upper()
        )

    else:

        reference_no = (
            "TRF-"
            + uuid.uuid4().hex[:10].upper()
        )

    # ============================================================
    # COMMON VARIABLES
    # ============================================================

    source_name = "Unknown"
    destination_name = "Unknown"

    source_currency = "USD"
    destination_currency = "USD"

    description = (
        data.get("description")
        or ""
    )

    direction = ""

    # ============================================================
    # BALANCE SNAPSHOTS
    #
    # IMPORTANT:
    #
    # These are the values that the REPORT/MODAL will use.
    # ============================================================

    from_account_balance_before = None
    from_account_balance_after = None

    to_account_balance_before = None
    to_account_balance_after = None

    from_saving_balance_before = None
    from_saving_balance_after = None

    to_saving_balance_before = None
    to_saving_balance_after = None

    # ============================================================
    # ACCOUNT -> ACCOUNT
    # ============================================================

    if transfer_type == "account_to_account":

        direction = "transfer"

        if not from_account_obj:
            return jsonify({
                "success": False,
                "error": "Source account is required."
            }), 400

        if not to_account_obj:
            return jsonify({
                "success": False,
                "error": "Destination account is required."
            }), 400

        if from_account_obj == to_account_obj:
            return jsonify({
                "success": False,
                "error": "You cannot transfer to the same account."
            }), 400

        # --------------------------------------------------------
        # GET ACCOUNTS
        # --------------------------------------------------------

        source_query = {
            "_id": from_account_obj,
            **owner_filter
        }

        destination_query = {
            "_id": to_account_obj,
            **owner_filter
        }

        source = mongo.db.accounts.find_one(
            source_query
        )

        destination = mongo.db.accounts.find_one(
            destination_query
        )

        if not source:
            return jsonify({
                "success": False,
                "error": "Source account not found."
            }), 404

        if not destination:
            return jsonify({
                "success": False,
                "error": "Destination account not found."
            }), 404

        # --------------------------------------------------------
        # CURRENCY
        # --------------------------------------------------------

        source_currency = (
            source.get("currency")
            or "USD"
        )

        destination_currency = (
            destination.get("currency")
            or "USD"
        )

        if source_currency != destination_currency:

            return jsonify({
                "success": False,
                "error": (
                    f"Currency mismatch. "
                    f"Source uses {source_currency}, "
                    f"destination uses {destination_currency}."
                )
            }), 400

        # --------------------------------------------------------
        # BEFORE
        # --------------------------------------------------------

        from_account_balance_before = safe_float(
            source.get("balance")
        )

        to_account_balance_before = safe_float(
            destination.get("balance")
        )

        if amount > from_account_balance_before:

            return jsonify({
                "success": False,
                "error": (
                    "Insufficient balance. "
                    f"Available {source_currency} "
                    f"{from_account_balance_before:,.2f}"
                )
            }), 400

        source_name = (
            source.get("name")
            or source.get("account_name")
            or "Source Account"
        )

        destination_name = (
            destination.get("name")
            or destination.get("account_name")
            or "Destination Account"
        )

        description = (
            data.get("description")
            or f"Transfer from {source_name} to {destination_name}"
        )

        # --------------------------------------------------------
        # UPDATE SOURCE
        # --------------------------------------------------------

        source_update = mongo.db.accounts.update_one(

            {
                "_id": from_account_obj,
                **owner_filter,
                "balance": {
                    "$gte": amount
                }
            },

            {
                "$inc": {
                    "balance": -amount
                },

                "$set": {
                    "updated_at": now
                }
            }
        )

        if source_update.modified_count != 1:

            return jsonify({
                "success": False,
                "error": "Source balance changed. Transfer failed."
            }), 400

        # --------------------------------------------------------
        # UPDATE DESTINATION
        # --------------------------------------------------------

        destination_update = mongo.db.accounts.update_one(

            {
                "_id": to_account_obj,
                **owner_filter
            },

            {
                "$inc": {
                    "balance": amount
                },

                "$set": {
                    "updated_at": now
                }
            }
        )

        if destination_update.modified_count != 1:

            mongo.db.accounts.update_one(
                {
                    "_id": from_account_obj
                },
                {
                    "$inc": {
                        "balance": amount
                    }
                }
            )

            return jsonify({
                "success": False,
                "error": "Destination account could not be updated."
            }), 500

        # --------------------------------------------------------
        # AFTER
        # --------------------------------------------------------

        from_account_balance_after = (
            from_account_balance_before - amount
        )

        to_account_balance_after = (
            to_account_balance_before + amount
        )

    # ============================================================
    # ACCOUNT -> SAVING
    # ============================================================

    elif transfer_type == "account_to_saving":

        direction = "deposit"

        if not from_account_obj:
            return jsonify({
                "success": False,
                "error": "Source account is required."
            }), 400

        if not to_saving_obj:
            return jsonify({
                "success": False,
                "error": "Destination saving is required."
            }), 400

        # --------------------------------------------------------
        # GET ACCOUNT
        # --------------------------------------------------------

        account = mongo.db.accounts.find_one({
            "_id": from_account_obj,
            **owner_filter
        })

        # --------------------------------------------------------
        # GET SAVING
        # --------------------------------------------------------

        saving = mongo.db.savings.find_one({
            "_id": to_saving_obj,
            **owner_filter
        })

        if not account:
            return jsonify({
                "success": False,
                "error": "Source account not found."
            }), 404

        if not saving:
            return jsonify({
                "success": False,
                "error": "Destination saving not found."
            }), 404

        # --------------------------------------------------------
        # CURRENCY
        # --------------------------------------------------------

        source_currency = (
            account.get("currency")
            or "USD"
        )

        destination_currency = (
            saving.get("currency")
            or source_currency
        )

        if source_currency != destination_currency:

            return jsonify({
                "success": False,
                "error": (
                    f"Currency mismatch. "
                    f"Account uses {source_currency}, "
                    f"saving uses {destination_currency}."
                )
            }), 400

        # --------------------------------------------------------
        # BEFORE
        # --------------------------------------------------------

        from_account_balance_before = safe_float(
            account.get("balance")
        )

        to_saving_balance_before = safe_float(
            saving.get("current_balance")
        )

        if amount > from_account_balance_before:

            return jsonify({
                "success": False,
                "error": (
                    "Insufficient account balance. "
                    f"Available {source_currency} "
                    f"{from_account_balance_before:,.2f}"
                )
            }), 400

        source_name = (
            account.get("name")
            or account.get("account_name")
            or "Source Account"
        )

        destination_name = (
            saving.get("name")
            or saving.get("saving_name")
            or saving.get("title")
            or "Saving"
        )

        description = (
            data.get("description")
            or "Account deposit to saving"
        )

        # --------------------------------------------------------
        # ACCOUNT - AMOUNT
        # --------------------------------------------------------

        account_update = mongo.db.accounts.update_one(

            {
                "_id": from_account_obj,
                **owner_filter,
                "balance": {
                    "$gte": amount
                }
            },

            {
                "$inc": {
                    "balance": -amount
                },

                "$set": {
                    "updated_at": now
                }
            }
        )

        if account_update.modified_count != 1:

            return jsonify({
                "success": False,
                "error": "Account balance changed. Transfer failed."
            }), 400

        # --------------------------------------------------------
        # SAVING + AMOUNT
        # --------------------------------------------------------

        saving_update = mongo.db.savings.update_one(

            {
                "_id": to_saving_obj,
                **owner_filter
            },

            {
                "$inc": {
                    "current_balance": amount
                },

                "$set": {
                    "updated_at": now
                }
            }
        )

        if saving_update.modified_count != 1:

            mongo.db.accounts.update_one(
                {
                    "_id": from_account_obj
                },
                {
                    "$inc": {
                        "balance": amount
                    }
                }
            )

            return jsonify({
                "success": False,
                "error": "Saving could not be updated."
            }), 500

        # --------------------------------------------------------
        # AFTER
        # --------------------------------------------------------

        from_account_balance_after = (
            from_account_balance_before - amount
        )

        to_saving_balance_after = (
            to_saving_balance_before + amount
        )

    # ============================================================
    # SAVING -> ACCOUNT
    # ============================================================

    elif transfer_type == "saving_to_account":

        direction = "withdraw"

        if not from_saving_obj:
            return jsonify({
                "success": False,
                "error": "Source saving is required."
            }), 400

        if not to_account_obj:
            return jsonify({
                "success": False,
                "error": "Destination account is required."
            }), 400

        # --------------------------------------------------------
        # GET SAVING
        # --------------------------------------------------------

        saving = mongo.db.savings.find_one({
            "_id": from_saving_obj,
            **owner_filter
        })

        # --------------------------------------------------------
        # GET ACCOUNT
        # --------------------------------------------------------

        account = mongo.db.accounts.find_one({
            "_id": to_account_obj,
            **owner_filter
        })

        if not saving:

            return jsonify({
                "success": False,
                "error": "Source saving not found."
            }), 404

        if not account:

            return jsonify({
                "success": False,
                "error": "Destination account not found."
            }), 404

        # --------------------------------------------------------
        # CURRENCY
        # --------------------------------------------------------

        source_currency = (
            saving.get("currency")
            or "USD"
        )

        destination_currency = (
            account.get("currency")
            or source_currency
        )

        if source_currency != destination_currency:

            return jsonify({
                "success": False,
                "error": (
                    f"Currency mismatch. "
                    f"Saving uses {source_currency}, "
                    f"account uses {destination_currency}."
                )
            }), 400

        # --------------------------------------------------------
        # BEFORE
        # --------------------------------------------------------

        from_saving_balance_before = safe_float(
            saving.get("current_balance")
        )

        to_account_balance_before = safe_float(
            account.get("balance")
        )

        # ========================================================
        # IMPORTANT
        # ========================================================
        #
        # Saving before must be the REAL current saving balance.
        #
        # Example:
        #
        # Saving = 212
        # Amount = 2
        #
        # After = 210
        #
        # NOT 0.
        # ========================================================

        if amount > from_saving_balance_before:

            return jsonify({
                "success": False,
                "error": (
                    "Insufficient saving balance. "
                    f"Available {source_currency} "
                    f"{from_saving_balance_before:,.2f}"
                )
            }), 400

        source_name = (
            saving.get("name")
            or saving.get("saving_name")
            or saving.get("title")
            or "Saving"
        )

        destination_name = (
            account.get("name")
            or account.get("account_name")
            or "Destination Account"
        )

        description = (
            data.get("description")
            or "Saving withdrawal to account"
        )

        # --------------------------------------------------------
        # SAVING - AMOUNT
        # --------------------------------------------------------

        saving_update = mongo.db.savings.update_one(

            {
                "_id": from_saving_obj,
                **owner_filter,
                "current_balance": {
                    "$gte": amount
                }
            },

            {
                "$inc": {
                    "current_balance": -amount
                },

                "$set": {
                    "updated_at": now
                }
            }
        )

        if saving_update.modified_count != 1:

            return jsonify({
                "success": False,
                "error": "Saving balance changed. Transfer failed."
            }), 400

        # --------------------------------------------------------
        # ACCOUNT + AMOUNT
        # --------------------------------------------------------

        account_update = mongo.db.accounts.update_one(

            {
                "_id": to_account_obj,
                **owner_filter
            },

            {
                "$inc": {
                    "balance": amount
                },

                "$set": {
                    "updated_at": now
                }
            }
        )

        if account_update.modified_count != 1:

            # Rollback saving
            mongo.db.savings.update_one(
                {
                    "_id": from_saving_obj
                },
                {
                    "$inc": {
                        "current_balance": amount
                    }
                }
            )

            return jsonify({
                "success": False,
                "error": "Destination account could not be updated."
            }), 500

        # --------------------------------------------------------
        # AFTER
        # --------------------------------------------------------

        from_saving_balance_after = (
            from_saving_balance_before - amount
        )

        to_account_balance_after = (
            to_account_balance_before + amount
        )

    # ============================================================
    # MASTER TRANSFER RECORD
    # ============================================================

    transfer_record = {

        "_id": ObjectId(),

        "user_id": str(user_id),

        # --------------------------------------------------------
        # TYPE
        # --------------------------------------------------------

        "transfer_type": transfer_type,

        "direction": direction,

        # --------------------------------------------------------
        # IDS
        # --------------------------------------------------------

        "from_account": from_account_obj,
        "to_account": to_account_obj,

        "from_saving": from_saving_obj,
        "to_saving": to_saving_obj,

        # --------------------------------------------------------
        # NAMES
        # --------------------------------------------------------

        "from_account_name": (
            source_name
            if transfer_type != "saving_to_account"
            else None
        ),

        "to_account_name": (
            destination_name
            if transfer_type != "account_to_saving"
            else None
        ),

        "from_saving_name": (
            source_name
            if transfer_type == "saving_to_account"
            else None
        ),

        "to_saving_name": (
            destination_name
            if transfer_type == "account_to_saving"
            else None
        ),

        # --------------------------------------------------------
        # AMOUNT
        # --------------------------------------------------------

        "amount": amount,

        "currency": source_currency,

        # --------------------------------------------------------
        # STATUS
        # --------------------------------------------------------

        "status": "completed",

        # --------------------------------------------------------
        # REFERENCE
        # --------------------------------------------------------

        "reference": reference_no,

        "reference_no": reference_no,

        # --------------------------------------------------------
        # DESCRIPTION
        # --------------------------------------------------------

        "description": description,

        # ========================================================
        # ACCOUNT BALANCE REPORT
        # ========================================================

        "from_account_balance_before":
            from_account_balance_before,

        "from_account_balance_after":
            from_account_balance_after,

        "to_account_balance_before":
            to_account_balance_before,

        "to_account_balance_after":
            to_account_balance_after,

        # ========================================================
        # SAVING BALANCE REPORT
        # ========================================================

        "from_saving_balance_before":
            from_saving_balance_before,

        "from_saving_balance_after":
            from_saving_balance_after,

        "to_saving_balance_before":
            to_saving_balance_before,

        "to_saving_balance_after":
            to_saving_balance_after,

        # --------------------------------------------------------
        # TIMESTAMPS
        # --------------------------------------------------------

        "created_at": now,

        "updated_at": now
    }

    # ============================================================
    # INSERT MASTER
    # ============================================================

    transfer_result = (
        mongo.db.account_transfers.insert_one(
            transfer_record
        )
    )

    transfer_id = (
        transfer_result.inserted_id
    )

    # ============================================================
    # TRANSACTION RECORDS
    # ============================================================

    transaction_records = []

    # ============================================================
    # ACCOUNT -> ACCOUNT
    # ============================================================

    if transfer_type == "account_to_account":

        # --------------------------------------------------------
        # SOURCE
        # --------------------------------------------------------

        transaction_records.append({

            "user_id": str(user_id),

            "account_id": from_account_obj,

            "transaction_type": "transfer_out",

            "type": "transfer_out",

            "amount": amount,

            "currency": source_currency,

            "category": "Account Transfer",

            "item": (
                f"Transfer to {destination_name}"
            ),

            "description": description,

            "note": (
                f"Money transferred to "
                f"{destination_name}"
            ),

            "reference_no": reference_no,

            "transfer_id": transfer_id,

            "from_account": from_account_obj,

            "to_account": to_account_obj,

            "balance_before":
                from_account_balance_before,

            "balance_after":
                from_account_balance_after,

            "created_at": now,

            "updated_at": now,

            "date": now
        })

        # --------------------------------------------------------
        # DESTINATION
        # --------------------------------------------------------

        transaction_records.append({

            "user_id": str(user_id),

            "account_id": to_account_obj,

            "transaction_type": "transfer_in",

            "type": "transfer_in",

            "amount": amount,

            "currency": destination_currency,

            "category": "Account Transfer",

            "item": (
                f"Transfer from {source_name}"
            ),

            "description": description,

            "note": (
                f"Money received from "
                f"{source_name}"
            ),

            "reference_no": reference_no,

            "transfer_id": transfer_id,

            "from_account": from_account_obj,

            "to_account": to_account_obj,

            "balance_before":
                to_account_balance_before,

            "balance_after":
                to_account_balance_after,

            "created_at": now,

            "updated_at": now,

            "date": now
        })

    # ============================================================
    # ACCOUNT -> SAVING
    # ============================================================

    elif transfer_type == "account_to_saving":

        transaction_records.append({

            "user_id": str(user_id),

            "account_id": from_account_obj,

            "transaction_type": "transfer_out",

            "type": "transfer_out",

            "amount": amount,

            "currency": source_currency,

            "category": "Saving Deposit",

            "item": (
                f"Deposit to {destination_name}"
            ),

            "description": description,

            "note": (
                f"Money transferred from "
                f"{source_name} to saving"
            ),

            "reference_no": reference_no,

            "transfer_id": transfer_id,

            "from_account": from_account_obj,

            "to_saving": to_saving_obj,

            "balance_before":
                from_account_balance_before,

            "balance_after":
                from_account_balance_after,

            "created_at": now,

            "updated_at": now,

            "date": now
        })

        transaction_records.append({

            "user_id": str(user_id),

            "saving_id": to_saving_obj,

            "account_id": from_account_obj,

            "transaction_type": "deposit",

            "type": "deposit",

            "amount": amount,

            "currency": destination_currency,

            "category": "Saving Deposit",

            "item": (
                f"Deposit from {source_name}"
            ),

            "description": description,

            "note": (
                f"Money received from "
                f"{source_name}"
            ),

            "reference_no": reference_no,

            "transfer_id": transfer_id,

            "from_account": from_account_obj,

            "to_saving": to_saving_obj,

            "balance_before":
                to_saving_balance_before,

            "balance_after":
                to_saving_balance_after,

            "saving_balance_before":
                to_saving_balance_before,

            "saving_balance_after":
                to_saving_balance_after,

            "created_at": now,

            "updated_at": now,

            "date": now
        })

    # ============================================================
    # SAVING -> ACCOUNT
    # ============================================================

    elif transfer_type == "saving_to_account":

        # --------------------------------------------------------
        # SAVING TRANSACTION
        # --------------------------------------------------------

        transaction_records.append({

            "user_id": str(user_id),

            "saving_id": from_saving_obj,

            "account_id": to_account_obj,

            "transaction_type": "withdrawal",

            "type": "withdrawal",

            "amount": amount,

            "currency": source_currency,

            "category": "Saving Withdrawal",

            "item": (
                f"Withdrawal to {destination_name}"
            ),

            "description": description,

            "note": (
                f"Money withdrawn from "
                f"{source_name}"
            ),

            "reference_no": reference_no,

            "transfer_id": transfer_id,

            "from_saving": from_saving_obj,

            "to_account": to_account_obj,

            # ====================================================
            # REAL SAVING BALANCE
            # ====================================================

            "balance_before":
                from_saving_balance_before,

            "balance_after":
                from_saving_balance_after,

            "saving_balance_before":
                from_saving_balance_before,

            "saving_balance_after":
                from_saving_balance_after,

            "created_at": now,

            "updated_at": now,

            "date": now
        })

        # --------------------------------------------------------
        # ACCOUNT TRANSACTION
        # --------------------------------------------------------

        transaction_records.append({

            "user_id": str(user_id),

            "account_id": to_account_obj,

            "transaction_type": "transfer_in",

            "type": "transfer_in",

            "amount": amount,

            "currency": destination_currency,

            "category": "Saving Withdrawal",

            "item": (
                f"Received from {source_name}"
            ),

            "description": description,

            "note": (
                f"Money received from "
                f"{source_name}"
            ),

            "reference_no": reference_no,

            "transfer_id": transfer_id,

            "from_saving": from_saving_obj,

            "to_account": to_account_obj,

            # ====================================================
            # REAL ACCOUNT BALANCE
            # ====================================================

            "balance_before":
                to_account_balance_before,

            "balance_after":
                to_account_balance_after,

            "account_balance_before":
                to_account_balance_before,

            "account_balance_after":
                to_account_balance_after,

            "created_at": now,

            "updated_at": now,

            "date": now
        })

    # ============================================================
    # INSERT TRANSACTIONS
    # ============================================================

    if transaction_records:

        mongo.db.transactions.insert_many(
            transaction_records
        )

    # ============================================================
    # ALSO SAVE SAVING TRANSACTION HISTORY
    # ============================================================

    if transfer_type == "account_to_saving":

        mongo.db.saving_transactions.insert_one({

            "user_id": str(user_id),

            "saving_id": to_saving_obj,

            "account_id": from_account_obj,

            "transaction_type": "deposit",

            "amount": amount,

            "description": description,

            "note": (
                f"Deposit from {source_name}"
            ),

            "reference_no": reference_no,

            "transfer_id": transfer_id,

            "balance_before":
                to_saving_balance_before,

            "balance_after":
                to_saving_balance_after,

            "created_at": now,

            "updated_at": now,

            "date": now,

            "status": True
        })

    elif transfer_type == "saving_to_account":

        mongo.db.saving_transactions.insert_one({

            "user_id": str(user_id),

            "saving_id": from_saving_obj,

            "account_id": to_account_obj,

            "transaction_type": "withdrawal",

            "amount": amount,

            "description": description,

            "note": (
                f"Withdrawal to {destination_name}"
            ),

            "reference_no": reference_no,

            "transfer_id": transfer_id,

            "balance_before":
                from_saving_balance_before,

            "balance_after":
                from_saving_balance_after,

            "created_at": now,

            "updated_at": now,

            "date": now,

            "status": True
        })

    # ============================================================
    # SUCCESS RESPONSE
    # ============================================================

    return jsonify({

        "success": True,

        "message": (
            "Money transferred successfully."
        ),

        "transfer_id": str(
            transfer_id
        ),

        "transfer_type":
            transfer_type,

        "direction":
            direction,

        "reference_no":
            reference_no,

        "amount":
            amount,

        "currency":
            source_currency,

        "from_name":
            source_name,

        "to_name":
            destination_name,

        # --------------------------------------------------------
        # ACCOUNT REPORT
        # --------------------------------------------------------

        "from_account_balance_before":
            from_account_balance_before,

        "from_account_balance_after":
            from_account_balance_after,

        "to_account_balance_before":
            to_account_balance_before,

        "to_account_balance_after":
            to_account_balance_after,

        # --------------------------------------------------------
        # SAVING REPORT
        # --------------------------------------------------------

        "from_saving_balance_before":
            from_saving_balance_before,

        "from_saving_balance_after":
            from_saving_balance_after,

        "to_saving_balance_before":
            to_saving_balance_before,

        "to_saving_balance_after":
            to_saving_balance_after

    }), 200

# ============================================================
# DELETE ACCOUNT / SAVING TRANSFER
# ============================================================
@bp.route(
    "/account/transfer/delete/<transfer_id>",
    methods=["POST", "DELETE"]
)
@login_required
def delete_account_transfer(transfer_id):

    from bson import ObjectId
    from datetime import datetime
    from flask import request, jsonify

    # ============================================================
    # HELPERS
    # ============================================================

    def json_success(
        message,
        transfer_id=None,
        transfer_type=None,
        amount=None,
        saving_history_deleted=0,
        transaction_history_deleted=0
    ):
        return jsonify({
            "success": True,
            "message": message,
            "transfer_id": str(transfer_id) if transfer_id else "",
            "transfer_type": transfer_type or "",
            "amount": float(amount or 0),
            "saving_history_deleted": int(
                saving_history_deleted or 0
            ),
            "transaction_history_deleted": int(
                transaction_history_deleted or 0
            )
        }), 200

    def json_error(
        message,
        status=400,
        details=None
    ):
        response = {
            "success": False,
            "error": message,
            "message": message
        }

        if details:
            response["details"] = str(details)

        return jsonify(response), status

    # ============================================================
    # NORMALIZE OBJECT ID
    # ============================================================

    try:

        transfer_obj_id = ObjectId(
            str(transfer_id)
        )

    except Exception:

        return json_error(
            "Invalid transfer ID.",
            400
        )

    # ============================================================
    # CURRENT USER
    # ============================================================

    current_user_id = str(
        current_user.id
    )

    try:

        current_user_obj_id = ObjectId(
            current_user_id
        )

    except Exception:

        current_user_obj_id = None

    # ============================================================
    # FIND TRANSFER WITH PERMISSION
    # ============================================================

    try:

        if current_user.role == UserRole.superadmin.value:

            transfer = (
                mongo.db.account_transfers.find_one({
                    "_id": transfer_obj_id
                })
            )

        else:

            user_conditions = [
                {
                    "user_id":
                    current_user_id
                }
            ]

            if current_user_obj_id:

                user_conditions.append({
                    "user_id":
                    current_user_obj_id
                })

            transfer = (
                mongo.db.account_transfers.find_one({

                    "_id":
                    transfer_obj_id,

                    "$or":
                    user_conditions

                })
            )

    except Exception as e:

        print(
            "FIND ACCOUNT TRANSFER DELETE ERROR:",
            repr(e)
        )

        return json_error(
            "Unable to find the transfer.",
            500,
            e
        )

    # ============================================================
    # NOT FOUND
    # ============================================================

    if not transfer:

        return json_error(
            "Transfer not found or you do not have permission to delete it.",
            404
        )

    # ============================================================
    # TRANSFER TYPE
    # ============================================================

    transfer_type = (
        transfer.get(
            "transfer_type"
        )
        or "account_to_account"
    )

    # ============================================================
    # AMOUNT
    # ============================================================

    try:

        amount = float(
            transfer.get("amount") or 0
        )

    except Exception:

        amount = 0.0

    if amount <= 0:

        return json_error(
            "Invalid transfer amount.",
            400
        )

    # ============================================================
    # OBJECT ID HELPER
    # ============================================================

    def normalize_object_id(value):

        if not value:
            return None

        try:

            if isinstance(
                value,
                ObjectId
            ):
                return value

            return ObjectId(
                str(value)
            )

        except Exception:

            return None

    # ============================================================
    # IDS
    # ============================================================

    from_account_obj = normalize_object_id(
        transfer.get("from_account")
    )

    to_account_obj = normalize_object_id(
        transfer.get("to_account")
    )

    from_saving_obj = normalize_object_id(
        transfer.get("from_saving")
    )

    to_saving_obj = normalize_object_id(
        transfer.get("to_saving")
    )

    # ============================================================
    # TIMESTAMP
    # ============================================================

    now = datetime.utcnow()

    # ============================================================
    # TRACK BALANCE CHANGES
    #
    # This is important for rollback.
    # ============================================================

    balance_changes = []

    history_deleted = 0
    transactions_deleted = 0

    # ============================================================
    # APPLY BALANCE CHANGE
    # ============================================================

    def change_account_balance(
        account_id,
        amount_change
    ):

        if not account_id:

            raise Exception(
                "Account information is missing."
            )

        result = (
            mongo.db.accounts.update_one(

                {
                    "_id":
                    account_id
                },

                {
                    "$inc": {
                        "balance":
                        amount_change
                    },

                    "$set": {
                        "updated_at":
                        now
                    }
                }
            )
        )

        if result.modified_count != 1:

            raise Exception(
                "Failed to update account balance."
            )

        balance_changes.append({
            "collection":
            "accounts",

            "id":
            account_id,

            "amount":
            amount_change
        })

    # ============================================================
    # APPLY SAVING BALANCE CHANGE
    # ============================================================

    def change_saving_balance(
        saving_id,
        amount_change
    ):

        if not saving_id:

            raise Exception(
                "Saving information is missing."
            )

        result = (
            mongo.db.savings.update_one(

                {
                    "_id":
                    saving_id
                },

                {
                    "$inc": {
                        "current_balance":
                        amount_change
                    },

                    "$set": {
                        "updated_at":
                        now
                    }
                }
            )
        )

        if result.modified_count != 1:

            raise Exception(
                "Failed to update saving balance."
            )

        balance_changes.append({
            "collection":
            "savings",

            "id":
            saving_id,

            "amount":
            amount_change
        })

    # ============================================================
    # CHECK EXISTING RECORDS
    # ============================================================

    try:

        # ========================================================
        # ACCOUNT -> SAVING
        # ========================================================

        if transfer_type == "account_to_saving":

            if not from_account_obj:

                return json_error(
                    "Source account information is missing.",
                    400
                )

            if not to_saving_obj:

                return json_error(
                    "Destination saving information is missing.",
                    400
                )

            account = mongo.db.accounts.find_one({
                "_id":
                from_account_obj
            })

            saving = mongo.db.savings.find_one({
                "_id":
                to_saving_obj
            })

            if not account:

                return json_error(
                    "Source account no longer exists.",
                    400
                )

            if not saving:

                return json_error(
                    "Destination saving no longer exists.",
                    400
                )

            # ----------------------------------------------------
            # ORIGINAL:
            #
            # ACCOUNT  - amount
            # SAVING   + amount
            #
            # DELETE:
            #
            # ACCOUNT  + amount
            # SAVING   - amount
            # ----------------------------------------------------

            change_account_balance(
                from_account_obj,
                amount
            )

            change_saving_balance(
                to_saving_obj,
                -amount
            )

        # ========================================================
        # SAVING -> ACCOUNT
        # ========================================================

        elif transfer_type == "saving_to_account":

            if not from_saving_obj:

                return json_error(
                    "Source saving information is missing.",
                    400
                )

            if not to_account_obj:

                return json_error(
                    "Destination account information is missing.",
                    400
                )

            saving = mongo.db.savings.find_one({
                "_id":
                from_saving_obj
            })

            account = mongo.db.accounts.find_one({
                "_id":
                to_account_obj
            })

            if not saving:

                return json_error(
                    "Source saving no longer exists.",
                    400
                )

            if not account:

                return json_error(
                    "Destination account no longer exists.",
                    400
                )

            # ----------------------------------------------------
            # ORIGINAL:
            #
            # SAVING  - amount
            # ACCOUNT + amount
            #
            # DELETE:
            #
            # SAVING  + amount
            # ACCOUNT - amount
            # ----------------------------------------------------

            change_saving_balance(
                from_saving_obj,
                amount
            )

            change_account_balance(
                to_account_obj,
                -amount
            )

        # ========================================================
        # ACCOUNT -> ACCOUNT
        # ========================================================

        else:

            if not from_account_obj:

                return json_error(
                    "Source account information is missing.",
                    400
                )

            if not to_account_obj:

                return json_error(
                    "Destination account information is missing.",
                    400
                )

            from_account = mongo.db.accounts.find_one({
                "_id":
                from_account_obj
            })

            to_account = mongo.db.accounts.find_one({
                "_id":
                to_account_obj
            })

            if not from_account:

                return json_error(
                    "Source account no longer exists.",
                    400
                )

            if not to_account:

                return json_error(
                    "Destination account no longer exists.",
                    400
                )

            # ----------------------------------------------------
            # ORIGINAL:
            #
            # FROM ACCOUNT - amount
            # TO ACCOUNT   + amount
            #
            # DELETE:
            #
            # FROM ACCOUNT + amount
            # TO ACCOUNT   - amount
            # ----------------------------------------------------

            change_account_balance(
                from_account_obj,
                amount
            )

            change_account_balance(
                to_account_obj,
                -amount
            )

        # ========================================================
        # DELETE SAVING HISTORY
        # ========================================================

        history_query = {
            "$or": [
                {
                    "transfer_id":
                    transfer_obj_id
                },
                {
                    "transfer_id":
                    str(transfer_obj_id)
                }
            ]
        }

        history_result = (
            mongo.db.saving_transactions.delete_many(
                history_query
            )
        )

        history_deleted = (
            history_result.deleted_count
        )

        # ========================================================
        # DELETE GENERAL TRANSACTION HISTORY
        # ========================================================

        transaction_conditions = [
            {
                "transfer_id":
                transfer_obj_id
            },
            {
                "transfer_id":
                str(transfer_obj_id)
            }
        ]

        reference_no = transfer.get(
            "reference_no"
        )

        reference = transfer.get(
            "reference"
        )

        if reference_no:

            transaction_conditions.append({
                "reference_no":
                reference_no
            })

        if reference:

            transaction_conditions.append({
                "reference":
                reference
            })

        transaction_result = (
            mongo.db.transactions.delete_many({

                "$or":
                transaction_conditions

            })
        )

        transactions_deleted = (
            transaction_result.deleted_count
        )

        # ========================================================
        # DELETE MAIN TRANSFER
        # ========================================================

        delete_result = (
            mongo.db.account_transfers.delete_one({

                "_id":
                transfer_obj_id

            })
        )

        # ========================================================
        # VERIFY DELETE
        # ========================================================

        if delete_result.deleted_count != 1:

            raise Exception(
                "Transfer could not be deleted."
            )

        # ========================================================
        # SUCCESS
        # ========================================================

        success_message = (
            "Transfer deleted successfully. "
            "Balances and related financial history "
            "have been restored."
        )

        return json_success(

            success_message,

            transfer_id=
            transfer_obj_id,

            transfer_type=
            transfer_type,

            amount=
            amount,

            saving_history_deleted=
            history_deleted,

            transaction_history_deleted=
            transactions_deleted
        )

    # ============================================================
    # EXCEPTION + ROLLBACK
    # ============================================================

    except Exception as e:

        print(
            "DELETE ACCOUNT TRANSFER ERROR:",
            repr(e)
        )

        # ========================================================
        # ROLLBACK BALANCE CHANGES
        # ========================================================

        try:

            for change in reversed(
                balance_changes
            ):

                if (
                    change["collection"]
                    == "accounts"
                ):

                    mongo.db.accounts.update_one(

                        {
                            "_id":
                            change["id"]
                        },

                        {
                            "$inc": {
                                "balance":
                                -change["amount"]
                            },

                            "$set": {
                                "updated_at":
                                now
                            }
                        }
                    )

                elif (
                    change["collection"]
                    == "savings"
                ):

                    mongo.db.savings.update_one(

                        {
                            "_id":
                            change["id"]
                        },

                        {
                            "$inc": {
                                "current_balance":
                                -change["amount"]
                            },

                            "$set": {
                                "updated_at":
                                now
                            }
                        }
                    )

        except Exception as rollback_error:

            print(
                "DELETE TRANSFER ROLLBACK ERROR:",
                repr(rollback_error)
            )

        # ========================================================
        # IMPORTANT
        #
        # If histories were deleted before the main transfer
        # failed, they cannot automatically be reconstructed.
        # Therefore return clear JSON.
        # ========================================================

        return json_error(

            "Failed to delete transfer. "
            "The balance changes were rolled back.",

            500,

            e
        )
    

