# ============================================================
# ALL ACCOUNT / SAVING TRANSFERS
# ============================================================
@bp.route("/account/transfers")
@login_required
def all_account_transfers():

    from bson import ObjectId
    from datetime import datetime
    import json

    # ============================================================
    # CURRENT USER
    # ============================================================

    current_user_id = str(current_user.id)

    try:
        current_user_object_id = ObjectId(current_user_id)
    except Exception:
        current_user_object_id = None

    # ============================================================
    # USER FILTER
    # ============================================================

    if current_user.role == UserRole.superadmin.value:

        transfer_query = {}

    else:

        user_conditions = [
            {"user_id": current_user_id}
        ]

        if current_user_object_id:
            user_conditions.append(
                {"user_id": current_user_object_id}
            )

        transfer_query = {
            "$or": user_conditions
        }

    # ============================================================
    # GET TRANSFERS
    # ============================================================

    transfers_raw = list(
        mongo.db.account_transfers.find(
            transfer_query
        ).sort(
            "created_at",
            -1
        )
    )

    # ============================================================
    # HELPERS
    # ============================================================

    def safe_float(value, default=0.0):

        try:

            if value is None:
                return default

            return float(value)

        except (TypeError, ValueError):

            return default

    def safe_string(value, default=""):

        if value is None:
            return default

        return str(value)

    def get_balance(transfer, *keys):

        for key in keys:

            if key in transfer:

                value = transfer.get(key)

                if value is not None:
                    return safe_float(value)

        return 0.0

    def format_datetime(value):

        if not value:
            return {
                "iso": "",
                "display": "-"
            }

        # Mongo datetime
        if isinstance(value, datetime):

            return {
                "iso": value.isoformat(),
                "display": value.strftime(
                    "%d %b %Y, %I:%M:%S %p"
                )
            }

        # String datetime
        value_string = str(value)

        try:

            parsed = datetime.fromisoformat(
                value_string.replace("Z", "+00:00")
            )

            return {
                "iso": parsed.isoformat(),
                "display": parsed.strftime(
                    "%d %b %Y, %I:%M:%S %p"
                )
            }

        except Exception:

            return {
                "iso": value_string,
                "display": value_string
            }

    # ============================================================
    # COLLECT ACCOUNT IDS
    # ============================================================

    account_ids = set()

    for transfer in transfers_raw:

        for key in [
            "from_account",
            "to_account"
        ]:

            value = transfer.get(key)

            if value:

                account_ids.add(
                    str(value)
                )

    # ============================================================
    # LOAD ACCOUNTS
    # ============================================================

    accounts_map = {}

    for account_id in account_ids:

        try:

            account = mongo.db.accounts.find_one({
                "_id": ObjectId(account_id)
            })

            if account:

                accounts_map[
                    str(account["_id"])
                ] = account

        except Exception:

            continue

    # ============================================================
    # COLLECT SAVING IDS
    # ============================================================

    saving_ids = set()

    for transfer in transfers_raw:

        for key in [
            "from_saving",
            "to_saving"
        ]:

            value = transfer.get(key)

            if value:

                saving_ids.add(
                    str(value)
                )

    # ============================================================
    # LOAD SAVINGS
    # ============================================================

    savings_map = {}

    for saving_id in saving_ids:

        try:

            saving = mongo.db.savings.find_one({
                "_id": ObjectId(saving_id)
            })

            if saving:

                savings_map[
                    str(saving["_id"])
                ] = saving

        except Exception:

            continue

    # ============================================================
    # PREPARE TRANSFERS
    # ============================================================

    transfers = []

    for transfer in transfers_raw:

        # ========================================================
        # BASIC
        # ========================================================

        transfer_id = str(
            transfer.get("_id")
        )

        transfer_type = (
            transfer.get("transfer_type")
            or "account_to_account"
        )

        direction = (
            transfer.get("direction")
            or ""
        )

        amount = safe_float(
            transfer.get("amount")
        )

        currency = (
            transfer.get("currency")
            or "USD"
        )

        status = (
            transfer.get("status")
            or "completed"
        )

        status_display = (
            str(status).replace("_", " ").title()
        )

        reference = (
            transfer.get("reference_no")
            or transfer.get("reference")
            or transfer.get("transfer_no")
            or transfer_id
        )

        description = (
            transfer.get("description")
            or ""
        )

        # ========================================================
        # DATE
        # ========================================================

        date_info = format_datetime(
            transfer.get("created_at")
        )

        # ========================================================
        # DEFAULT
        # ========================================================

        transaction_type = "Transfer"

        from_type = "Account"
        to_type = "Account"

        from_name = "Unknown Account"
        to_name = "Unknown Account"

        # ========================================================
        # BALANCES
        # ========================================================

        from_balance_before = 0.0
        from_balance_after = 0.0

        to_balance_before = 0.0
        to_balance_after = 0.0

        from_account_balance_before = 0.0
        from_account_balance_after = 0.0

        to_account_balance_before = 0.0
        to_account_balance_after = 0.0

        from_saving_balance_before = 0.0
        from_saving_balance_after = 0.0

        to_saving_balance_before = 0.0
        to_saving_balance_after = 0.0

        # ========================================================
        # ACCOUNT → SAVING
        # ========================================================

        if transfer_type == "account_to_saving":

            transaction_type = "Deposit"

            from_type = "Account"
            to_type = "Saving"

            # ----------------------------------------------------
            # FROM ACCOUNT
            # ----------------------------------------------------

            from_account_id = transfer.get(
                "from_account"
            )

            account = None

            if from_account_id:

                account = accounts_map.get(
                    str(from_account_id)
                )

            if account:

                from_name = (
                    transfer.get(
                        "from_account_name"
                    )
                    or account.get("name")
                    or account.get("account_name")
                    or "Unknown Account"
                )

            else:

                from_name = (
                    transfer.get(
                        "from_account_name"
                    )
                    or "Unknown Account"
                )

            # ----------------------------------------------------
            # TO SAVING
            # ----------------------------------------------------

            to_saving_id = transfer.get(
                "to_saving"
            )

            saving = None

            if to_saving_id:

                saving = savings_map.get(
                    str(to_saving_id)
                )

            if saving:

                to_name = (
                    transfer.get(
                        "to_saving_name"
                    )
                    or saving.get("name")
                    or saving.get("saving_name")
                    or saving.get("title")
                    or "Unknown Saving"
                )

            else:

                to_name = (
                    transfer.get(
                        "to_saving_name"
                    )
                    or "Unknown Saving"
                )

            # ----------------------------------------------------
            # CURRENCY
            # ----------------------------------------------------

            currency = (
                transfer.get("currency")
                or (
                    account.get("currency")
                    if account
                    else None
                )
                or "USD"
            )

            # ----------------------------------------------------
            # ACCOUNT BALANCE
            # ----------------------------------------------------

            from_account_balance_before = get_balance(
                transfer,
                "account_balance_before",
                "from_account_balance_before",
                "source_account_balance_before"
            )

            from_account_balance_after = get_balance(
                transfer,
                "account_balance_after",
                "from_account_balance_after",
                "source_account_balance_after"
            )

            # ----------------------------------------------------
            # SAVING BALANCE
            # ----------------------------------------------------

            to_saving_balance_before = get_balance(
                transfer,
                "saving_balance_before",
                "to_saving_balance_before",
                "destination_saving_balance_before"
            )

            to_saving_balance_after = get_balance(
                transfer,
                "saving_balance_after",
                "to_saving_balance_after",
                "destination_saving_balance_after"
            )

            from_balance_before = (
                from_account_balance_before
            )

            from_balance_after = (
                from_account_balance_after
            )

            to_balance_before = (
                to_saving_balance_before
            )

            to_balance_after = (
                to_saving_balance_after
            )

        # ========================================================
        # SAVING → ACCOUNT
        # ========================================================

        elif transfer_type == "saving_to_account":

            transaction_type = "Withdraw"

            from_type = "Saving"
            to_type = "Account"

            # ----------------------------------------------------
            # FROM SAVING
            # ----------------------------------------------------

            from_saving_id = transfer.get(
                "from_saving"
            )

            saving = None

            if from_saving_id:

                saving = savings_map.get(
                    str(from_saving_id)
                )

            if saving:

                from_name = (
                    transfer.get(
                        "from_saving_name"
                    )
                    or saving.get("name")
                    or saving.get("saving_name")
                    or saving.get("title")
                    or "Unknown Saving"
                )

            else:

                from_name = (
                    transfer.get(
                        "from_saving_name"
                    )
                    or "Unknown Saving"
                )

            # ----------------------------------------------------
            # TO ACCOUNT
            # ----------------------------------------------------

            to_account_id = transfer.get(
                "to_account"
            )

            account = None

            if to_account_id:

                account = accounts_map.get(
                    str(to_account_id)
                )

            if account:

                to_name = (
                    transfer.get(
                        "to_account_name"
                    )
                    or account.get("name")
                    or account.get("account_name")
                    or "Unknown Account"
                )

            else:

                to_name = (
                    transfer.get(
                        "to_account_name"
                    )
                    or "Unknown Account"
                )

            # ----------------------------------------------------
            # CURRENCY
            # ----------------------------------------------------

            currency = (
                transfer.get("currency")
                or (
                    saving.get("currency")
                    if saving
                    else None
                )
                or (
                    account.get("currency")
                    if account
                    else None
                )
                or "USD"
            )

            # ----------------------------------------------------
            # SAVING BALANCE
            # ----------------------------------------------------

            from_saving_balance_before = get_balance(
                transfer,
                "saving_balance_before",
                "from_saving_balance_before",
                "source_saving_balance_before"
            )

            from_saving_balance_after = get_balance(
                transfer,
                "saving_balance_after",
                "from_saving_balance_after",
                "source_saving_balance_after"
            )

            # ----------------------------------------------------
            # ACCOUNT BALANCE
            # ----------------------------------------------------

            to_account_balance_before = get_balance(
                transfer,
                "account_balance_before",
                "to_account_balance_before",
                "destination_account_balance_before"
            )

            to_account_balance_after = get_balance(
                transfer,
                "account_balance_after",
                "to_account_balance_after",
                "destination_account_balance_after"
            )

            from_balance_before = (
                from_saving_balance_before
            )

            from_balance_after = (
                from_saving_balance_after
            )

            to_balance_before = (
                to_account_balance_before
            )

            to_balance_after = (
                to_account_balance_after
            )

        # ========================================================
        # ACCOUNT → ACCOUNT
        # ========================================================

        else:

            transaction_type = "Transfer"

            from_type = "Account"
            to_type = "Account"

            # ----------------------------------------------------
            # FROM ACCOUNT
            # ----------------------------------------------------

            from_account_id = transfer.get(
                "from_account"
            )

            from_account = None

            if from_account_id:

                from_account = accounts_map.get(
                    str(from_account_id)
                )

            if from_account:

                from_name = (
                    transfer.get(
                        "from_account_name"
                    )
                    or from_account.get("name")
                    or from_account.get("account_name")
                    or "Unknown Account"
                )

            else:

                from_name = (
                    transfer.get(
                        "from_account_name"
                    )
                    or "Unknown Account"
                )

            # ----------------------------------------------------
            # TO ACCOUNT
            # ----------------------------------------------------

            to_account_id = transfer.get(
                "to_account"
            )

            to_account = None

            if to_account_id:

                to_account = accounts_map.get(
                    str(to_account_id)
                )

            if to_account:

                to_name = (
                    transfer.get(
                        "to_account_name"
                    )
                    or to_account.get("name")
                    or to_account.get("account_name")
                    or "Unknown Account"
                )

            else:

                to_name = (
                    transfer.get(
                        "to_account_name"
                    )
                    or "Unknown Account"
                )

            # ----------------------------------------------------
            # CURRENCY
            # ----------------------------------------------------

            currency = (
                transfer.get("currency")
                or (
                    from_account.get("currency")
                    if from_account
                    else None
                )
                or (
                    to_account.get("currency")
                    if to_account
                    else None
                )
                or "USD"
            )

            # ----------------------------------------------------
            # SOURCE BALANCE
            # ----------------------------------------------------

            from_account_balance_before = get_balance(
                transfer,
                "from_account_balance_before",
                "source_account_balance_before",
                "account_balance_before"
            )

            from_account_balance_after = get_balance(
                transfer,
                "from_account_balance_after",
                "source_account_balance_after",
                "account_balance_after"
            )

            # ----------------------------------------------------
            # DESTINATION BALANCE
            # ----------------------------------------------------

            to_account_balance_before = get_balance(
                transfer,
                "to_account_balance_before",
                "destination_account_balance_before",
                "receiver_account_balance_before"
            )

            to_account_balance_after = get_balance(
                transfer,
                "to_account_balance_after",
                "destination_account_balance_after",
                "receiver_account_balance_after"
            )

            from_balance_before = (
                from_account_balance_before
            )

            from_balance_after = (
                from_account_balance_after
            )

            to_balance_before = (
                to_account_balance_before
            )

            to_balance_after = (
                to_account_balance_after
            )

        # ========================================================
        # ORIGINAL BALANCE FIELDS
        # ========================================================

        saving_balance_before = get_balance(
            transfer,
            "saving_balance_before"
        )

        saving_balance_after = get_balance(
            transfer,
            "saving_balance_after"
        )

        account_balance_before = get_balance(
            transfer,
            "account_balance_before"
        )

        account_balance_after = get_balance(
            transfer,
            "account_balance_after"
        )

        # ========================================================
        # USER
        # ========================================================

        raw_transfer_user_id = transfer.get(
            "user_id"
        )

        transfer_user_id = (
            str(raw_transfer_user_id)
            if raw_transfer_user_id is not None
            else ""
        )

        # ========================================================
        # TRANSFER DATA
        # ========================================================

        transfer_data = {

            # ====================================================
            # IDENTITY
            # ====================================================

            "id": transfer_id,
            "_id": transfer_id,
            "user_id": transfer_user_id,

            # ====================================================
            # TYPE
            # ====================================================

            "transfer_type": transfer_type,
            "transaction_type": transaction_type,
            "direction": direction,

            # ====================================================
            # FROM
            # ====================================================

            "from_name": from_name,
            "from_type": from_type,

            "from_account_name": (
                from_name
                if from_type == "Account"
                else (
                    transfer.get(
                        "from_account_name"
                    )
                    or ""
                )
            ),

            "from_saving_name": (
                from_name
                if from_type == "Saving"
                else (
                    transfer.get(
                        "from_saving_name"
                    )
                    or ""
                )
            ),

            # ====================================================
            # TO
            # ====================================================

            "to_name": to_name,
            "to_type": to_type,

            "to_account_name": (
                to_name
                if to_type == "Account"
                else (
                    transfer.get(
                        "to_account_name"
                    )
                    or ""
                )
            ),

            "to_saving_name": (
                to_name
                if to_type == "Saving"
                else (
                    transfer.get(
                        "to_saving_name"
                    )
                    or ""
                )
            ),

            # ====================================================
            # AMOUNT
            # ====================================================

            "amount": amount,
            "currency": currency,

            # ====================================================
            # STATUS
            # ====================================================

            "status": status_display,

            # ====================================================
            # REFERENCE
            # ====================================================

            "reference_no": safe_string(reference),
            "reference": safe_string(reference),

            # ====================================================
            # DESCRIPTION
            # ====================================================

            "description": description,

            # ====================================================
            # DATE
            # ====================================================

            "created_at": date_info["iso"],

            "created_at_display": date_info["display"],

            # ====================================================
            # GENERIC BALANCES
            # ====================================================

            "from_balance_before":
                from_balance_before,

            "from_balance_after":
                from_balance_after,

            "to_balance_before":
                to_balance_before,

            "to_balance_after":
                to_balance_after,

            # ====================================================
            # ACCOUNT BALANCES
            # ====================================================

            "from_account_balance_before":
                from_account_balance_before,

            "from_account_balance_after":
                from_account_balance_after,

            "to_account_balance_before":
                to_account_balance_before,

            "to_account_balance_after":
                to_account_balance_after,

            # ====================================================
            # SAVING BALANCES
            # ====================================================

            "from_saving_balance_before":
                from_saving_balance_before,

            "from_saving_balance_after":
                from_saving_balance_after,

            "to_saving_balance_before":
                to_saving_balance_before,

            "to_saving_balance_after":
                to_saving_balance_after,

            # ====================================================
            # ORIGINAL DATABASE FIELDS
            # ====================================================

            "saving_balance_before":
                saving_balance_before,

            "saving_balance_after":
                saving_balance_after,

            "account_balance_before":
                account_balance_before,

            "account_balance_after":
                account_balance_after,

            # ====================================================
            # OBJECT IDS AS STRINGS
            # Useful for modal/detail page
            # ====================================================

            "from_account_id": (
                str(transfer.get("from_account"))
                if transfer.get("from_account")
                else ""
            ),

            "to_account_id": (
                str(transfer.get("to_account"))
                if transfer.get("to_account")
                else ""
            ),

            "from_saving_id": (
                str(transfer.get("from_saving"))
                if transfer.get("from_saving")
                else ""
            ),

            "to_saving_id": (
                str(transfer.get("to_saving"))
                if transfer.get("to_saving")
                else ""
            )
        }

        transfers.append(
            transfer_data
        )

    # ============================================================
    # SUMMARY
    # ============================================================

    total_transfers = len(transfers)

    total_amount = sum(
        safe_float(
            item.get("amount")
        )
        for item in transfers
    )

    total_deposits = sum(
        safe_float(item.get("amount"))
        for item in transfers
        if item.get("transaction_type") == "Deposit"
    )

    total_withdrawals = sum(
        safe_float(item.get("amount"))
        for item in transfers
        if item.get("transaction_type") == "Withdraw"
    )

    total_account_transfers = sum(
        safe_float(item.get("amount"))
        for item in transfers
        if item.get("transaction_type") == "Transfer"
    )

    deposit_count = sum(
        1
        for item in transfers
        if item.get("transaction_type") == "Deposit"
    )

    withdrawal_count = sum(
        1
        for item in transfers
        if item.get("transaction_type") == "Withdraw"
    )

    account_transfer_count = sum(
        1
        for item in transfers
        if item.get("transaction_type") == "Transfer"
    )

    # ============================================================
    # JSON SAFE
    # ============================================================

    transfers_json = json.dumps(
        transfers,
        default=str
    )

    # ============================================================
    # RENDER
    # ============================================================

    return render_template(

        "backend/pages/components/accounts/account_transfers.html",

        transfers=transfers,

        transfers_json=transfers_json,

        total_transfers=total_transfers,

        total_amount=total_amount,

        total_deposits=total_deposits,

        total_withdrawals=total_withdrawals,

        total_account_transfers=total_account_transfers,

        deposit_count=deposit_count,

        withdrawal_count=withdrawal_count,

        account_transfer_count=account_transfer_count
    )


@bp.route("/account/transfers/edit/<transfer_id>", methods=["GET", "POST"])
@login_required
def edit_account_transfer(transfer_id):

    from bson import ObjectId
    from datetime import datetime
    from flask import request, render_template, redirect, url_for, flash

    # ============================================================
    # VALIDATE TRANSFER ID
    # ============================================================

    try:
        transfer_object_id = ObjectId(transfer_id)

    except Exception:
        flash("Invalid transfer ID.", "error")
        return redirect(
            url_for("main.all_account_transfers")
        )

    # ============================================================
    # CURRENT USER
    # ============================================================

    current_user_id = str(current_user.id)

    # ============================================================
    # FIND TRANSFER
    # ============================================================

    transfer = mongo.db.account_transfers.find_one({
        "_id": transfer_object_id
    })

    if not transfer:

        flash("Transfer not found.", "error")

        return redirect(
            url_for("main.all_account_transfers")
        )

    # ============================================================
    # ACCESS CONTROL
    # ============================================================

    transfer_user_id = transfer.get("user_id")

    transfer_user_id_string = (
        str(transfer_user_id)
        if transfer_user_id is not None
        else ""
    )

    is_superadmin = (
        current_user.role == UserRole.superadmin.value
    )

    if not is_superadmin:

        if transfer_user_id_string != current_user_id:

            flash(
                "You are not allowed to edit this transfer.",
                "error"
            )

            return redirect(
                url_for("main.all_account_transfers")
            )

    # ============================================================
    # HELPER
    # ============================================================

    def safe_float(value, default=0.0):

        try:

            if value is None:
                return default

            return float(value)

        except (TypeError, ValueError):

            return default

    def safe_string(value, default=""):

        if value is None:
            return default

        return str(value)

    # ============================================================
    # GET ACCOUNT IDS
    # ============================================================

    account_ids = []

    for key in [
        "from_account",
        "to_account"
    ]:

        value = transfer.get(key)

        if value:

            value_string = str(value)

            if value_string not in account_ids:

                account_ids.append(value_string)

    # ============================================================
    # LOAD ACCOUNTS
    # ============================================================

    accounts = []

    for account_id in account_ids:

        try:

            account = mongo.db.accounts.find_one({
                "_id": ObjectId(account_id)
            })

            if account:

                accounts.append({
                    "id": str(account["_id"]),

                    "name": (
                        account.get("name")
                        or account.get("account_name")
                        or "Unnamed Account"
                    ),

                    "currency": (
                        account.get("currency")
                        or "USD"
                    )
                })

        except Exception:

            continue

    # ============================================================
    # LOAD ALL USER ACCOUNTS
    # Useful for EDIT FORM
    # ============================================================

    if is_superadmin:

        accounts_raw = list(
            mongo.db.accounts.find({}).sort(
                "name",
                1
            )
        )

    else:

        accounts_raw = list(
            mongo.db.accounts.find({
                "$or": [
                    {"user_id": current_user_id},
                    {"user_id": ObjectId(current_user_id)}
                ]
            }).sort(
                "name",
                1
            )
        )

    accounts = []

    for account in accounts_raw:

        accounts.append({

            "id": str(
                account.get("_id")
            ),

            "name": (
                account.get("name")
                or account.get("account_name")
                or "Unnamed Account"
            ),

            "currency": (
                account.get("currency")
                or "USD"
            ),

            "balance": safe_float(
                account.get("balance")
                or account.get("current_balance")
                or account.get("available_balance")
            )
        })

    # ============================================================
    # LOAD SAVINGS
    # ============================================================

    if is_superadmin:

        savings_raw = list(
            mongo.db.savings.find({}).sort(
                "name",
                1
            )
        )

    else:

        savings_raw = list(
            mongo.db.savings.find({
                "$or": [
                    {"user_id": current_user_id},
                    {"user_id": ObjectId(current_user_id)}
                ]
            }).sort(
                "name",
                1
            )
        )

    savings = []

    for saving in savings_raw:

        savings.append({

            "id": str(
                saving.get("_id")
            ),

            "name": (
                saving.get("name")
                or saving.get("saving_name")
                or saving.get("title")
                or "Unnamed Saving"
            ),

            "currency": (
                saving.get("currency")
                or "USD"
            ),

            "balance": safe_float(
                saving.get("balance")
                or saving.get("current_balance")
            )
        })

    # ============================================================
    # POST - UPDATE TRANSFER
    # ============================================================

    if request.method == "POST":

        transfer_type = (
            request.form.get("transfer_type")
            or transfer.get("transfer_type")
            or "account_to_account"
        )

        amount_raw = (
            request.form.get("amount")
        )

        currency = (
            request.form.get("currency")
            or transfer.get("currency")
            or "USD"
        )

        reference_no = (
            request.form.get("reference_no")
            or request.form.get("reference")
            or transfer.get("reference_no")
            or ""
        ).strip()

        description = (
            request.form.get("description")
            or ""
        ).strip()

        status = (
            request.form.get("status")
            or transfer.get("status")
            or "completed"
        )

        # ========================================================
        # VALIDATE AMOUNT
        # ========================================================

        try:

            amount = float(amount_raw)

            if amount <= 0:

                raise ValueError

        except (TypeError, ValueError):

            flash(
                "Please enter a valid amount.",
                "error"
            )

            return render_template(

                "backend/pages/components/accounts/edit_account_transfer.html",

                transfer=transfer,

                accounts=accounts,

                savings=savings
            )

        # ========================================================
        # BASE UPDATE
        # ========================================================

        update_data = {

            "transfer_type": transfer_type,

            "amount": amount,

            "currency": currency,

            "reference_no": reference_no,

            "reference": reference_no,

            "description": description,

            "status": status,

            "updated_at": datetime.utcnow()
        }

        # ========================================================
        # ACCOUNT → ACCOUNT
        # ========================================================

        if transfer_type == "account_to_account":

            from_account_id = (
                request.form.get("from_account")
            )

            to_account_id = (
                request.form.get("to_account")
            )

            if not from_account_id or not to_account_id:

                flash(
                    "Please select both source and destination accounts.",
                    "error"
                )

                return render_template(

                    "backend/pages/components/accounts/edit_account_transfer.html",

                    transfer=transfer,

                    accounts=accounts,

                    savings=savings
                )

            if from_account_id == to_account_id:

                flash(
                    "Source and destination accounts cannot be the same.",
                    "error"
                )

                return render_template(

                    "backend/pages/components/accounts/edit_account_transfer.html",

                    transfer=transfer,

                    accounts=accounts,

                    savings=savings
                )

            try:

                from_account_object_id = ObjectId(
                    from_account_id
                )

                to_account_object_id = ObjectId(
                    to_account_id
                )

            except Exception:

                flash(
                    "Invalid account selection.",
                    "error"
                )

                return render_template(

                    "backend/pages/components/accounts/edit_account_transfer.html",

                    transfer=transfer,

                    accounts=accounts,

                    savings=savings
                )

            update_data.update({

                "from_account":
                    from_account_object_id,

                "to_account":
                    to_account_object_id,

                "from_account_name":
                    next(
                        (
                            a["name"]
                            for a in accounts
                            if a["id"] == from_account_id
                        ),
                        ""
                    ),

                "to_account_name":
                    next(
                        (
                            a["name"]
                            for a in accounts
                            if a["id"] == to_account_id
                        ),
                        ""
                    )
            })

        # ========================================================
        # ACCOUNT → SAVING
        # ========================================================

        elif transfer_type == "account_to_saving":

            from_account_id = (
                request.form.get("from_account")
            )

            to_saving_id = (
                request.form.get("to_saving")
            )

            if not from_account_id or not to_saving_id:

                flash(
                    "Please select source account and destination saving.",
                    "error"
                )

                return render_template(

                    "backend/pages/components/accounts/edit_account_transfer.html",

                    transfer=transfer,

                    accounts=accounts,

                    savings=savings
                )

            try:

                from_account_object_id = ObjectId(
                    from_account_id
                )

                to_saving_object_id = ObjectId(
                    to_saving_id
                )

            except Exception:

                flash(
                    "Invalid account or saving selection.",
                    "error"
                )

                return render_template(

                    "backend/pages/components/accounts/edit_account_transfer.html",

                    transfer=transfer,

                    accounts=accounts,

                    savings=savings
                )

            update_data.update({

                "from_account":
                    from_account_object_id,

                "to_saving":
                    to_saving_object_id,

                "from_account_name":
                    next(
                        (
                            a["name"]
                            for a in accounts
                            if a["id"] == from_account_id
                        ),
                        ""
                    ),

                "to_saving_name":
                    next(
                        (
                            s["name"]
                            for s in savings
                            if s["id"] == to_saving_id
                        ),
                        ""
                    )
            })

        # ========================================================
        # SAVING → ACCOUNT
        # ========================================================

        elif transfer_type == "saving_to_account":

            from_saving_id = (
                request.form.get("from_saving")
            )

            to_account_id = (
                request.form.get("to_account")
            )

            if not from_saving_id or not to_account_id:

                flash(
                    "Please select source saving and destination account.",
                    "error"
                )

                return render_template(

                    "backend/pages/components/accounts/edit_account_transfer.html",

                    transfer=transfer,

                    accounts=accounts,

                    savings=savings
                )

            try:

                from_saving_object_id = ObjectId(
                    from_saving_id
                )

                to_account_object_id = ObjectId(
                    to_account_id
                )

            except Exception:

                flash(
                    "Invalid saving or account selection.",
                    "error"
                )

                return render_template(

                    "backend/pages/components/accounts/edit_account_transfer.html",

                    transfer=transfer,

                    accounts=accounts,

                    savings=savings
                )

            update_data.update({

                "from_saving":
                    from_saving_object_id,

                "to_account":
                    to_account_object_id,

                "from_saving_name":
                    next(
                        (
                            s["name"]
                            for s in savings
                            if s["id"] == from_saving_id
                        ),
                        ""
                    ),

                "to_account_name":
                    next(
                        (
                            a["name"]
                            for a in accounts
                            if a["id"] == to_account_id
                        ),
                        ""
                    )
            })

        else:

            flash(
                "Invalid transfer type.",
                "error"
            )

            return render_template(

                "backend/pages/components/accounts/edit_account_transfer.html",

                transfer=transfer,

                accounts=accounts,

                savings=savings
            )

        # ========================================================
        # UPDATE DATABASE
        # ========================================================

        mongo.db.account_transfers.update_one(

            {
                "_id": transfer_object_id
            },

            {
                "$set": update_data
            }

        )

        # ========================================================
        # SUCCESS
        # ========================================================

        flash(
            "Transfer updated successfully.",
            "success"
        )

        return redirect(
            url_for(
                "main.all_account_transfers"
            )
        )

    # ============================================================
    # PREPARE TEMPLATE TRANSFER
    # ============================================================

    transfer["id"] = str(
        transfer.get("_id")
    )

    transfer["from_account_id"] = (
        str(transfer.get("from_account"))
        if transfer.get("from_account")
        else ""
    )

    transfer["to_account_id"] = (
        str(transfer.get("to_account"))
        if transfer.get("to_account")
        else ""
    )

    transfer["from_saving_id"] = (
        str(transfer.get("from_saving"))
        if transfer.get("from_saving")
        else ""
    )

    transfer["to_saving_id"] = (
        str(transfer.get("to_saving"))
        if transfer.get("to_saving")
        else ""
    )

    # ============================================================
    # RENDER
    # ============================================================

    return render_template(

        "backend/pages/components/accounts/edit_account_transfer.html",

        transfer=transfer,

        accounts=accounts,

        savings=savings
    )

@bp.route("/saving-topup", methods=["POST"])
@login_required
def saving_topup():

    from bson import ObjectId
    from datetime import datetime
    from flask import request, jsonify
    import math
    import secrets

    # ============================================================
    # RESPONSE HELPERS
    # ============================================================

    def error_response(message, status=400):
        return jsonify({
            "success": False,
            "error": message,
            "message": message
        }), status

    # ============================================================
    # GET JSON DATA
    # ============================================================

    data = request.get_json(silent=True)

    if not data:
        return error_response(
            "No data provided.",
            400
        )

    saving_id = data.get("saving_id")
    account_id = data.get("account_id")
    amount = data.get("amount")

    # ============================================================
    # REQUIRED FIELDS
    # ============================================================

    if not saving_id:
        return error_response(
            "Saving account is required.",
            400
        )

    if not account_id:
        return error_response(
            "Source account is required.",
            400
        )

    if amount is None or amount == "":
        return error_response(
            "Amount is required.",
            400
        )

    # ============================================================
    # VALIDATE AMOUNT
    # ============================================================

    try:
        amount = float(amount)

    except (TypeError, ValueError):
        return error_response(
            "Invalid amount.",
            400
        )

    if not math.isfinite(amount):
        return error_response(
            "Invalid amount.",
            400
        )

    if amount <= 0:
        return error_response(
            "Amount must be greater than zero.",
            400
        )

    # ============================================================
    # OBJECT IDS
    # ============================================================

    try:

        saving_obj_id = ObjectId(
            str(saving_id)
        )

        account_obj_id = ObjectId(
            str(account_id)
        )

    except Exception:

        return error_response(
            "Invalid account or saving ID.",
            400
        )

    # ============================================================
    # CURRENT USER
    # ============================================================

    user_id = str(
        current_user.id
    )

    try:

        user_object_id = ObjectId(
            user_id
        )

    except Exception:

        user_object_id = None

    # ============================================================
    # USER FILTER
    # Supports STRING + ObjectId
    # ============================================================

    if current_user.role == UserRole.superadmin.value:

        user_filter = {}

    else:

        owner_conditions = [
            {
                "user_id": user_id
            }
        ]

        if user_object_id:

            owner_conditions.append({
                "user_id": user_object_id
            })

        user_filter = {
            "$or": owner_conditions
        }

    # ============================================================
    # GET SAVING
    # ============================================================

    saving_query = {
        "_id": saving_obj_id
    }

    saving_query.update(
        user_filter
    )

    saving = mongo.db.savings.find_one(
        saving_query
    )

    if not saving:

        return error_response(
            "Saving not found.",
            404
        )

    # ============================================================
    # GET SOURCE ACCOUNT
    # ============================================================

    account_query = {
        "_id": account_obj_id
    }

    account_query.update(
        user_filter
    )

    account = mongo.db.accounts.find_one(
        account_query
    )

    if not account:

        return error_response(
            "Source account not found.",
            404
        )

    # ============================================================
    # ACCOUNT BALANCE BEFORE
    # ============================================================

    try:

        account_balance_before = float(
            account.get("balance", 0) or 0
        )

    except (TypeError, ValueError):

        account_balance_before = 0.0

    # ============================================================
    # SAVING BALANCE BEFORE
    # ============================================================

    try:

        saving_balance_before = float(
            saving.get("current_balance", 0) or 0
        )

    except (TypeError, ValueError):

        saving_balance_before = 0.0

    # ============================================================
    # CURRENCY
    # ============================================================

    account_currency = (
        account.get("currency")
        or "USD"
    )

    saving_currency = (
        saving.get("currency")
        or account_currency
        or "USD"
    )

    # ============================================================
    # CURRENCY CHECK
    # ============================================================

    if (
        account_currency
        and saving_currency
        and account_currency != saving_currency
    ):

        return error_response(
            (
                "Currency mismatch. "
                f"Account uses {account_currency}, "
                f"Saving uses {saving_currency}."
            ),
            400
        )

    currency = (
        account_currency
        or saving_currency
        or "USD"
    )

    # ============================================================
    # CHECK ACCOUNT BALANCE
    # ============================================================

    if amount > account_balance_before:

        return error_response(
            (
                "Insufficient account balance. "
                f"Available "
                f"{currency} "
                f"{account_balance_before:,.2f}"
            ),
            400
        )

    # ============================================================
    # NAMES
    # ============================================================

    account_name = (
        account.get("name")
        or account.get("account_name")
        or "Unknown Account"
    )

    saving_name = (
        saving.get("name")
        or saving.get("saving_name")
        or saving.get("title")
        or "Unknown Saving"
    )

    # ============================================================
    # NEW BALANCES
    # ============================================================

    account_balance_after = (
        account_balance_before - amount
    )

    saving_balance_after = (
        saving_balance_before + amount
    )

    # ============================================================
    # REFERENCE
    # ============================================================

    reference_no = (
        "SAV-"
        + datetime.utcnow().strftime(
            "%Y%m%d%H%M%S"
        )
        + "-"
        + secrets.token_hex(3).upper()
    )

    # ============================================================
    # TIMESTAMP
    # ============================================================

    now = datetime.utcnow()

    # ============================================================
    # DEBUG BEFORE TRANSACTION
    # ============================================================

    print(
        "\n=================================================="
    )

    print(
        "SAVING TOPUP START"
    )

    print(
        "USER:",
        user_id
    )

    print(
        "REFERENCE:",
        reference_no
    )

    print(
        "FROM ACCOUNT:",
        account_name,
        str(account_obj_id)
    )

    print(
        "TO SAVING:",
        saving_name,
        str(saving_obj_id)
    )

    print(
        "AMOUNT:",
        amount,
        currency
    )

    print(
        "ACCOUNT BEFORE:",
        account_balance_before
    )

    print(
        "ACCOUNT AFTER:",
        account_balance_after
    )

    print(
        "SAVING BEFORE:",
        saving_balance_before
    )

    print(
        "SAVING AFTER:",
        saving_balance_after
    )

    print(
        "==================================================\n"
    )

    # ============================================================
    # STEP 1
    # ACCOUNT → REMOVE MONEY
    #
    # IMPORTANT:
    # Atomic balance check
    # ============================================================

    account_result = mongo.db.accounts.update_one(

        {
            "_id": account_obj_id,

            **user_filter,

            "balance": {
                "$gte": amount
            }
        },

        {
            "$inc": {
                "balance": -amount
            },

            "$set": {
                "updated_at": now
            }
        }

    )

    if account_result.modified_count != 1:

        return error_response(
            (
                "Failed to remove money from source "
                "account. The balance may have changed."
            ),
            400
        )

    # ============================================================
    # STEP 2
    # SAVING → ADD MONEY
    # ============================================================

    saving_result = mongo.db.savings.update_one(

        {
            "_id": saving_obj_id,

            **user_filter
        },

        {
            "$inc": {
                "current_balance": amount
            },

            "$set": {
                "updated_at": now
            }
        }

    )

    # ============================================================
    # ROLLBACK IF SAVING UPDATE FAILED
    # ============================================================

    if saving_result.modified_count != 1:

        mongo.db.accounts.update_one(

            {
                "_id": account_obj_id
            },

            {
                "$inc": {
                    "balance": amount
                },

                "$set": {
                    "updated_at": now
                }
            }

        )

        return error_response(
            (
                "Failed to add money to saving. "
                "Account balance has been restored."
            ),
            500
        )

    # ============================================================
    # STEP 3
    # CREATE MASTER TRANSFER RECORD
    # ============================================================

    try:

        transfer_document = {

            # ====================================================
            # IDENTIFICATION
            # ====================================================

            "user_id":
                user_id,

            "transfer_type":
                "account_to_saving",

            "direction":
                "deposit",

            # ====================================================
            # SOURCE ACCOUNT
            # ====================================================

            "from_account":
                account_obj_id,

            "from_account_name":
                account_name,

            "from_type":
                "Account",

            # ====================================================
            # DESTINATION SAVING
            # ====================================================

            "to_saving":
                saving_obj_id,

            "to_saving_name":
                saving_name,

            "to_type":
                "Saving",

            # ====================================================
            # AMOUNT
            # ====================================================

            "amount":
                amount,

            "currency":
                currency,

            # ====================================================
            # STATUS
            # ====================================================

            "status":
                "completed",

            # ====================================================
            # REFERENCE
            # ====================================================

            "reference":
                reference_no,

            "reference_no":
                reference_no,

            "transfer_no":
                reference_no,

            # ====================================================
            # DESCRIPTION
            # ====================================================

            "description":
                "Account to Saving deposit",

            "note":
                (
                    f"Deposit from "
                    f"{account_name} "
                    f"to "
                    f"{saving_name}"
                ),

            # ====================================================
            # ACCOUNT BALANCE AUDIT
            # ====================================================

            "account_balance_before":
                account_balance_before,

            "account_balance_after":
                account_balance_after,

            # ====================================================
            # SAVING BALANCE AUDIT
            # ====================================================

            "saving_balance_before":
                saving_balance_before,

            "saving_balance_after":
                saving_balance_after,

            # ====================================================
            # CREATED / UPDATED
            # ====================================================

            "created_at":
                now,

            "updated_at":
                now
        }

        # --------------------------------------------------------
        # INSERT MASTER
        # --------------------------------------------------------

        transfer_result = (
            mongo.db.account_transfers.insert_one(
                transfer_document
            )
        )

        transfer_id = (
            transfer_result.inserted_id
        )

    except Exception as transfer_error:

        print(
            "ACCOUNT TRANSFER INSERT ERROR:",
            repr(transfer_error)
        )

        # ========================================================
        # ROLLBACK SAVING
        # ========================================================

        mongo.db.savings.update_one(

            {
                "_id": saving_obj_id
            },

            {
                "$inc": {
                    "current_balance": -amount
                },

                "$set": {
                    "updated_at": now
                }
            }

        )

        # ========================================================
        # ROLLBACK ACCOUNT
        # ========================================================

        mongo.db.accounts.update_one(

            {
                "_id": account_obj_id
            },

            {
                "$inc": {
                    "balance": amount
                },

                "$set": {
                    "updated_at": now
                }
            }

        )

        return error_response(
            (
                "Transfer history could not be saved. "
                "The transaction was rolled back."
            ),
            500
        )

    # ============================================================
    # STEP 4
    # GENERAL TRANSACTION RECORD
    #
    # This allows the normal transactions report
    # to also understand the movement.
    # ============================================================

    try:

        transaction_document = {

            # ====================================================
            # USER
            # ====================================================

            "user_id":
                user_id,

            # ====================================================
            # ACCOUNT
            # ====================================================

            "account_id":
                account_obj_id,

            # ====================================================
            # TRANSACTION TYPE
            # ====================================================

            "transaction_type":
                "transfer_out",

            "type":
                "transfer_out",

            # ====================================================
            # AMOUNT
            # ====================================================

            "amount":
                amount,

            "currency":
                currency,

            # ====================================================
            # CATEGORY
            # ====================================================

            "category":
                "Saving Transfer",

            "item":
                f"Saving Deposit - {saving_name}",

            # ====================================================
            # DESCRIPTION
            # ====================================================

            "description":
                (
                    f"Transfer from "
                    f"{account_name} "
                    f"to "
                    f"{saving_name}"
                ),

            "note":
                (
                    f"Money moved from "
                    f"{account_name} "
                    f"to "
                    f"{saving_name}"
                ),

            # ====================================================
            # REFERENCE
            # ====================================================

            "reference_no":
                reference_no,

            "reference":
                reference_no,

            # ====================================================
            # TRANSFER ID
            # ====================================================

            "transfer_id":
                transfer_id,

            # ====================================================
            # ROUTE
            # ====================================================

            "from_account":
                account_obj_id,

            "from_account_name":
                account_name,

            "to_saving":
                saving_obj_id,

            "to_saving_name":
                saving_name,

            # ====================================================
            # BALANCE AUDIT
            # ====================================================

            "account_balance_before":
                account_balance_before,

            "account_balance_after":
                account_balance_after,

            "saving_balance_before":
                saving_balance_before,

            "saving_balance_after":
                saving_balance_after,

            # ====================================================
            # DATE
            # ====================================================

            "date":
                now,

            "created_at":
                now,

            "updated_at":
                now,

            "status":
                True
        }

        mongo.db.transactions.insert_one(
            transaction_document
        )

    except Exception as transaction_error:

        print(
            "GENERAL TRANSACTION INSERT ERROR:",
            repr(transaction_error)
        )

        # ========================================================
        # IMPORTANT
        #
        # Master transfer already exists.
        # Do NOT rollback balances here.
        #
        # The master account_transfers record is the
        # source of truth.
        # ========================================================

    # ============================================================
    # STEP 5
    # SAVING TRANSACTION HISTORY
    # ============================================================

    try:

        saving_transaction_document = {

            "user_id":
                user_id,

            "saving_id":
                saving_obj_id,

            "account_id":
                account_obj_id,

            "transaction_type":
                "deposit",

            "amount":
                amount,

            "currency":
                currency,

            "description":
                (
                    f"Deposit from "
                    f"{account_name}"
                ),

            "note":
                (
                    f"Saving deposit from "
                    f"{account_name}"
                ),

            "reference_no":
                reference_no,

            "reference":
                reference_no,

            "transfer_id":
                transfer_id,

            "from_account":
                account_obj_id,

            "from_account_name":
                account_name,

            "saving_balance_before":
                saving_balance_before,

            "saving_balance_after":
                saving_balance_after,

            "account_balance_before":
                account_balance_before,

            "account_balance_after":
                account_balance_after,

            "date":
                now,

            "created_at":
                now,

            "updated_at":
                now,

            "status":
                True
        }

        mongo.db.saving_transactions.insert_one(
            saving_transaction_document
        )

    except Exception as saving_history_error:

        print(
            "SAVING TRANSACTION HISTORY ERROR:",
            repr(saving_history_error)
        )

    # ============================================================
    # FINAL RESPONSE
    # ============================================================

    response_data = {

        "success":
            True,

        "message":
            (
                "Money moved from Account → Saving "
                "successfully."
            ),

        # ========================================================
        # MASTER TRANSFER
        # ========================================================

        "transfer_id":
            str(transfer_id),

        "transfer_type":
            "account_to_saving",

        "direction":
            "deposit",

        "status":
            "completed",

        # ========================================================
        # REFERENCE
        # ========================================================

        "reference":
            reference_no,

        "reference_no":
            reference_no,

        # ========================================================
        # SOURCE
        # ========================================================

        "from_account":
            account_name,

        "from_account_id":
            str(account_obj_id),

        "from_type":
            "Account",

        # ========================================================
        # DESTINATION
        # ========================================================

        "to_saving":
            saving_name,

        "to_saving_id":
            str(saving_obj_id),

        "to_type":
            "Saving",

        # ========================================================
        # MONEY
        # ========================================================

        "amount":
            amount,

        "currency":
            currency,

        # ========================================================
        # ACCOUNT AUDIT
        # ========================================================

        "account_balance_before":
            account_balance_before,

        "account_balance_after":
            account_balance_after,

        # ========================================================
        # SAVING AUDIT
        # ========================================================

        "saving_balance_before":
            saving_balance_before,

        "saving_balance_after":
            saving_balance_after,

        # ========================================================
        # DATE
        # ========================================================

        "created_at":
            now.isoformat()
    }

    # ============================================================
    # DEBUG FINAL REPORT
    # ============================================================

    print(
        "\n=================================================="
    )

    print(
        "SAVING TOPUP COMPLETED"
    )

    print(
        "Transfer ID:",
        str(transfer_id)
    )

    print(
        "Reference:",
        reference_no
    )

    print(
        "Account:",
        account_name
    )

    print(
        "Saving:",
        saving_name
    )

    print(
        "Amount:",
        f"{currency} {amount:,.2f}"
    )

    print(
        "Account:",
        f"{account_balance_before:,.2f}",
        "→",
        f"{account_balance_after:,.2f}"
    )

    print(
        "Saving:",
        f"{saving_balance_before:,.2f}",
        "→",
        f"{saving_balance_after:,.2f}"
    )

    print(
        "==================================================\n"
    )

    return jsonify(
        response_data
    ), 200



@bp.route("/saving-withdraw", methods=["POST"])
@login_required
def saving_withdraw():

    # ============================================================
    # GET JSON DATA
    # ============================================================

    data = request.get_json(silent=True)

    if not data:

        return jsonify({
            "success": False,
            "error": "No data provided"
        }), 400


    saving_id = data.get("saving_id")
    account_id = data.get("account_id")
    amount = data.get("amount")


    # ============================================================
    # REQUIRED FIELDS
    # ============================================================

    if not saving_id:

        return jsonify({
            "success": False,
            "error": "Saving account is required."
        }), 400


    if not account_id:

        return jsonify({
            "success": False,
            "error": "Destination account is required."
        }), 400


    if amount is None or amount == "":

        return jsonify({
            "success": False,
            "error": "Amount is required."
        }), 400


    # ============================================================
    # AMOUNT VALIDATION
    # ============================================================

    try:

        amount = float(amount)

    except (TypeError, ValueError):

        return jsonify({
            "success": False,
            "error": "Invalid amount."
        }), 400


    if amount <= 0:

        return jsonify({
            "success": False,
            "error": "Amount must be greater than zero."
        }), 400


    # ============================================================
    # PREVENT NaN / INFINITY
    # ============================================================

    import math

    if not math.isfinite(amount):

        return jsonify({
            "success": False,
            "error": "Invalid amount."
        }), 400


    # ============================================================
    # OBJECT ID VALIDATION
    # ============================================================

    try:

        saving_obj_id = ObjectId(
            str(saving_id)
        )

        account_obj_id = ObjectId(
            str(account_id)
        )

    except Exception:

        return jsonify({
            "success": False,
            "error": "Invalid saving or account ID."
        }), 400


    # ============================================================
    # CURRENT USER
    # ============================================================

    user_id = str(
        current_user.id
    )


    # ============================================================
    # USER FILTER
    # Supports STRING + ObjectId
    # ============================================================

    try:

        user_object_id = ObjectId(
            user_id
        )

        user_filter = {

            "$or": [

                {
                    "user_id": user_id
                },

                {
                    "user_id": user_object_id
                }

            ]

        }

    except Exception:

        user_filter = {

            "user_id": user_id

        }


    # ============================================================
    # GET SAVING
    # ============================================================

    saving = mongo.db.savings.find_one({

        "_id": saving_obj_id,

        **user_filter

    })


    if not saving:

        return jsonify({

            "success": False,
            "error": "Saving not found."

        }), 404


    # ============================================================
    # GET DESTINATION ACCOUNT
    # ============================================================

    account = mongo.db.accounts.find_one({

        "_id": account_obj_id,

        **user_filter

    })


    if not account:

        return jsonify({

            "success": False,
            "error": "Destination account not found."

        }), 404


    # ============================================================
    # CURRENT BALANCES
    # ============================================================

    saving_balance = float(

        saving.get(
            "current_balance",
            0
        ) or 0

    )


    account_balance = float(

        account.get(
            "balance",
            0
        ) or 0

    )


    # ============================================================
    # CHECK SAVING BALANCE
    # ============================================================

    if amount > saving_balance:

        return jsonify({

            "success": False,

            "error":
                "Insufficient saving balance. "
                f"Available "
                f"{saving.get('currency', 'USD')} "
                f"{saving_balance:,.2f}"

        }), 400


    # ============================================================
    # NAMES
    # ============================================================

    saving_name = (

        saving.get("name")

        or saving.get("saving_name")

        or saving.get("title")

        or "Saving"

    )


    account_name = (

        account.get("name")

        or account.get("account_name")

        or "Unknown Account"

    )


    # ============================================================
    # CURRENCY
    # ============================================================

    currency = (

        saving.get("currency")

        or account.get("currency")

        or "USD"

    )


    # ============================================================
    # REFERENCE NUMBER
    # ============================================================

    reference_no = (

        "SAV-"

        +

        datetime.utcnow().strftime(
            "%Y%m%d%H%M%S"
        )

        +

        "-"

        +

        secrets.token_hex(3).upper()

    )


    # ============================================================
    # BALANCES BEFORE
    # ============================================================

    saving_balance_before = saving_balance

    account_balance_before = account_balance


    # ============================================================
    # BALANCES AFTER
    # ============================================================

    new_saving_balance = (

        saving_balance
        -
        amount

    )


    new_account_balance = (

        account_balance
        +
        amount

    )


    # ============================================================
    # STEP 1
    # REMOVE MONEY FROM SAVING
    # ============================================================

    saving_result = mongo.db.savings.update_one(

        {

            "_id": saving_obj_id,

            **user_filter,

            "current_balance": {
                "$gte": amount
            }

        },

        {

            "$inc": {

                "current_balance":
                    -amount

            },

            "$set": {

                "updated_at":
                    datetime.utcnow()

            }

        }

    )


    if saving_result.modified_count != 1:

        return jsonify({

            "success": False,

            "error":
                "Failed to remove money from saving."

        }), 500


    # ============================================================
    # STEP 2
    # ADD MONEY TO ACCOUNT
    # ============================================================

    account_result = mongo.db.accounts.update_one(

        {

            "_id": account_obj_id,

            **user_filter

        },

        {

            "$inc": {

                "balance":
                    amount

            },

            "$set": {

                "updated_at":
                    datetime.utcnow()

            }

        }

    )


    # ============================================================
    # ACCOUNT UPDATE FAILED → ROLLBACK SAVING
    # ============================================================

    if account_result.modified_count != 1:

        mongo.db.savings.update_one(

            {

                "_id":
                    saving_obj_id

            },

            {

                "$inc": {

                    "current_balance":
                        amount

                }

            }

        )


        return jsonify({

            "success": False,

            "error":
                "Failed to add money to destination account. "
                "Saving balance has been restored."

        }), 500


    # ============================================================
    # STEP 3
    # SAVE ONLY IN account_transfers
    # ============================================================

    try:

        transfer_result = mongo.db.account_transfers.insert_one({

            # ----------------------------------------------------
            # USER
            # ----------------------------------------------------

            "user_id":
                user_id,


            # ----------------------------------------------------
            # TRANSFER TYPE
            # ----------------------------------------------------

            "transfer_type":
                "saving_to_account",


            # ----------------------------------------------------
            # DIRECTION
            # ----------------------------------------------------

            "direction":
                "withdraw",


            # ----------------------------------------------------
            # SOURCE SAVING
            # ----------------------------------------------------

            "from_saving":
                saving_obj_id,

            "from_saving_name":
                saving_name,


            # ----------------------------------------------------
            # DESTINATION ACCOUNT
            # ----------------------------------------------------

            "to_account":
                account_obj_id,

            "to_account_name":
                account_name,


            # ----------------------------------------------------
            # AMOUNT
            # ----------------------------------------------------

            "amount":
                amount,


            # ----------------------------------------------------
            # CURRENCY
            # ----------------------------------------------------

            "currency":
                currency,


            # ----------------------------------------------------
            # STATUS
            # ----------------------------------------------------

            "status":
                "completed",


            # ----------------------------------------------------
            # REFERENCE
            # ----------------------------------------------------

            "reference":
                reference_no,

            "reference_no":
                reference_no,


            # ----------------------------------------------------
            # DESCRIPTION
            # ----------------------------------------------------

            "description":
                "Saving withdrawal to account",


            # ----------------------------------------------------
            # BALANCES
            # ----------------------------------------------------

            "saving_balance_before":
                saving_balance_before,

            "saving_balance_after":
                new_saving_balance,

            "account_balance_before":
                account_balance_before,

            "account_balance_after":
                new_account_balance,


            # ----------------------------------------------------
            # DATE
            # ----------------------------------------------------

            "created_at":
                datetime.utcnow(),

            "updated_at":
                datetime.utcnow()

        })


    except Exception as transfer_error:

        print(
            "Saving withdrawal history error:",
            transfer_error
        )


        # ========================================================
        # ROLLBACK ACCOUNT
        # ========================================================

        mongo.db.accounts.update_one(

            {
                "_id":
                    account_obj_id
            },

            {

                "$inc": {

                    "balance":
                        -amount

                }

            }

        )


        # ========================================================
        # ROLLBACK SAVING
        # ========================================================

        mongo.db.savings.update_one(

            {
                "_id":
                    saving_obj_id
            },

            {

                "$inc": {

                    "current_balance":
                        amount

                }

            }

        )


        return jsonify({

            "success": False,

            "error":
                "Withdrawal could not be recorded. "
                "The transaction was rolled back."

        }), 500


    # ============================================================
    # SUCCESS
    # ============================================================

    return jsonify({

        "success": True,

        "message":
            "Money moved from Saving → Account successfully.",

        "reference":
            reference_no,

        "amount":
            amount,

        "currency":
            currency,

        "saving":
            saving_name,

        "account":
            account_name,

        "saving_balance":
            new_saving_balance,

        "account_balance":
            new_account_balance

    }), 200



def clean_category(cat):

    return {

        "_id": str(
            cat.get("_id")
        ),

        "name": cat.get(
            "name",
            ""
        ),

        "type": cat.get(
            "type",
            ""
        ),

        "items":[

            str(i)

            for i in (
                cat.get("items") or []
            )

            if i

        ]

    }






def get_month_range(year=None, month=None):

    # ==========================
    # CURRENT DATE DEFAULT
    # ==========================

    now = datetime.utcnow()


    if not year:

        year = now.year


    if not month:

        month = now.month



    # ==========================
    # MONTH START
    # ==========================

    start = datetime(
        int(year),
        int(month),
        1
    )



    # ==========================
    # NEXT MONTH
    # ==========================

    if int(month) == 12:

        end = datetime(
            int(year) + 1,
            1,
            1
        )

    else:

        end = datetime(
            int(year),
            int(month) + 1,
            1
        )


    return start, end



def calculate_savings_balance(records):


    total=0

    deposits=0

    withdrawals=0



    for item in records:


        amount=float(
            item.get(
                "amount",
                0
            )
        )


        if item.get(
            "transaction_type"
        )=="deposit":


            deposits += amount

            total += amount



        elif item.get(
            "transaction_type"
        )=="withdrawal":


            withdrawals += amount

            total -= amount



    return {

        "balance":total,

        "deposit":deposits,

        "withdrawal":withdrawals

    }





def calculate_transaction_summary(transactions):


    result={

        "income":0,

        "expense":0,

        "income_categories":defaultdict(float),

        "expense_categories":defaultdict(float),

        "largest_income":None,

        "largest_expense":None

    }



    for trx in transactions:


        amount=float(
            trx.get(
                "amount",
                0
            )
        )


        trx_type=trx.get(
            "transaction_type"
        )


        category=trx.get(
            "category",
            "Unknown"
        )



        if trx_type=="income":


            result["income"] += amount


            result[
                "income_categories"
            ][category]+=amount



            if (

                result["largest_income"] is None

                or amount >

                result["largest_income"]["amount"]

            ):

                result["largest_income"]={

                    "amount":amount,

                    "data":trx

                }




        elif trx_type=="expense":


            result["expense"] += amount


            result[
                "expense_categories"
            ][category]+=amount



            if (

                result["largest_expense"] is None

                or amount >

                result["largest_expense"]["amount"]

            ):


                result["largest_expense"]={

                    "amount":amount,

                    "data":trx

                }


    return result






def get_biggest_category(data):


    if not data:

        return None,0



    key=max(

        data,

        key=data.get

    )


    return key,data[key]



@bp.route("/transactions")
@login_required
def transaction_list():

    from datetime import datetime
    from bson import ObjectId


    # ==================================================
    # USER
    # ==================================================

    user_object_id = ObjectId(
        current_user.id
    )

    user_string_id = str(
        current_user.id
    )




    # ==================================================
    # MONTH / YEAR FILTER
    # ==================================================

    now = datetime.utcnow()


    # ==========================================
    # FIRST TRANSACTION OF USER
    # ==========================================

    first_transaction = mongo.db.transactions.find_one(

        {
            "user_id": ObjectId(current_user.id),
            "status": True
        },

        sort=[
            ("date", 1)
        ]

    )



    # Default start
    SYSTEM_START_MONTH = 1

    FIRST_YEAR = now.year



    if first_transaction:


        first_date = first_transaction.get("date")


        if first_date:


            SYSTEM_START_MONTH = first_date.month

            FIRST_YEAR = first_date.year






    # ==========================================
    # CURRENT SELECTED FILTER
    # ==========================================

    year = int(

        request.args.get(

            "year",

            now.year

        )

    )



    month = int(

        request.args.get(

            "month",

            now.month

        )

    )



    # ==========================================
    # PREVENT FUTURE DATE
    # ==========================================

    if year > now.year:

        year = now.year



    if year == now.year and month > now.month:

        month = now.month






    # ==================================================
    # MONTH RANGE
    # ==================================================

    month_start, month_end = get_month_range(

        year,

        month

    )






    # ==================================================
    # MONTH LIST
    # ==================================================

    month_names = [

        "January",
        "February",
        "March",
        "April",
        "May",
        "June",
        "July",
        "August",
        "September",
        "October",
        "November",
        "December"

    ]



    months = []



    for i in range(12):


        month_number = (

            SYSTEM_START_MONTH + i - 1

        ) % 12 + 1



        # ===============================
        # REMOVE FUTURE MONTHS
        # ===============================

        if year == now.year and month_number > now.month:

            continue



        # ===============================
        # REMOVE BEFORE FIRST TRANSACTION
        # ===============================

        if year == FIRST_YEAR and month_number < SYSTEM_START_MONTH:

            continue



        months.append({

            "number": month_number,

            "name": month_names[month_number - 1]

        })






    # ==================================================
    # YEAR LIST
    # ==================================================

    years = list(

        range(

            FIRST_YEAR,

            now.year + 1

        )

    )


    # ==================================================
    # FILTERS
    # ==================================================

    transaction_type = request.args.get(
        "type"
    )


    account_id = request.args.get(
        "account_id"
    )


    category = request.args.get(
        "category"
    )


    item = request.args.get(
        "item"
    )



    # ==================================================
    # TRANSACTION QUERY
    # ==================================================

    transaction_query = {

        "user_id": user_object_id,

        "status": True,

        "date": {

            "$gte": month_start,

            "$lt": month_end

        }

    }



    filters = {

        "transaction_type":
        transaction_type,

        "category":
        category,

        "item":
        item

    }



    for key,value in filters.items():

        if value:

            transaction_query[key]=value



    if account_id:

        try:

            transaction_query["account_id"] = ObjectId(
                account_id
            )

        except:

            pass




    # ==================================================
    # TRANSACTIONS
    # ==================================================

    transactions = list(

        mongo.db.transactions.find(
            transaction_query
        )
        .sort(
            "date",
            -1
        )

    )



    # ==================================================
    # ACCOUNTS
    # ==================================================

    accounts = list(

        mongo.db.accounts.find({

            "user_id": user_object_id,

            "status": True

        })

    )



    account_map = {

        str(account["_id"]):

        account.get(
            "name",
            "Unknown"
        )

        for account in accounts

    }



    for transaction in transactions:

        transaction["account_name"] = (

            account_map.get(

                str(
                    transaction.get(
                        "account_id"
                    )
                ),

                "Unknown"

            )

        )





    # ==================================================
    # CATEGORIES
    # ==================================================

    categories = [

        clean_category(category)

        for category in mongo.db.categories.find({

            "$or":[

                {
                    "user_id":user_object_id
                },

                {
                    "user_id":user_string_id
                }

            ],

            "status":True

        })

    ]





    # ==================================================
    # SAVINGS
    # ==================================================

    saving_transactions=list(

        mongo.db.saving_transactions.find({

            "$or":[

                {
                    "user_id":user_object_id
                },

                {
                    "user_id":user_string_id
                }

            ],

            "status":True

        })

    )



    saving_summary = calculate_savings_balance(

        saving_transactions

    )





    # ==================================================
    # ANALYTICS
    # ==================================================

    summary = calculate_transaction_summary(

        transactions

    )

 


    #waa gii hore

    total_income = summary["income"]

    total_expense = summary["expense"]


    net_profit = (

        total_income

        -

        total_expense

    )



    total_balance = sum(

        float(

            account.get(
                "balance",
                0
            )

        )

        for account in accounts

    )



    income_category, income_amount = get_biggest_category(

        summary["income_categories"]

    )



    expense_category, expense_amount = get_biggest_category(

        summary["expense_categories"]

    )





    # ==================================================
    # ALERTS
    # ==================================================

    warnings=[]



    if total_balance < 10:

        warnings.append({

            "type":"danger",

            "title":"Low Balance",

            "message":

            f"Available balance ${total_balance:.2f}"

        })




    if total_expense > total_income:

        warnings.append({

            "type":"warning",

            "title":"Overspending",

            "message":

            "Expense is higher than income"

        })







    # ==================================================
    # MONTH CARD
    # ==================================================

    monthly_card={

        "month":
        month_start.strftime(
            "%B %Y"
        ),

        "income":
        total_income,

        "expense":
        total_expense,

        "profit":
        net_profit,

        "transactions":
        len(transactions),

        "saving":
        saving_summary["balance"],

        "deposit":
        saving_summary["deposit"],

        "withdrawal":
        saving_summary["withdrawal"]

    }


    # ==================================================
    # ITEM ANALYTICS
    # ==================================================

    expense_items = {}
    income_items = {}


    for transaction in transactions:

        item = (
            transaction.get("item")
            or "Unknown"
        ).strip()


        amount = float(
            transaction.get(
                "amount",
                0
            )
        )


        transaction_type = (
            transaction.get(
                "transaction_type",
                ""
            )
            .lower()
            .strip()
        )


        if transaction_type == "expense":

            expense_items[item] = (
                expense_items.get(item, 0)
                + amount
            )


        elif transaction_type == "income":

            income_items[item] = (
                income_items.get(item, 0)
                + amount
            )



    # ==================================================
    # SORT ITEMS (OUTSIDE LOOP)
    # ==================================================

    expense_item_list = sorted(

        expense_items.items(),

        key=lambda x: x[1],

        reverse=True

    )



    income_item_list = sorted(

        income_items.items(),

        key=lambda x: x[1],

        reverse=True

    )




    # ==================================================
    # BIGGEST EXPENSE ITEM
    # ==================================================

    biggest_expense_item = "-"

    biggest_expense_item_amount = 0



    if expense_item_list:


        biggest_expense_item = (
            expense_item_list[0][0]
        )


        biggest_expense_item_amount = (
            expense_item_list[0][1]
        )





    # ==================================================
    # BIGGEST INCOME ITEM
    # ==================================================

    biggest_income_item = "-"

    biggest_income_item_amount = 0



    if income_item_list:


        biggest_income_item = (
            income_item_list[0][0]
        )


        biggest_income_item_amount = (
            income_item_list[0][1]
        )





    # ==================================================
    # ITEM RECOMMENDATIONS
    # ==================================================

    item_recommendations = []



    # ===============================
    # EXPENSE
    # ===============================

    if biggest_expense_item_amount > 0:


        expense_percent = (

            biggest_expense_item_amount

            /

            max(total_expense, 1)

        ) * 100



        if expense_percent >= 50:


            item_recommendations.append({

                "type": "danger",

                "title": "High Spending Item",

                "message":
                    f"{biggest_expense_item} consumed "
                    f"{expense_percent:.1f}% "
                    "of your expenses."

            })



        elif expense_percent >= 30:


            item_recommendations.append({

                "type": "warning",

                "title": "Monitor Spending",

                "message":
                    f"{biggest_expense_item} accounts for "
                    f"{expense_percent:.1f}% "
                    "of total expenses."

            })





    # ===============================
    # INCOME
    # ===============================

    if biggest_income_item_amount > 0:


        income_percent = (

            biggest_income_item_amount

            /

            max(total_income,1)

        ) * 100



        if income_percent >= 50:


            item_recommendations.append({

                "type": "success",

                "title": "Main Income Source",

                "message":
                    f"{biggest_income_item} generates "
                    f"{income_percent:.1f}% "
                    "of your income."

            })


    # ===============================
    # INCOME
    # ===============================

    if biggest_income_item_amount > 0:

        income_percent = (
            biggest_income_item_amount
            / max(total_income, 1)
        ) * 100

        if income_percent >= 60:

            item_recommendations.append({

                "type": "info",

                "title": "Income Concentration",

                "message":
                    f"{biggest_income_item} generates "
                    f"{income_percent:.1f}% "
                    "of your income."

            })


    # wareeg 5



    # ==================================================
    # RENDER
    # ==================================================

    return render_template(

        "backend/pages/components/transactions/all_transactions.html",


        transactions=transactions,


        accounts=accounts,


        categories=categories,



        year=year,

        month=month,

        months=months,
years=years,


        monthly_card=monthly_card,



        total_balance=total_balance,

        current_balance=total_balance,


        total_income=total_income,

        total_expense=total_expense,


        net_profit=net_profit,



        total_savings=saving_summary["balance"],


        total_deposit=saving_summary["deposit"],


        total_withdrawal=saving_summary["withdrawal"],



        total_transactions=len(transactions),



        biggest_income_category=income_category,

        biggest_income_amount=income_amount,



        biggest_expense_category=expense_category,

        biggest_expense_amount=expense_amount,



        largest_income=summary["largest_income"],

        largest_expense=summary["largest_expense"],



        warnings=warnings,



        selected_type=transaction_type,

        selected_account=account_id,

        selected_category=category,

        selected_item=item,

        expense_item_list=expense_item_list,

income_item_list=income_item_list,

biggest_expense_item=biggest_expense_item,

biggest_expense_item_amount=biggest_expense_item_amount,

biggest_income_item=biggest_income_item,

biggest_income_item_amount=biggest_income_item_amount,

item_recommendations=item_recommendations,


        month_name=month_start.strftime(
            "%B %Y"
        )

    )




@bp.route("/persons")
@login_required
def persons():

    import re
    from collections import defaultdict
    from bson import ObjectId

    # ============================================================
    # PERSONS STORAGE
    # ============================================================

    persons_dict = defaultdict(lambda: {
        "_id": "",
        "name": "",
        "total_income": 0.0,
        "total_expense": 0.0,
        "balance": 0.0,
        "transactions": 0
    })

    # ============================================================
    # CURRENT USER
    # ============================================================

    current_user_id = str(current_user.id)

    try:
        current_user_object_id = ObjectId(
            current_user.id
        )
    except Exception:
        current_user_object_id = None

    # ============================================================
    # USER CONDITIONS
    # ============================================================

    user_conditions = [
        {
            "user_id": current_user_id
        }
    ]

    if current_user_object_id is not None:
        user_conditions.append({
            "user_id": current_user_object_id
        })

    # ============================================================
    # SYSTEM DESCRIPTION DETECTOR
    #
    # Anything that is clearly an accounting/system description
    # must NEVER become a person.
    # ============================================================

    def is_system_description(value):

        if value is None:
            return False

        text = str(value).strip().lower()

        if not text:
            return False

        # --------------------------------------------------------
        # NORMALIZE SPACES
        # --------------------------------------------------------

        text = re.sub(
            r"\s+",
            " ",
            text
        ).strip()

        # --------------------------------------------------------
        # TRANSFER DESCRIPTIONS
        # --------------------------------------------------------

        transfer_patterns = [

            # Transfer From ...
            r"^transfer\s+from\b",

            # Transfer To ...
            r"^transfer\s+to\b",

            # Transferred From ...
            r"^transferred\s+from\b",

            # Transferred To ...
            r"^transferred\s+to\b",

            # Money Transferred From ...
            r"^money\s+transferred\s+from\b",

            # Money Transferred To ...
            r"^money\s+transferred\s+to\b",

            # Money Transfer From ...
            r"^money\s+transfer\s+from\b",

            # Money Transfer To ...
            r"^money\s+transfer\s+to\b",

            # Account Transfer ...
            r"^account\s+transfer\b",

            # Bank Transfer ...
            r"^bank\s+transfer\b",

            # Wallet Transfer ...
            r"^wallet\s+transfer\b",

            # Fund Transfer ...
            r"^fund\s+transfer\b",

            # Funds Transfer ...
            r"^funds\s+transfer\b",

            # Internal Transfer ...
            r"^internal\s+transfer\b",

            # Transfered ... common typo
            r"^transfered\s+from\b",
            r"^transfered\s+to\b",

        ]

        for pattern in transfer_patterns:

            if re.search(
                pattern,
                text,
                flags=re.IGNORECASE
            ):
                return True

        # --------------------------------------------------------
        # TRANSFER WORD ANYWHERE
        #
        # Example:
        # Salaam Bank -> Primary Wallet Money Transferred To
        # --------------------------------------------------------

        transfer_phrases = [

            "money transferred to",
            "money transferred from",

            "money transfer to",
            "money transfer from",

            "transferred to",
            "transferred from",

            "transfer to",
            "transfer from",

            "account transfer",
            "bank transfer",
            "wallet transfer",
            "fund transfer",
            "funds transfer",
            "internal transfer",

        ]

        for phrase in transfer_phrases:

            if phrase in text:
                return True

        # --------------------------------------------------------
        # PAYMENT / DEPOSIT / WITHDRAWAL SYSTEM DESCRIPTIONS
        # --------------------------------------------------------

        system_patterns = [

            r"^payment\s+from\b",
            r"^payment\s+to\b",

            r"^paid\s+to\b",
            r"^paid\s+from\b",

            r"^deposit\s+from\b",
            r"^deposit\s+to\b",

            r"^withdrawal\s+from\b",
            r"^withdrawal\s+to\b",

            r"^withdraw\s+from\b",
            r"^withdraw\s+to\b",

            r"^received\s+from\b",
            r"^received\s+to\b",

            r"^sent\s+to\b",
            r"^sent\s+from\b",

            r"^cash\s+transfer\b",
            r"^cash\s+movement\b",

            r"^opening\s+balance\b",
            r"^opening\s+transaction\b",

        ]

        for pattern in system_patterns:

            if re.search(
                pattern,
                text,
                flags=re.IGNORECASE
            ):
                return True

        return False

    # ============================================================
    # NORMALIZE PERSON NAME
    # ============================================================

    def normalize_person_name(
        value,
        allow_system_description=False
    ):

        if value is None:
            return ""

        value = str(value).strip()

        if not value:
            return ""

        # --------------------------------------------------------
        # Remove leading "By"
        #
        # By Cumar
        # by Cumar
        # BY Cumar
        # By    Cumar
        # --------------------------------------------------------

        value = re.sub(
            r"^by\s+",
            "",
            value,
            flags=re.IGNORECASE
        ).strip()

        # --------------------------------------------------------
        # Remove extra spaces
        # --------------------------------------------------------

        value = re.sub(
            r"\s+",
            " ",
            value
        ).strip()

        if not value:
            return ""

        # --------------------------------------------------------
        # Do NOT allow system descriptions
        # --------------------------------------------------------

        if not allow_system_description:

            if is_system_description(value):
                return ""

        # --------------------------------------------------------
        # Normalize capitalization
        # --------------------------------------------------------

        return value.title()

    # ============================================================
    # ADD PERSON HELPER
    # ============================================================

    def add_person(
        transaction_persons,
        seen_names,
        value,
        allow_system_description=False
    ):

        normalized = normalize_person_name(
            value,
            allow_system_description=allow_system_description
        )

        if not normalized:
            return

        name_key = normalized.casefold()

        if name_key in seen_names:
            return

        seen_names.add(
            name_key
        )

        transaction_persons.append(
            normalized
        )

    # ============================================================
    # 1. NORMAL TRANSACTIONS
    # ============================================================

    transactions = mongo.db.transactions.find({

        "$or": user_conditions

    }).sort(
        "date",
        -1
    )

    # ============================================================
    # PROCESS NORMAL TRANSACTIONS
    # ============================================================

    for trx in transactions:

        # ========================================================
        # AMOUNT
        # ========================================================

        try:

            amount = float(
                trx.get("amount", 0) or 0
            )

        except (TypeError, ValueError):

            amount = 0.0

        # ========================================================
        # TRANSACTION TYPE
        # ========================================================

        transaction_type = str(
            trx.get("transaction_type")
            or trx.get("type")
            or "expense"
        ).strip().lower()

        if transaction_type not in (
            "income",
            "expense"
        ):

            transaction_type = "expense"

        # ========================================================
        # RAW VALUES
        # ========================================================

        raw_person_name = str(
            trx.get("person_name") or ""
        ).strip()

        raw_description = str(
            trx.get("description") or ""
        ).strip()

        raw_note = str(
            trx.get("note") or ""
        ).strip()

        # ========================================================
        # COLLECT PERSONS
        # ========================================================

        transaction_persons = []

        seen_names = set()

        # ========================================================
        # 1. PERSON_NAME
        #
        # This field is explicitly intended for a person.
        # ========================================================

        if raw_person_name:

            add_person(
                transaction_persons,
                seen_names,
                raw_person_name,
                allow_system_description=False
            )

        # ========================================================
        # 2. DESCRIPTION
        #
        # Description is ONLY accepted if it is not a system
        # description.
        #
        # Therefore:
        #
        # Samiro
        #       -> accepted
        #
        # Transfer From Salaam Bank ...
        #       -> rejected
        #
        # Money Transferred To Primary Hormuud Walet
        #       -> rejected
        # ========================================================

        if raw_description:

            if not is_system_description(
                raw_description
            ):

                add_person(
                    transaction_persons,
                    seen_names,
                    raw_description,
                    allow_system_description=False
                )

        # ========================================================
        # 3. NOTE
        #
        # Example:
        #
        # By Cumar Cumar Omar
        #
        # becomes:
        #
        # Cumar Cumar Omar
        #
        # NOTE:
        # System descriptions are also rejected here.
        # ========================================================

        if raw_note:

            if not is_system_description(
                raw_note
            ):

                add_person(
                    transaction_persons,
                    seen_names,
                    raw_note,
                    allow_system_description=False
                )

        # ========================================================
        # NO PERSON FOUND
        # ========================================================

        if not transaction_persons:
            continue

        # ========================================================
        # ADD TRANSACTION TO EACH PERSON
        # ========================================================

        for person_name in transaction_persons:

            person = persons_dict[
                person_name
            ]

            # ----------------------------------------------------
            # BASIC DATA
            # ----------------------------------------------------

            person["_id"] = person_name

            person["name"] = person_name

            person["transactions"] += 1

            # ----------------------------------------------------
            # INCOME
            # ----------------------------------------------------

            if transaction_type == "income":

                person["total_income"] += amount

            # ----------------------------------------------------
            # EXPENSE
            # ----------------------------------------------------

            else:

                person["total_expense"] += amount

    # ============================================================
    # 2. MANUAL / OPENING PERSON TRANSACTIONS
    # ============================================================

    old_transactions = mongo.db.person_opening_transactions.find({

        "$or": user_conditions

    }).sort(
        "date",
        -1
    )

    # ============================================================
    # PROCESS MANUAL TRANSACTIONS
    # ============================================================

    for old in old_transactions:

        # ========================================================
        # PERSON NAME
        # ========================================================

        person_name = normalize_person_name(
            old.get("person_name"),
            allow_system_description=False
        )

        if not person_name:
            continue

        # ========================================================
        # AMOUNT
        # ========================================================

        try:

            amount = float(
                old.get("amount", 0) or 0
            )

        except (TypeError, ValueError):

            amount = 0.0

        # ========================================================
        # TYPE
        # ========================================================

        transaction_type = str(
            old.get("type")
            or old.get("transaction_type")
            or "expense"
        ).strip().lower()

        if transaction_type not in (
            "income",
            "expense"
        ):

            transaction_type = "expense"

        # ========================================================
        # PERSON DATA
        # ========================================================

        person = persons_dict[
            person_name
        ]

        person["_id"] = person_name

        person["name"] = person_name

        person["transactions"] += 1

        # ========================================================
        # INCOME
        # ========================================================

        if transaction_type == "income":

            person["total_income"] += amount

        # ========================================================
        # EXPENSE
        # ========================================================

        else:

            person["total_expense"] += amount

    # ============================================================
    # FINAL DATA
    # ============================================================

    persons = []

    for person in persons_dict.values():

        # ========================================================
        # BALANCE
        # ========================================================

        person["balance"] = (
            person["total_income"]
            -
            person["total_expense"]
        )

        # ========================================================
        # ROUND VALUES
        # ========================================================

        person["total_income"] = round(
            person["total_income"],
            2
        )

        person["total_expense"] = round(
            person["total_expense"],
            2
        )

        person["balance"] = round(
            person["balance"],
            2
        )

        persons.append(
            person
        )

    # ============================================================
    # SORT
    # ============================================================

    persons.sort(
        key=lambda x: x["name"].casefold()
    )

    # ============================================================
    # RENDER
    # ============================================================

    return render_template(
        "backend/pages/components/transactions/persons.html",
        persons=persons,
        
    )


@bp.route("/persons/delete/<path:person_name>", methods=["POST", "GET"])
@login_required
def delete_person(person_name):

    import re
    from bson import ObjectId
    from flask import redirect, url_for, flash

    # ============================================================
    # CURRENT USER
    # ============================================================

    current_user_id = str(current_user.id)

    try:
        current_user_object_id = ObjectId(
            current_user_id
        )
    except Exception:
        current_user_object_id = None

    # ============================================================
    # NORMALIZE PERSON NAME
    # ============================================================

    person_name = str(
        person_name or ""
    ).strip()

    # Remove "By"
    person_name = re.sub(
        r"^by\s*",
        "",
        person_name,
        flags=re.IGNORECASE
    )

    person_name = " ".join(
        person_name.split()
    ).strip()

    if not person_name:

        flash(
            "Invalid person name.",
            "error"
        )

        return redirect(
            url_for("main.persons")
        )

    # ============================================================
    # USER QUERY
    # ============================================================

    user_conditions = [
        {
            "user_id": current_user_id
        }
    ]

    if current_user_object_id:

        user_conditions.append({
            "user_id": current_user_object_id
        })

    # ============================================================
    # FIND TRANSACTIONS BELONGING TO PERSON
    # ============================================================

    transactions_collection = (
        mongo.db.transactions
    )

    transactions = transactions_collection.find({

        "$and": [

            {
                "$or": user_conditions
            },

            {
                "$or": [

                    {
                        "person_name": {
                            "$regex": (
                                "^\\s*by\\s*"
                                + re.escape(person_name)
                                + "\\s*$"
                            ),
                            "$options": "i"
                        }
                    },

                    {
                        "person_name": {
                            "$regex": (
                                "^\\s*"
                                + re.escape(person_name)
                                + "\\s*$"
                            ),
                            "$options": "i"
                        }
                    },

                    {
                        "description": {
                            "$regex": (
                                "^\\s*by\\s*"
                                + re.escape(person_name)
                                + "\\s*$"
                            ),
                            "$options": "i"
                        }
                    },

                    {
                        "description": {
                            "$regex": (
                                "^\\s*"
                                + re.escape(person_name)
                                + "\\s*$"
                            ),
                            "$options": "i"
                        }
                    },

                    {
                        "note": {
                            "$regex": (
                                "^\\s*by\\s*"
                                + re.escape(person_name)
                                + "\\s*$"
                            ),
                            "$options": "i"
                        }
                    },

                    {
                        "note": {
                            "$regex": (
                                "^\\s*"
                                + re.escape(person_name)
                                + "\\s*$"
                            ),
                            "$options": "i"
                        }
                    }

                ]
            }

        ]

    })

    transaction_ids = [
        transaction["_id"]
        for transaction in transactions
    ]

    # ============================================================
    # DELETE NORMAL TRANSACTIONS
    # ============================================================

    deleted_transactions = 0

    if transaction_ids:

        result = transactions_collection.delete_many({

            "_id": {
                "$in": transaction_ids
            }

        })

        deleted_transactions = (
            result.deleted_count
        )

    # ============================================================
    # DELETE PERSON OPENING / MANUAL TRANSACTIONS
    # ============================================================

    opening_collection = (
        mongo.db.person_opening_transactions
    )

    # Case-insensitive exact person name
    opening_query = {

        "$and": [

            {
                "$or": user_conditions
            },

            {
                "person_name": {
                    "$regex": (
                        "^\\s*by\\s*"
                        + re.escape(person_name)
                        + "\\s*$"
                    ),
                    "$options": "i"
                }

            }

        ]

    }

    opening_result = (
        opening_collection.delete_many(
            opening_query
        )
    )

    deleted_opening_transactions = (
        opening_result.deleted_count
    )

    # ============================================================
    # TOTAL
    # ============================================================

    total_deleted = (
        deleted_transactions
        +
        deleted_opening_transactions
    )

    # ============================================================
    # FLASH MESSAGE
    # ============================================================

    if total_deleted > 0:

        flash(
            f"Person '{person_name}' and "
            f"{total_deleted} transaction(s) were deleted successfully.",
            "success"
        )

    else:

        flash(
            f"No transactions found for '{person_name}'.",
            "warning"
        )

    # ============================================================
    # REDIRECT
    # ============================================================

    return redirect(
        url_for("main.persons")
    )


@bp.route("/person/<person_name>/invoice")
@login_required
def person_invoice(person_name):

    person_name = person_name.strip()


    user_query = {
        "$or": [
            {
                "user_id": str(current_user.id)
            },
            {
                "user_id": ObjectId(current_user.id)
            }
        ]
    }


    total_income = 0
    total_expense = 0

    invoices = []



    # ================================
    # NORMAL TRANSACTIONS
    # ================================

    normal_transactions = list(
        mongo.db.transactions.find({

            **user_query,

            "$or": [

                {
                    "description": {
                        "$regex": person_name,
                        "$options": "i"
                    }
                },

                {
                    "person_name": {
                        "$regex": person_name,
                        "$options": "i"
                    }
                },

                {
                    "note": {
                        "$regex": person_name,
                        "$options": "i"
                    }
                }

            ]

        })
    )





    # ================================
    # OPENING / MANUAL TRANSACTIONS
    # ================================

    opening_transactions = list(
        mongo.db.person_opening_transactions.find({

            "user_id": ObjectId(current_user.id),

            "person_name": {
                "$regex": person_name,
                "$options": "i"
            }

        })
    )






    # ================================
    # NORMAL
    # ================================

    for t in normal_transactions:


        amount = float(
            t.get("amount", 0)
        )


        t_type = t.get(
            "transaction_type",
            "expense"
        )


        if t_type == "income":

            total_income += amount

        else:

            total_expense += amount



        invoices.append({

            "date": t.get("date"),

            "item": t.get("item") or "Transaction",

            "reference": "NORMAL",

            "type": t_type,

            "amount": amount,

            "note": t.get("note")

        })







    # ================================
    # OPENING / MANUAL
    # ================================

    for t in opening_transactions:


        amount = float(
            t.get("amount", 0)
        )


        t_type = t.get(
            "type",
            "expense"
        )


        if t_type == "income":

            total_income += amount

        else:

            total_expense += amount




        invoices.append({

            "date": t.get("date"),

            "item": t.get("item") or "Opening Balance",

            "reference": "MANUAL",

            "type": t_type,

            "amount": amount,

            "note": t.get("note")

        })







    # ================================
    # LATEST DATE FIRST
    # ================================

    invoices = sorted(

        invoices,

        key=lambda x: x.get("date") or datetime.min,

        reverse=True

    )






    balance = (
        total_income -
        total_expense
    )





    return render_template(

        "backend/pages/components/transactions/person_invoice.html",

        person_name=person_name,

        invoices=invoices,

        total_income=total_income,

        total_expense=total_expense,

        balance=balance,

        now=now_eat()

    )



@bp.route("/person/manual/add", methods=["GET", "POST"])
@login_required
def add_manual_person_transaction():

    if request.method == "POST":

        # =========================
        # FORM DATA
        # =========================

        person_name = request.form.get(
            "person_name",
            ""
        ).strip()

        transaction_type = request.form.get(
            "transaction_type",
            "expense"
        )

        category = request.form.get(
            "category",
            "Person Payment"
        ).strip()

        item = request.form.get(
            "item",
            ""
        ).strip()

        note = request.form.get(
            "note",
            ""
        ).strip()

        try:
            amount = float(
                request.form.get(
                    "amount",
                    0
                )
            )
        except (ValueError, TypeError):
            amount = 0

        # =========================
        # VALIDATION
        # =========================

        if not person_name or amount <= 0:

            flash(
                "Person and amount required.",
                "danger"
            )

            return redirect(request.url)

        # =========================
        # USER SELECTED DATE & TIME
        # =========================

        date_value = request.form.get(
            "date",
            ""
        ).strip()

        if date_value:

            try:

                transaction_date = datetime.strptime(
                    date_value,
                    "%Y-%m-%dT%H:%M"
                )

            except ValueError:

                flash(
                    "Invalid date and time.",
                    "danger"
                )

                return redirect(request.url)

        else:

            transaction_date = now_eat().replace(
                tzinfo=None
            )

        # =========================
        # CLEAN PERSON NAME
        # =========================

        person_name = (
            person_name
            .replace("By ", "")
            .replace("by ", "")
            .strip()
            .title()
        )

        # =========================
        # INSERT
        # =========================

        mongo.db.person_opening_transactions.insert_one({

            "user_id": ObjectId(current_user.id),

            "person_name": person_name,

            "type": transaction_type,

            "category": category,

            "amount": amount,

            "item": item,

            "note": note,

            "source": "manual",

            # User selected Date & Time
            "date": transaction_date,

            # Record created time
            "created_at": now_eat()

        })

        flash(
            "Person transaction added successfully.",
            "success"
        )

        return redirect(
            url_for("main.persons")
        )

    return render_template(

        "backend/pages/components/transactions/add_person_manual.html",

        today=now_eat().replace(
            tzinfo=None
        ).strftime("%Y-%m-%dT%H:%M")

    )


@bp.route("/person-opening-transactions")
@login_required
def person_opening_transactions():

    try:

        user_id = ObjectId(
            current_user.id
        )

    except Exception:

        abort(404)



    # ======================================
    # GET TRANSACTIONS
    # LATEST FIRST
    # ======================================

    transactions = list(

        mongo.db.person_opening_transactions.find({

            "user_id": user_id

        }).sort(

            [
                ("date", -1),          # Latest date first
                ("created_at", -1)     # Latest created first
            ]

        )

    )



    return render_template(

        "backend/pages/components/transactions/person_opening_transactions.html",

        transactions=transactions,

        now=now_eat()

    )



@bp.route("/person-opening-transactions/edit/<id>", methods=["GET", "POST"])
@login_required
def edit_person_opening_transaction(id):

    try:
        transaction_id = ObjectId(id)
        user_id = ObjectId(current_user.id)

    except Exception:
        abort(404)

    # =========================
    # GET TRANSACTION
    # =========================

    transaction = mongo.db.person_opening_transactions.find_one({

        "_id": transaction_id,
        "user_id": user_id

    })

    if not transaction:
        abort(404)

    # =========================
    # UPDATE
    # =========================

    if request.method == "POST":

        person_name = request.form.get(
            "person_name",
            ""
        ).strip().title()

        trx_type = request.form.get(
            "type",
            "expense"
        )

        category = request.form.get(
            "category",
            "Person Payment"
        ).strip()

        item = request.form.get(
            "item",
            ""
        ).strip()

        note = request.form.get(
            "note",
            ""
        ).strip()

        try:
            amount = float(
                request.form.get(
                    "amount",
                    0
                )
            )
        except (ValueError, TypeError):

            flash(
                "Invalid amount.",
                "danger"
            )

            return redirect(request.url)

        if not person_name or amount <= 0:

            flash(
                "Person and amount required.",
                "danger"
            )

            return redirect(request.url)

        # =========================
        # DATE & TIME
        # =========================

        date_value = request.form.get(
            "date",
            ""
        ).strip()

        if date_value:

            try:

                transaction_datetime = datetime.strptime(
                    date_value,
                    "%Y-%m-%dT%H:%M"
                )

            except ValueError:

                flash(
                    "Invalid date and time.",
                    "danger"
                )

                return redirect(request.url)

        else:

            transaction_datetime = transaction.get(
                "date",
                now_eat().replace(tzinfo=None)
            )

        # =========================
        # UPDATE DATABASE
        # =========================

        mongo.db.person_opening_transactions.update_one(

            {
                "_id": transaction_id,
                "user_id": user_id
            },

            {
                "$set": {

                    "person_name": person_name,

                    "type": trx_type,

                    "category": category,

                    "amount": amount,

                    "item": item,

                    "note": note,

                    # User selected date & time
                    "date": transaction_datetime,

                    # Update timestamp
                    "updated_at": now_eat()

                }
            }

        )

        flash(
            "Person opening transaction updated successfully.",
            "success"
        )

        return redirect(
            url_for("main.person_opening_transactions")
        )

    # =========================
    # FORMAT DATE FOR datetime-local
    # =========================

    if transaction.get("date"):

        if hasattr(transaction["date"], "tzinfo") and transaction["date"].tzinfo:

            transaction["date"] = transaction["date"].replace(
                tzinfo=None
            )

    return render_template(

        "backend/pages/components/transactions/edit_person_opening_transaction.html",

        transaction=transaction

    )




