@bp.route("/person/<person_id>/ledger")
@login_required
def person_ledger(person_id):

    # =========================
    # CLEAN PERSON NAME
    # =========================

    person_name = str(person_id).strip()

    person_name = re.sub(
        r"^by\s+",
        "",
        person_name,
        flags=re.IGNORECASE
    )

    person_name = person_name.strip().title()



    person_regex = rf"^\s*(?:by\s+)?{re.escape(person_name)}\s*$"




    user_filter = {

        "$or": [

            {
                "user_id": str(current_user.id)
            },

            {
                "user_id": ObjectId(current_user.id)
            }

        ]

    }




    # =========================
    # TRANSACTIONS
    # =========================

    transactions = list(

        mongo.db.transactions.find({

            **user_filter,

            "$or": [

                {
                    "description": {
                        "$regex": person_regex,
                        "$options": "i"
                    }
                },

                {
                    "person_name": {
                        "$regex": person_regex,
                        "$options": "i"
                    }
                },

                {
                    "note": {
                        "$regex": person_regex,
                        "$options": "i"
                    }
                }

            ]

        })

    )






    # =========================
    # OPENING / MANUAL
    # =========================

    old_transactions = list(

        mongo.db.person_opening_transactions.find({

            "user_id": ObjectId(current_user.id),

            "person_name": {
                "$regex": person_regex,
                "$options": "i"
            }

        })

    )





    ledger = []


    total_income = 0

    total_expense = 0





    # =========================
    # NORMAL TRANSACTIONS
    # =========================

    for t in transactions:


        amount = float(
            t.get("amount", 0) or 0
        )


        trx_type = t.get(
            "transaction_type",
            "expense"
        )



        if trx_type == "income":

            total_income += amount

        else:

            total_expense += amount





        ledger.append({

            "date": t.get("date"),

            "type": trx_type,

            "category": t.get("category"),

            "item": t.get("item"),

            "amount": amount,

            "note": t.get("description") or t.get("note"),

            "source": "Transaction"

        })








    # =========================
    # OPENING / MANUAL
    # =========================

    for t in old_transactions:


        amount = float(
            t.get("amount", 0) or 0
        )



        trx_type = t.get(
            "type",
            "expense"
        )



        if trx_type == "income":

            total_income += amount

        else:

            total_expense += amount





        ledger.append({

            "date": t.get("date"),

            "type": trx_type,

            "category": t.get(
                "category",
                "Opening Balance"
            ),

            "item": t.get("item"),


            "amount": amount,


            "note": t.get("note"),


            "source": "Excel / Manual"

        })







    # =========================
    # DATE CONVERTER
    # =========================

    def convert_date(value):

        if isinstance(value, datetime):

            return value



        if isinstance(value, str):

            formats = [

                "%Y-%m-%dT%H:%M",

                "%Y-%m-%d",

                "%Y-%m-%d %H:%M:%S"

            ]


            for fmt in formats:

                try:

                    return datetime.strptime(
                        value,
                        fmt
                    )

                except:

                    continue



        return datetime.min






    # =========================
    # SORT LATEST FIRST
    # =========================

    ledger.sort(

        key=lambda x: convert_date(
            x.get("date")
        ),

        reverse=True

    )







    balance = (

        total_income -

        total_expense

    )






    return render_template(

        "backend/pages/components/transactions/person_ledger.html",

        person_name=person_name,

        ledger=ledger,

        total_income=total_income,

        total_expense=total_expense,

        balance=balance,

        now=now_eat()

    )



@bp.route("/add-transaction", methods=["GET", "POST"])
@login_required
def add_transaction():
    user_oid = ObjectId(current_user.id)

    if request.method == "POST":
        account_id = request.form.get("account_id")
        transaction_type = request.form.get("transaction_type")
        category_id = request.form.get("category")
        item = request.form.get("item")
        amount = request.form.get("amount")
        description = request.form.get("description", "")
        note = request.form.get("note", "")
        reference_no = request.form.get("reference_no")

        if not account_id or not category_id or not amount:
            flash("Account, Category and Amount are required.", "danger")
            return redirect(url_for("main.add_transaction"))
        
        # Gudaha POST
        cat_doc = mongo.db.categories.find_one({"_id": ObjectId(category_id)})
        if cat_doc.get("type") != transaction_type:
            flash("Category-gan kuma haboona Type-ka aad dooratay!", "danger")
            return redirect(url_for("main.add_transaction"))

        try:
            amount = float(amount)
        except ValueError:
            flash("Invalid amount", "danger")
            return redirect(url_for("main.add_transaction"))

        # 🔥 CATEGORY VALIDATION
        category_doc = mongo.db.categories.find_one({
            "_id": ObjectId(category_id),
            "user_id": user_oid
        })

        if not category_doc:
            flash("Invalid category", "danger")
            return redirect(url_for("main.add_transaction"))

        # 🔥 ITEM VALIDATION
        # 🔥 ITEM VALIDATION
        if item:
            # 1. Soo saar list-ka saxda ah
            raw_items = category_doc.get("items", [])
            
            # Haddii ay tahay JSON string, u beddel list
            if isinstance(raw_items, str):
                try:
                    items = json.loads(raw_items)
                except:
                    items = []
            else:
                items = raw_items

            # 2. Nadiifi dhammaan items-ka si ay u noqdaan strings nadiif ah
            # Tani waxay ka saaraysaa quotes-ka iyo brackets-ka aan loo baahnayn
            clean_items = [str(i).strip('[]"\' ') for i in items]

            # 3. Hadda isbarbar dhig
            if item.strip() not in clean_items:
                flash(f"Invalid item: '{item}' maaha mid ku jira category-ga.", "danger")
                return redirect(url_for("main.add_transaction"))
        # 🔥 BALANCE VALIDATION (Halkan ayaan ku daray)
        if transaction_type == "expense":
            account_doc = mongo.db.accounts.find_one({
                "_id": ObjectId(account_id),
                "user_id": user_oid
            })
            if not account_doc or account_doc.get("balance", 0) < amount:
                flash(f"Digniin: Akaunkan balance-kiisu waa {account_doc.get('balance', 0)}. Ma samayn kartid expense ka badan lacagtaas!", "danger")
                return redirect(url_for("main.add_transaction"))

        # 🔥 SAVE TRANSACTION WITH SESSION (Atomicity)
        try:
            with mongo.db.client.start_session() as session:
                with session.start_transaction():
                    # 1. Diyaarinta Data
                    data = Transaction().add(
                        user_id=current_user.id,
                        account_id=account_id,
                        transaction_type=transaction_type,
                        category=category_doc["name"],
                        item=item,
                        amount=amount,
                        description=description,
                        note=note,
                        reference_no=reference_no
                    )
                    data["user_id"] = user_oid
                    data["account_id"] = ObjectId(account_id)

                    # 2. Insert Transaction
                    mongo.db.transactions.insert_one(data, session=session)

                    # 3. Update Balance
                    inc_val = amount if transaction_type == "income" else -amount
                    mongo.db.accounts.update_one(
                        {"_id": ObjectId(account_id)},
                        {"$inc": {"balance": inc_val}},
                        session=session
                    )
            
            flash("Transaction saved successfully", "success")
            return redirect(url_for("main.transaction_list"))
        
        except Exception as e:
            flash(f"Error saving transaction: {str(e)}", "danger")
            return redirect(url_for("main.add_transaction"))

    # GET Request: Fetch and Clean Categories
    # GET Request: Fetch and Clean Categories
    accounts = list(mongo.db.accounts.find({"user_id": user_oid}))
    categories_raw = list(mongo.db.categories.find({"user_id": user_oid}))

    categories = []
    for cat in categories_raw:
        items = cat.get("items", [])
        
        # Haddii ay tahay JSON string, u beddel list
        if isinstance(items, str):
            try:
                items = json.loads(items)
            except:
                items = []
                
        # Hubi in items ay yihiin list dhab ah (haddii ay ku jiraan brackets dhexda)
        clean_items = []
        if isinstance(items, list):
            for i in items:
                # Ka saar brackets iyo quotes dheeraad ah
                clean_item = str(i).replace('[', '').replace(']', '').replace("'", "").replace('"', "").strip()
                if clean_item:
                    clean_items.append(clean_item)
                    
        cat["items"] = clean_items
        categories.append(clean_category(cat))

        

    return render_template(
        "backend/pages/components/transactions/add_transaction.html",
        accounts=accounts,
        categories=categories
    )


@bp.route("/edit-transaction/<id>", methods=["GET", "POST"])
@login_required
def edit_transaction(id):
    user_oid = ObjectId(current_user.id)

    # =========================
    # GET TRANSACTION
    # =========================
    transaction = mongo.db.transactions.find_one(
        {
            "_id": ObjectId(id),
            "user_id": user_oid
        }
    )

    if not transaction:
        flash("Transaction not found", "danger")
        return redirect(url_for("main.transaction_list"))

    # =========================
    # POST
    # =========================
    if request.method == "POST":

        account_id = request.form.get("account_id")
        transaction_type = request.form.get("transaction_type")
        category_id = request.form.get("category")
        item = request.form.get("item")

        amount = float(request.form.get("amount", 0))

        description = request.form.get(
            "description",
            ""
        )

        note = request.form.get(
            "note",
            ""
        )

        reference_no = request.form.get(
            "reference_no",
            ""
        )


        # Date
        date_str = request.form.get("date")

        if date_str:
            try:
                transaction_date = datetime.strptime(
                    date_str,
                    "%Y-%m-%dT%H:%M"
                )
            except:
                transaction_date = datetime.utcnow()

        else:
            transaction_date = datetime.utcnow()


        # Status
        status = True if request.form.get("status") else False

        # =========================
        # BALANCE CHECK FIX
        # =========================

        if transaction_type == "expense":

            account = mongo.db.accounts.find_one(
                {
                    "_id": ObjectId(account_id)
                }
            )

            if account:


                current_balance = account.get(
                    "balance",
                    0
                )


                available_balance = current_balance



                # Haddii account kii hore yahay isla account-ka
                if (
                    transaction["transaction_type"] == "expense"
                    and str(transaction["account_id"]) == account_id
                ):

                    available_balance += transaction["amount"]



                if amount > available_balance:

                    flash(
                        "Balance-ka akaunkan kuma filna!",
                        "danger"
                    )

                    return redirect(
                        url_for(
                            "main.edit_transaction",
                            id=id
                        )
                    )



        # =========================
        # CATEGORY CHECK
        # =========================

        category_doc = mongo.db.categories.find_one(
            {
                "_id": ObjectId(category_id),
                "user_id": user_oid
            }
        )


        if not category_doc:

            flash(
                "Invalid category",
                "danger"
            )

            return redirect(
                url_for(
                    "main.edit_transaction",
                    id=id
                )
            )



        try:

            with mongo.db.client.start_session() as session:

                with session.start_transaction():


                    old_amount = transaction["amount"]

                    old_type = transaction["transaction_type"]



                    # =========================
                    # RESTORE OLD BALANCE
                    # =========================

                    if old_type == "income":

                        revert = -old_amount

                    else:

                        revert = old_amount



                    mongo.db.accounts.update_one(
                        {
                            "_id": transaction["account_id"]
                        },
                        {
                            "$inc": {
                                "balance": revert
                            }
                        },
                        session=session
                    )



                    # =========================
                    # UPDATE TRANSACTION
                    # =========================

                    mongo.db.transactions.update_one(
                        {
                            "_id": ObjectId(id)
                        },
                        {
                            "$set": {

                                "account_id": ObjectId(account_id),

                                "transaction_type": transaction_type,

                                "category": category_doc["name"],

                                "item": item,

                                "amount": amount,


                                "description": description,

                                "note": note,

                                "reference_no": reference_no,

                                "date": transaction_date,

                                "status": status,


                                "updated_at": datetime.utcnow()
                            }
                        },
                        session=session
                    )



                    # =========================
                    # APPLY NEW BALANCE
                    # =========================

                    if transaction_type == "income":

                        new_value = amount

                    else:

                        new_value = -amount



                    mongo.db.accounts.update_one(
                        {
                            "_id": ObjectId(account_id)
                        },
                        {
                            "$inc": {
                                "balance": new_value
                            }
                        },
                        session=session
                    )



            flash(
                "Transaction updated successfully",
                "success"
            )


            return redirect(
                url_for(
                    "main.transaction_list"
                )
            )



        except Exception as e:

            flash(
                f"Error updating: {e}",
                "danger"
            )


            return redirect(
                url_for(
                    "main.edit_transaction",
                    id=id
                )
            )

    # ===================================================
    # GET DATA
    # ===================================================

    # Accounts
    accounts = list(
        mongo.db.accounts.find(
            {
                "user_id": user_oid
            }
        )
    )

    for acc in accounts:
        acc["_id"] = str(acc["_id"])

        if "user_id" in acc:
            acc["user_id"] = str(acc["user_id"])

    # Categories
    categories_raw = list(
        mongo.db.categories.find(
            {
                "user_id": user_oid
            }
        )
    )

    categories = []

    for cat in categories_raw:

        cat["_id"] = str(cat["_id"])

        if "user_id" in cat:
            cat["user_id"] = str(cat["user_id"])

        items = cat.get("items", [])

        if isinstance(items, str):
            try:
                items = json.loads(items)
            except:
                items = []

        if isinstance(items, list):
            cat["items"] = [
                str(i).strip('[]"\' ')
                for i in items
            ]
        else:
            cat["items"] = []

        categories.append(
            clean_category(cat)
        )

    # Transaction
    transaction["_id"] = str(transaction["_id"])

    if "account_id" in transaction:
        transaction["account_id"] = str(transaction["account_id"])

    if "user_id" in transaction:
        transaction["user_id"] = str(transaction["user_id"])

    return render_template(
        "backend/pages/components/transactions/edit_transaction.html",
        transaction=transaction,
        accounts=accounts,
        categories=categories
    )



@bp.route("/delete-transaction/<id>")
@login_required
def delete_transaction(id):

    trx = mongo.db.transactions.find_one({
        "_id": ObjectId(id),
        "user_id": ObjectId(current_user.id)
    })

    if not trx:
        flash("Transaction not found.", "danger")
        return redirect(url_for("main.transaction_list"))

    amount = float(trx["amount"])

    # 🔥 REVERSE BALANCE
    if trx["transaction_type"] == "income":
        mongo.db.accounts.update_one(
            {"_id": trx["account_id"]},
            {"$inc": {"balance": -amount}}
        )
    else:
        mongo.db.accounts.update_one(
            {"_id": trx["account_id"]},
            {"$inc": {"balance": amount}}
        )

    # DELETE
    mongo.db.transactions.delete_one({
        "_id": ObjectId(id)
    })

    flash("Transaction deleted successfully.", "success")
    return redirect(url_for("main.transaction_list"))


@bp.route("/add-saving", methods=["GET", "POST"])
@login_required
def add_saving():

    # ==========================================
    # USER ID
    # ==========================================
    user_id = ObjectId(current_user.id)

    # ==========================================
    # USER ACCOUNTS
    # ==========================================
    accounts = list(
        mongo.db.accounts.find(
            {
                "user_id": user_id
            }
        )
    )

    if request.method == "POST":

        # ==========================================
        # FORM DATA
        # ==========================================
        title = request.form.get(
            "title",
            ""
        ).strip()

        description = request.form.get(
            "description",
            ""
        ).strip()

        target_amount = request.form.get(
            "target_amount",
            ""
        ).strip()

        account_id = request.form.get(
            "account_id",
            ""
        ).strip()

        start_date = request.form.get(
            "start_date",
            ""
        ).strip()

        maturity_date = request.form.get(
            "maturity_date",
            ""
        ).strip()

        status = request.form.get(
            "status",
            "active"
        ).strip().lower()

        # ==========================================
        # VALIDATION
        # ==========================================
        if not title:

            flash(
                "Saving title is required.",
                "danger"
            )

            return redirect(
                url_for("main.add_saving")
            )

        if not target_amount:

            flash(
                "Target amount is required.",
                "danger"
            )

            return redirect(
                url_for("main.add_saving")
            )

        if not account_id:

            flash(
                "Please select account.",
                "danger"
            )

            return redirect(
                url_for("main.add_saving")
            )

        # ==========================================
        # TARGET AMOUNT
        # ==========================================
        try:

            target_amount = float(
                Decimal(target_amount).quantize(
                    Decimal("0.01")
                )
            )

        except InvalidOperation:

            flash(
                "Invalid target amount.",
                "danger"
            )

            return redirect(
                url_for("main.add_saving")
            )

        if target_amount <= 0:

            flash(
                "Target amount must be greater than zero.",
                "danger"
            )

            return redirect(
                url_for("main.add_saving")
            )

        # ==========================================
        # ACCOUNT VALIDATION
        # ==========================================
        try:

            account = mongo.db.accounts.find_one(
                {
                    "_id": ObjectId(account_id),
                    "user_id": user_id
                }
            )

        except Exception:

            account = None

        if not account:

            flash(
                "Invalid account selected.",
                "danger"
            )

            return redirect(
                url_for("main.add_saving")
            )

        # ==========================================
        # DATE CONVERSION
        # ==========================================
        try:

            if start_date:

                start_date = datetime.strptime(
                    start_date,
                    "%Y-%m-%d"
                )

            else:

                start_date = datetime.utcnow()

        except:

            start_date = datetime.utcnow()

        try:

            if maturity_date:

                maturity_date = datetime.strptime(
                    maturity_date,
                    "%Y-%m-%d"
                )

            else:

                maturity_date = None

        except:

            maturity_date = None

        # ==========================================
        # STATUS VALIDATION
        # ==========================================
        if status not in [
            "active",
            "completed",
            "paused"
        ]:

            status = "active"

        # ==========================================
        # CREATE MODEL
        # ==========================================
        saving = Saving()

        data = saving.add(
            user_id=current_user.id,
            title=title,
            description=description,
            target_amount=target_amount,
            account_id=ObjectId(account_id),
            start_date=start_date,
            maturity_date=maturity_date,
            status=status
        )

        # ==========================================
        # MONGODB TYPES
        # ==========================================
        data["user_id"] = user_id
        data["account_id"] = ObjectId(account_id)
        data["target_amount"] = target_amount
        data["current_balance"] = 0.00
        data["status"] = status
        data["created_at"] = datetime.utcnow()
        data["updated_at"] = datetime.utcnow()

        # ==========================================
        # INSERT
        # ==========================================
        mongo.db.savings.insert_one(
            data
        )

        flash(
            "Saving goal created successfully.",
            "success"
        )

        return redirect(
            url_for("main.saving_list")
        )

    return render_template(
        "backend/pages/components/savings/add_saving.html",
        accounts=accounts
    )


@bp.route("/savings")
@login_required
def saving_list():


    user_id = ObjectId(current_user.id)



    # ============================
    # ACCOUNTS
    # ============================

    accounts = list(
        mongo.db.accounts.find(
            {
                "user_id": user_id,
                "status": True
            }
        )
        .sort(
            "created_at",
            -1
        )
    )




    # ============================
    # ACCOUNT MAP
    # ============================

    account_map = {

        str(account["_id"]):
        account.get("name","Unknown")

        for account in accounts

    }





    # ============================
    # SAVINGS
    # ============================

    savings = list(
        mongo.db.savings.find(
            {
                "user_id": user_id
            }
        )
        .sort(
            "created_at",
            -1
        )
    )





    # ============================
    # SAVING DETAILS
    # ============================

    for saving in savings:



        saving["account_name"] = account_map.get(

            str(
                saving.get("account_id")
            ),

            "No Account"

        )



        target = float(
            saving.get(
                "target_amount",
                0
            )
        )



        current = float(
            saving.get(
                "current_balance",
                0
            )
        )




        if target > 0:


            saving["progress"] = round(

                (current / target) * 100,

                2

            )


        else:

            saving["progress"] = 0





        # convert ObjectId for JS/Jinja

        saving["_id"] = str(
            saving["_id"]
        )





    return render_template(

        "backend/pages/components/savings/all_savings.html",

        savings=savings,

        accounts=accounts

    )



