# ============================================================
# AI SAFE FLOAT
# ============================================================

def ai_safe_float(value, default=0.0):

    try:

        if value is None:
            return default

        if isinstance(value, bool):
            return default

        return float(value)

    except Exception:

        return default


# ============================================================
# AI OBJECT ID
# ============================================================

def ai_to_object_id(value):

    try:

        if isinstance(value, ObjectId):
            return value

        if value is None:
            return None

        value = str(value).strip()

        if not value:
            return None

        if ObjectId.is_valid(value):

            return ObjectId(value)

    except Exception:
        pass

    return None


# ============================================================
# CURRENT USER ID
# ============================================================

def ai_get_current_user_id():

    try:

        if not current_user:

            return None

        user_id = getattr(
            current_user,
            "id",
            None
        )

        if not user_id:

            user_id = getattr(
                current_user,
                "get_id",
                lambda: None
            )()

        if not user_id:

            return None

        return str(user_id)

    except Exception:

        return None


# ============================================================
# USER IDS
#
# MongoDB may contain:
#
# user_id: ObjectId(...)
#
# OR
#
# user_id: "ObjectId string"
#
# ============================================================

def ai_get_user_ids():

    user_id = ai_get_current_user_id()

    if not user_id:
        return []

    ids = []

    # String
    ids.append(str(user_id))

    # ObjectId
    object_id = ai_to_object_id(user_id)

    if object_id:

        ids.append(object_id)

    # Remove duplicates
    unique_ids = []

    for item in ids:

        if item not in unique_ids:

            unique_ids.append(item)

    return unique_ids


# ============================================================
# SAFE TEXT
# ============================================================

def ai_clean_text(value):

    if value is None:
        return ""

    try:

        value = str(value)

    except Exception:

        return ""

    value = value.strip()

    # Remove excessive whitespace
    value = re.sub(
        r"\s+",
        " ",
        value
    )

    return value[:10000]


# ============================================================
# DATETIME → STRING
# ============================================================

def ai_date_to_string(value):

    if value is None:

        return None

    try:

        if isinstance(value, datetime):

            return value.isoformat()

        if isinstance(value, date):

            return value.isoformat()

        return str(value)

    except Exception:

        return str(value)


# ============================================================
# DATETIME FORMAT
# ============================================================

def ai_format_datetime(value):

    if not value:

        return None

    try:

        if isinstance(value, datetime):

            dt = value

        else:

            text = str(value).strip()

            if text.endswith("Z"):

                text = text[:-1] + "+00:00"

            dt = datetime.fromisoformat(
                text
            )

        # UTC
        if dt.tzinfo is not None:

            dt = dt.astimezone(
                timezone.utc
            )

        return dt.strftime(
            "%d %B %Y, %I:%M %p UTC"
        )

    except Exception:

        return str(value)


# ============================================================
# SAFE JSON
# ============================================================

def ai_json(value):

    try:

        return json.dumps(
            value,
            ensure_ascii=False,
            default=str
        )

    except Exception:

        return "{}"


